const App = () => {
    const [view, setView] = useState('dashboard');
    const [vehicles, setVehicles] = useState<Vehicle[]>([]);
    const [logs, setLogs] = useState<LogEntry[]>([]);
    const [orders, setOrders] = useState<Order[]>([]);
    const [loading, setLoading] = useState(true);

    // Modal States
    const [vehicleModal, setVehicleModal] = useState({ open: false, data: null as Vehicle | null });
    const [entryModal, setEntryModal] = useState({ open: false, data: null as LogEntry | null });
    const [orderModal, setOrderModal] = useState({ open: false, data: null as Order | null });

    // Load Data
    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const [v, l, o] = await Promise.all([
                api.get('/vehicles'),
                api.get('/logs'),
                api.get('/orders')
            ]);
            setVehicles(v || []);
            setLogs(l || []);
            setOrders(o || []);
        } catch (e) {
            console.error(e);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => { loadData(); }, [loadData]);

    // Handlers
    const saveVehicle = async (v: Vehicle) => {
        if(v.id && vehicles.find(x => x.id === v.id)) {
             await api.put(`/vehicles/${v.id}`, v);
        } else {
             await api.post('/vehicles', v);
        }
        setVehicleModal({ open: false, data: null });
        loadData();
    };

    const deleteVehicle = async (id: string) => {
        if(confirm('Fahrzeug wirklich löschen?')) {
            await api.delete(`/vehicles/${id}`);
            loadData();
        }
    };

    const saveEntry = async (entries: any[]) => {
        for (const entry of entries) {
            if(entry.id && logs.find(x => x.id === entry.id)) {
                await api.put(`/logs/${entry.id}`, entry);
            } else {
                await api.post('/logs', entry);
            }
        }
        setEntryModal({ open: false, data: null });
        loadData();
    };

    const completeLog = async (log: LogEntry) => {
        if(confirm('Aufgabe als erledigt markieren?')) {
             await api.put(`/logs/${log.id}`, { ...log, status: 'DONE', dateCompleted: getTodayDate() });
             loadData();
        }
    };

    const deleteLog = async (id: string) => {
        if(confirm('Eintrag löschen?')) {
            await api.delete(`/logs/${id}`);
            loadData();
        }
    };

    const saveOrder = async (ordersList: any[]) => {
        for (const o of ordersList) {
             if(o.id && orders.find(x => x.id === o.id)) {
                await api.put(`/orders/${o.id}`, o);
            } else {
                await api.post('/orders', o);
            }
        }
        setOrderModal({ open: false, data: null });
        loadData();
    };

    const updateOrderStatus = async (id: string, status: OrderStatus) => {
        const order = orders.find(o => o.id === id);
        if(order) {
            await api.put(`/orders/${id}`, { ...order, status });
            loadData();
        }
    };

    const deleteOrder = async (id: string) => {
        if(confirm('Bestellung löschen?')) {
            await api.delete(`/orders/${id}`);
            loadData();
        }
    };

    return (
