  nextHU?: string;
  nextSP?: string;
  nextUVV?: string;
  nextTacho?: string;

  currentMileage?: number; // KM or Hours
}

interface LogEntry {
  id: string;
  vehicleId: string;
  type: string; // Generic 'Aufgabe'
  description: string;
  priority: Priority;
  dateAdded: string; // ISO Date
  dateCompleted?: string;
  status: 'OPEN' | 'DONE';
  mileage?: number;

  // Specific for inspections
  inspectionType?: 'HU' | 'SP' | 'UVV' | 'Tacho';

  // Attachments
  attachments?: Attachment[];
}

interface Order {
  id: string;
  description: string;
  vehicleId?: string;
  dateAdded: string;
  status: OrderStatus;
}

