const DashboardView = ({ logs, vehicles = [], onComplete, onEdit, onDelete, onAdd }: any) => {
  const safeVehicles = Array.isArray(vehicles) ? vehicles : [];
  const openLogs = logs.filter((l: LogEntry) => l.status !== 'DONE');

  const sortedLogs = useMemo(() => {
    return [...openLogs].sort((a, b) => {
      const vA = safeVehicles.find(v => v.id === a.vehicleId);
      const vB = safeVehicles.find(v => v.id === b.vehicleId);
      const lpA = vA?.licensePlate || 'ZZZ_Allgemein';
      const lpB = vB?.licensePlate || 'ZZZ_Allgemein';

      // 1. Sort by License Plate (Alphabetical)
      const plateCompare = lpA.localeCompare(lpB);
      if (plateCompare !== 0) return plateCompare;

      // 2. Sort by Priority (High -> Normal -> Low)
      const pA = getPrioritySortValue(a.priority);
      const pB = getPrioritySortValue(b.priority);
      return pA - pB;
    });
  }, [openLogs, safeVehicles]);

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-gray-800">Offene Aufgaben</h2>
