        {sortedLogs.length === 0 && <div className="text-gray-500 text-center py-8">Keine offenen Aufgaben.</div>}
        {sortedLogs.map((log: LogEntry) => {
          const vehicle = safeVehicles.find((v: Vehicle) => v.id === log.vehicleId);
          return (
            <div key={log.id} className="bg-white p-4 rounded shadow-sm border-l-4 border-l-blue-500 flex justify-between items-start">
              <div className="flex-1">
                {/* Header: License Plate + Priority */}
                <div className="flex items-center gap-2 mb-2">
                    <span className="font-bold text-lg text-gray-800 bg-gray-100 px-2 py-0.5 rounded border border-gray-200">
                        {vehicle?.licensePlate || 'Allgemein'}
                    </span>
                    <span className={`px-2 py-0.5 rounded text-xs font-bold uppercase tracking-wider ${
                        log.priority === Priority.HIGH ? 'bg-red-100 text-red-800 border border-red-200' : 
                        log.priority === Priority.LOW ? 'bg-gray-100 text-gray-600 border border-gray-200' : 
                        'bg-blue-50 text-blue-800 border border-blue-100'
                    }`}>
                        {log.priority}
                    </span>
                </div>

                {/* Body: Description */}
                <div className="text-gray-700 whitespace-pre-wrap">{log.description}</div>

                <div className="text-xs text-gray-400 mt-2">Erstellt: {log.dateAdded}</div>
