                <button onClick={() => onEdit(log)} className="p-2 text-blue-600 hover:bg-blue-50 rounded" title="Bearbeiten"><Icons.Edit /></button>
                <button onClick={() => onDelete(log.id)} className="p-2 text-red-600 hover:bg-red-50 rounded" title="Löschen"><Icons.Trash /></button>
              </div>
