const EntryModal = ({ isOpen, onClose, entry, vehicles, onSave }: any) => {
    const [header, setHeader] = useState({
        vehicleId: '',
        dateAdded: getTodayDate(),
    });

    const [items, setItems] = useState<{description: string, priority: Priority}[]>([]);

    const groupedVehicles = useMemo(() => groupVehiclesByType(vehicles), [vehicles]);

    const vehicleTypes = useMemo(() => {
        return Object.keys(groupedVehicles).sort((a, b) => getVehicleTypePriority(a) - getVehicleTypePriority(b));
    }, [groupedVehicles]);

    useEffect(() => { 
        if(isOpen) {
            if (entry) {
                setHeader({
                    vehicleId: entry.vehicleId,
                    dateAdded: entry.dateAdded,
                });
                setItems([{ description: entry.description, priority: entry.priority }]);
            } else {
                setHeader({
                    vehicleId: vehicles[0]?.id || '',
                    dateAdded: getTodayDate(),
                });
                setItems([{ description: '', priority: Priority.NORMAL }]);
            }
        }
    }, [entry, isOpen, vehicles]);

    const handleSave = () => {
        // Simplified: Everything is just a generic task
        const type = 'Aufgabe';

        const newEntries = items.map(item => ({
            ...(entry ? { id: entry.id } : {}),
            vehicleId: header.vehicleId,
            dateAdded: header.dateAdded,
            type: type,
            description: item.description,
            priority: item.priority,
            status: entry ? entry.status : 'OPEN'
        }));

        const validEntries = newEntries.filter(e => e.description.trim() !== '');
        if(validEntries.length === 0) return;

        onSave(validEntries);
    };

    const updateItem = (index: number, field: string, value: any) => {
        const newItems = [...items];
        // @ts-ignore
        newItems[index][field] = value;
        setItems(newItems);
    };

    const removeItem = (index: number) => {
        setItems(items.filter((_, i) => i !== index));
    };

    const addItem = () => {
        setItems([...items, { description: '', priority: Priority.NORMAL }]);
    };

    return (
        <ModalOverlay isOpen={isOpen} onClose={onClose} maxWidth="max-w-4xl">
             <div className="p-6">
                <h3 className="text-xl font-bold mb-4">{entry ? 'Auftrag bearbeiten' : 'Neuer Auftrag'}</h3>

                <div className="flex gap-4 mb-4 items-start">
                    <div className="flex flex-col gap-1 w-1/2">
                        <label className="text-sm font-bold text-gray-700">Kennzeichen</label>
                        <div className="relative border border-gray-400 p-1 rounded bg-white">
                            <select 
                                className="w-full bg-transparent outline-none appearance-none pr-4" 
                                value={header.vehicleId} 
                                onChange={e => setHeader({...header, vehicleId: e.target.value})}
                            >
                                <option value="">Wählen...</option>
                                {vehicleTypes.map(type => (
                                    <optgroup key={type} label={type}>
                                        {groupedVehicles[type].map(v => (
                                            <option key={v.id} value={v.id}>{v.licensePlate}</option>
                                        ))}
                                    </optgroup>
                                ))}
                            </select>
                            <span className="absolute right-2 top-1 pointer-events-none text-gray-500 text-xs">▼</span>
                        </div>
                    </div>
                    <div className="flex flex-col gap-1 w-1/2">
                        <label className="text-sm font-bold text-gray-700">Datum</label>
                        <div className="relative border border-gray-400 p-1 rounded bg-white">
                             <input 
                                type="date"
                                className="w-full bg-transparent outline-none" 
                                value={header.dateAdded} 
                                onChange={e => setHeader({...header, dateAdded: e.target.value})} 
                             />
                        </div>
                    </div>
                </div>

                <div className="space-y-3 max-h-[50vh] overflow-y-auto pr-1">
                    {items.map((item, idx) => (
                        <div key={idx} className="flex gap-2 items-start group">
                            <div className="border border-gray-400 p-3 flex-1 rounded bg-white shadow-sm">
                                <textarea 
                                    className="w-full border border-gray-300 p-2 rounded mb-2 outline-none focus:border-blue-500 text-sm min-h-[5rem] resize-y" 
                                    placeholder="Beschreibung des Auftrags" 
                                    value={item.description} 
                                    onChange={e => updateItem(idx, 'description', e.target.value)} 
                                />
                                <div className="flex gap-3 items-center text-sm">
                                    <span className="font-bold text-gray-600 mr-1">Priorität:</span>
                                    <PriorityCheckbox 
                                        label="normal" 
                                        checked={item.priority === Priority.NORMAL} 
                                        onChange={() => updateItem(idx, 'priority', Priority.NORMAL)} 
                                    />
                                    <PriorityCheckbox 
                                        label="dringend" 
                                        checked={item.priority === Priority.HIGH} 
                                        onChange={() => updateItem(idx, 'priority', Priority.HIGH)} 
                                    />
                                    <PriorityCheckbox 
                                        label="niedrig" 
                                        checked={item.priority === Priority.LOW} 
                                        onChange={() => updateItem(idx, 'priority', Priority.LOW)} 
                                    />
                                </div>
                            </div>
                            {items.length > 1 && (
                                <button onClick={() => removeItem(idx)} className="mt-4 text-gray-400 hover:text-red-600 transition-colors">
                                    <Icons.Trash />
                                </button>
                            )}
                        </div>
                    ))}
                </div>

                <button onClick={addItem} className="w-full border-2 border-dashed border-gray-300 text-gray-500 py-2 mt-4 text-sm font-bold hover:bg-gray-50 hover:border-gray-400 hover:text-gray-700 transition-colors rounded">
                    Neuen Auftrag hinzufügen
                </button>

                <div className="mt-8 flex justify-end gap-3">
                    <button onClick={onClose} className="px-5 py-2 text-gray-600 hover:bg-gray-100 rounded font-medium">Abbrechen</button>
                    <button onClick={() => handleSave()} className="border border-gray-400 px-6 py-2 bg-white hover:bg-gray-100 font-bold rounded shadow-sm text-gray-800">
                        Speichern
                    </button>
                </div>
            </div>
        </ModalOverlay>
    );
};

