          <input 
             type="text" 
             placeholder="Suchen..." 
             className="border rounded pl-8 pr-2 py-1" 
             value={filter} 
             onChange={e => setFilter(e.target.value)}
          />
          <span className="absolute left-2 top-2 text-gray-400"><Icons.Filter /></span>
        </div>
      </div>
      <div className="bg-white rounded shadow overflow-hidden">
        {completedLogs.map((l: LogEntry) => (
           <div key={l.id} className="p-4 border-b hover:bg-gray-50">
             <div className="flex justify-between">
               <div className="font-bold whitespace-pre-wrap">{l.description}</div>
               <div className="text-xs text-gray-400">{l.dateCompleted}</div>
             </div>
             <div className="text-sm text-gray-600 mt-1">
               {safeVehicles.find((v:Vehicle) => v.id === l.vehicleId)?.licensePlate}
             </div>
             {isAdmin && (
               <div className="mt-2 flex gap-2 justify-end">
                 <button onClick={() => onEdit(l)} className="text-xs text-blue-600 underline">Bearbeiten</button>
                 <button onClick={() => onDelete(l.id)} className="text-xs text-red-600 underline">Löschen</button>
               </div>
             )}
           </div>
        ))}
      </div>
    </div>
  );
};

