  AUFLIEGER = 'Auflieger',
  SONSTIGE = 'Sonstige',
  MASCHINE = 'Maschine'
}

enum Priority {
  LOW = 'Niedrig',
  NORMAL = 'Normal',
  HIGH = 'Dringend',
}

enum OrderStatus {
  OFFEN = 'Offen',
  BESTELLT = 'Bestellt',
