const OrderModal = ({ isOpen, onClose, order, onSave, vehicles }: any) => {
    const [header, setHeader] = useState({
        vehicleId: '',
        dateAdded: getTodayDate()
    });

    const [items, setItems] = useState<{description: string, priority: string}[]>([]);

    const groupedVehicles = useMemo(() => groupVehiclesByType(vehicles), [vehicles]);

    const vehicleTypes = useMemo(() => {
        return Object.keys(groupedVehicles).sort((a, b) => getVehicleTypePriority(a) - getVehicleTypePriority(b));
    }, [groupedVehicles]);

    useEffect(() => { 
        if(isOpen) {
             if (order) {
                setHeader({
                    vehicleId: order.vehicleId || '',
                    dateAdded: order.dateAdded,
                });
                let desc = order.description;
                let prio = 'normal';
                if(desc.includes('[Dringend]')) { prio = 'dringend'; desc = desc.replace('[Dringend]', '').trim(); }
                if(desc.includes('[Niedrig]')) { prio = 'niedrig'; desc = desc.replace('[Niedrig]', '').trim(); }

                setItems([{ description: desc, priority: prio }]);
            } else {
                setHeader({
                    vehicleId: vehicles[0]?.id || '',
                    dateAdded: getTodayDate(),
                });
                setItems([{ description: '', priority: 'normal' }]);
            }
        } 
    }, [order, isOpen, vehicles]);

    const handleSave = () => {
        const newOrders = items.map(item => {
            let desc = item.description;
            if(item.priority === 'dringend') desc += ' [Dringend]';
            if(item.priority === 'niedrig') desc += ' [Niedrig]';

            return {
                ...(order ? { id: order.id } : {}),
                vehicleId: header.vehicleId,
                dateAdded: header.dateAdded,
                description: desc,
                status: order ? order.status : OrderStatus.OFFEN
            };
        });

        const validOrders = newOrders.filter(o => o.description.trim() !== '');
        if(validOrders.length === 0) return;

        onSave(validOrders);
    };

    const updateItem = (index: number, field: string, value: any) => {
        const newItems = [...items];
        // @ts-ignore
        newItems[index][field] = value;
        setItems(newItems);
    };

    const removeItem = (index: number) => {
        setItems(items.filter((_, i) => i !== index));
    };

    const addItem = () => {
        setItems([...items, { description: '', priority: 'normal' }]);
    };

    return (
        <ModalOverlay isOpen={isOpen} onClose={onClose} maxWidth="max-w-4xl">
            <div className="p-6">
                <h3 className="text-xl font-bold mb-4">{order ? 'Bestellung bearbeiten' : 'Neue Bestellung'}</h3>

                <div className="flex gap-4 mb-6 items-start">
                    <div className="flex flex-col gap-1 w-1/2">
                        <label className="text-sm font-bold text-gray-700">Kennzeichen</label>
                        <div className="relative border border-gray-400 p-1 rounded bg-white">
                            <select 
                                className="w-full bg-transparent outline-none appearance-none pr-4" 
                                value={header.vehicleId} 
                                onChange={e => setHeader({...header, vehicleId: e.target.value})}
                            >
                                <option value="">Lager/Allgemein</option>
                                {vehicleTypes.map(type => (
                                    <optgroup key={type} label={type}>
                                        {groupedVehicles[type].map(v => (
                                            <option key={v.id} value={v.id}>{v.licensePlate}</option>
                                        ))}
                                    </optgroup>
                                ))}
                            </select>
                            <span className="absolute right-2 top-1 pointer-events-none text-gray-500 text-xs">▼</span>
                        </div>
                    </div>
                    <div className="flex flex-col gap-1 w-1/2">
                        <label className="text-sm font-bold text-gray-700">Datum</label>
                        <div className="relative border border-gray-400 p-1 rounded bg-white">
                             <input 
                                type="date"
                                className="w-full bg-transparent outline-none" 
                                value={header.dateAdded} 
                                onChange={e => setHeader({...header, dateAdded: e.target.value})} 
                             />
                        </div>
                    </div>
                </div>

                <div className="space-y-3 max-h-[50vh] overflow-y-auto pr-1">
                    {items.map((item, idx) => (
                        <div key={idx} className="flex gap-2 items-start group">
                            <div className="border border-gray-400 p-3 flex-1 rounded bg-white shadow-sm">
                                <textarea 
                                    className="w-full border border-gray-300 p-2 rounded mb-2 outline-none focus:border-blue-500 text-sm min-h-[5rem] resize-y" 
                                    placeholder="Artikel / Beschreibung" 
                                    value={item.description} 
                                    onChange={e => updateItem(idx, 'description', e.target.value)} 
                                />
                                <div className="flex gap-3 items-center text-sm">
                                    <span className="font-bold text-gray-600 mr-1">Priorität:</span>
                                    <PriorityCheckbox 
                                        label="normal" 
                                        checked={item.priority === 'normal'} 
                                        onChange={() => updateItem(idx, 'priority', 'normal')} 
                                    />
                                    <PriorityCheckbox 
                                        label="dringend" 
                                        checked={item.priority === 'dringend'} 
                                        onChange={() => updateItem(idx, 'priority', 'dringend')} 
                                    />
                                    <PriorityCheckbox 
                                        label="niedrig" 
                                        checked={item.priority === 'niedrig'} 
                                        onChange={() => updateItem(idx, 'priority', 'niedrig')} 
                                    />
                                </div>
                            </div>
                            {items.length > 1 && (
                                <button onClick={() => removeItem(idx)} className="mt-4 text-gray-400 hover:text-red-600 transition-colors">
                                    <Icons.Trash />
                                </button>
                            )}
                        </div>
                    ))}
                </div>

                <button onClick={addItem} className="w-full border-2 border-dashed border-gray-300 text-gray-500 py-2 mt-4 text-sm font-bold hover:bg-gray-50 hover:border-gray-400 hover:text-gray-700 transition-colors rounded">
                    Neue Position hinzufügen
                </button>

                <div className="mt-8 flex justify-end gap-3">
                    <button onClick={onClose} className="px-5 py-2 text-gray-600 hover:bg-gray-100 rounded font-medium">Abbrechen</button>
                    <button onClick={() => handleSave()} className="border border-gray-400 px-6 py-2 bg-white hover:bg-gray-100 font-bold rounded shadow-sm text-gray-800">
                        Speichern
                    </button>
                </div>
            </div>
        </ModalOverlay>
    );
};

const App = () => {
    const [view, setView] = useState('dashboard');
    const [vehicles, setVehicles] = useState<Vehicle[]>([]);
    const [logs, setLogs] = useState<LogEntry[]>([]);
    const [orders, setOrders] = useState<Order[]>([]);
    const [loading, setLoading] = useState(true);

    // Modal States
    const [vehicleModal, setVehicleModal] = useState({ open: false, data: null as Vehicle | null });
    const [entryModal, setEntryModal] = useState({ open: false, data: null as LogEntry | null });
    const [orderModal, setOrderModal] = useState({ open: false, data: null as Order | null });
    const [inspectionModal, setInspectionModal] = useState({ open: false, data: null as LogEntry | null });

    // Load Data
    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const [v, l, o] = await Promise.all([
                api.get('/vehicles'),
                api.get('/logs'),
                api.get('/orders')
            ]);
            setVehicles(v || []);
            setLogs(l || []);
            setOrders(o || []);
        } catch (e) {
            console.error(e);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => { loadData(); }, [loadData]);

    // Handlers
    const saveVehicle = async (v: Vehicle) => {
        if(v.id && vehicles.find(x => x.id === v.id)) {
             await api.put(`/vehicles/${v.id}`, v);
        } else {
             await api.post('/vehicles', v);
        }
        setVehicleModal({ open: false, data: null });
        loadData();
    };

    const deleteVehicle = async (id: string) => {
        if(confirm('Fahrzeug wirklich löschen?')) {
            await api.delete(`/vehicles/${id}`);
            loadData();
        }
    };

    const saveEntry = async (entries: any[]) => {
        for (const entry of entries) {
            if(entry.id && logs.find(x => x.id === entry.id)) {
                await api.put(`/logs/${entry.id}`, entry);
            } else {
                await api.post('/logs', entry);
            }
        }
        setEntryModal({ open: false, data: null });
        loadData();
    };

    // Updated generic handler for status changes (In Progress, Done, etc.)
    const updateLogStatus = async (log: LogEntry, newStatus: 'IN_PROGRESS' | 'DONE') => {
        const updateData: any = { ...log, status: newStatus };
        if(newStatus === 'DONE') {
             updateData.dateCompleted = getTodayDate();
        }
        await api.put(`/logs/${log.id}`, updateData);
        loadData();
    };

    const completeInspection = async (log: LogEntry, nextDate: string) => {
        // 1. Create a DONE log for the inspection
        // Note: nextDate comes as YYYY-MM from input type="month", save as string
        // The log itself is the "record" of the inspection.
        const vehicle = vehicles.find(v => v.id === log.vehicleId);

        // Convert YYYY-MM back to MM/YYYY for storage if needed, but standardizing on what backend expects
        const [y, m] = nextDate.split('-');
        const nextDateStorage = `${m}/${y}`;

        await api.post('/logs', {
            vehicleId: log.vehicleId,
            type: 'Wartung',
            description: `${log.inspectionType} Prüfung durchgeführt`,
            priority: Priority.NORMAL,
            dateAdded: getTodayDate(),
            status: 'DONE',
            dateCompleted: getTodayDate(),
            inspectionType: log.inspectionType
        });

        // 2. Update Vehicle Next Date
        if (vehicle) {
            const updateKey = `next${log.inspectionType}`;
            const updatedVehicle = { ...vehicle, [updateKey]: nextDateStorage };
            await api.put(`/vehicles/${vehicle.id}`, updatedVehicle);
        }

        setInspectionModal({ open: false, data: null });
        loadData();
    };

    const deleteLog = async (id: string) => {
        if(confirm('Eintrag löschen?')) {
            await api.delete(`/logs/${id}`);
            loadData();
        }
    };

    const saveOrder = async (ordersList: any[]) => {
        for (const o of ordersList) {
             if(o.id && orders.find(x => x.id === o.id)) {
                await api.put(`/orders/${o.id}`, o);
            } else {
                await api.post('/orders', o);
            }
        }
        setOrderModal({ open: false, data: null });
        loadData();
    };

    const updateOrderStatus = async (id: string, status: OrderStatus) => {
        const order = orders.find(o => o.id === id);
        if(order) {
            await api.put(`/orders/${id}`, { ...order, status });
            loadData();
        }
    };

    const deleteOrder = async (id: string) => {
        if(confirm('Bestellung löschen?')) {
            await api.delete(`/orders/${id}`);
            loadData();
        }
    };

    // Couple / Uncouple Logic
    const coupleVehicles = async (motorId: string, trailerId: string) => {
        const motor = vehicles.find(v => v.id === motorId);
        const trailer = vehicles.find(v => v.id === trailerId);
        if(motor && trailer) {
            await api.put(`/vehicles/${motor.id}`, { ...motor, coupledVehicleId: trailer.id });
            await api.put(`/vehicles/${trailer.id}`, { ...trailer, coupledVehicleId: motor.id });
            loadData();
        }
    };

    const uncoupleVehicles = async (motorId: string, trailerId: string) => {
        const motor = vehicles.find(v => v.id === motorId);
        if(motor) await api.put(`/vehicles/${motor.id}`, { ...motor, coupledVehicleId: null });

        if(trailerId) {
            const trailer = vehicles.find(v => v.id === trailerId);
            if(trailer) await api.put(`/vehicles/${trailer.id}`, { ...trailer, coupledVehicleId: null });
        }
        loadData();
    };

    return (
        <div className="flex h-full bg-gray-100 font-sans text-gray-900">
            {/* Sidebar */}
            <div className="w-64 bg-slate-800 text-white flex flex-col shadow-xl z-10 no-print">
                <div className="p-6 border-b border-slate-700">
                    <h1 className="text-xl font-bold tracking-tight">Fuhrpark<span className="text-blue-400">Manager</span></h1>
                </div>
                <nav className="flex-1 p-4 space-y-2">
                    <NavButton icon={<Icons.Dashboard />} label="Dashboard" active={view === 'dashboard'} onClick={() => setView('dashboard')} />
                    <NavButton icon={<Icons.Calendar />} label="Termine" active={view === 'appointments'} onClick={() => setView('appointments')} />
                    <NavButton icon={<Icons.ShoppingCart />} label="Bestellungen" active={view === 'orders'} onClick={() => setView('orders')} />
                    <NavButton icon={<Icons.History />} label="Historie" active={view === 'history'} onClick={() => setView('history')} />
                    <NavButton icon={<Icons.Link />} label="Gespanne" active={view === 'combinations'} onClick={() => setView('combinations')} />
                    <NavButton icon={<Icons.Truck />} label="Fahrzeuge" active={view === 'vehicles'} onClick={() => setView('vehicles')} />
                </nav>
                <div className="p-4 border-t border-slate-700 text-xs text-slate-400">
                    v2.1.0 • {isOfflineMode ? 'Offline Mode' : 'Online'}
                </div>
            </div>

            {/* Main Content */}
            <div className="flex-1 flex flex-col h-full overflow-hidden">
                <header className="bg-white shadow-sm border-b px-8 py-4 flex justify-between items-center no-print">
                     <h2 className="text-xl font-bold text-gray-800 capitalize">{view === 'dashboard' ? 'Übersicht' : view}</h2>
                     <div className="flex gap-2">
                         <button onClick={loadData} className="p-2 text-gray-500 hover:bg-gray-100 rounded" title="Refresh">
                            <Icons.History /> {/* Using history icon as refresh roughly */}
                         </button>
                     </div>
                </header>

                <main className="flex-1 overflow-auto p-8">
                    <ErrorBoundary>
                        {loading ? (
                            <div className="flex justify-center items-center h-full text-gray-400">Laden...</div>
                        ) : (
                            <>
                                {view === 'dashboard' && <DashboardView logs={logs} vehicles={vehicles} onAdd={() => setEntryModal({open:true, data:null})} onInspect={(l:any) => setInspectionModal({open: true, data: l})} onStatusUpdate={updateLogStatus} onEdit={(l:any) => setEntryModal({open:true, data:l})} onDelete={deleteLog} />}
                                {view === 'vehicles' && <VehicleListView vehicles={vehicles} onAdd={() => setVehicleModal({open:true, data:null})} onEdit={(v:any) => setVehicleModal({open:true, data:v})} onDelete={deleteVehicle} />}
                                {view === 'combinations' && <CombinationsView vehicles={vehicles} onCouple={coupleVehicles} onUncouple={uncoupleVehicles} />}
                                {view === 'appointments' && <AppointmentsView vehicles={vehicles} onComplete={(apt: any) => {
                                    setEntryModal({
                                        open: true, 
                                        data: {
                                            id: '', 
                                            vehicleId: apt.vid, 
                                            type: 'Wartung', 
                                            description: `${apt.inspectionType} Prüfung durchgeführt`, 
                                            priority: Priority.NORMAL, 
                                            dateAdded: getTodayDate(), 
                                            status: 'DONE',
                                            inspectionType: apt.inspectionType
                                        } as LogEntry
                                    });
                                }} />}
                                {view === 'orders' && <OrdersView orders={orders} vehicles={vehicles} onAdd={() => setOrderModal({open:true, data:null})} onEdit={(o:any) => setOrderModal({open:true, data:o})} onStatusChange={updateOrderStatus} onDelete={deleteOrder} />}
                                {view === 'history' && <HistoryView logs={logs} vehicles={vehicles} isAdmin={true} onEdit={(l:any) => setEntryModal({open:true, data:l})} onDelete={deleteLog} />}
                            </>
                        )}
                    </ErrorBoundary>
                </main>
            </div>

            {/* Modals */}
            <VehicleModal isOpen={vehicleModal.open} onClose={() => setVehicleModal({open:false, data:null})} vehicle={vehicleModal.data} allVehicles={vehicles} onSave={saveVehicle} />
            <EntryModal isOpen={entryModal.open} onClose={() => setEntryModal({open:false, data:null})} entry={entryModal.data} vehicles={vehicles} onSave={saveEntry} />
            <OrderModal isOpen={orderModal.open} onClose={() => setOrderModal({open:false, data:null})} order={orderModal.data} vehicles={vehicles} onSave={saveOrder} />
            <InspectionModal isOpen={inspectionModal.open} onClose={() => setInspectionModal({open:false, data:null})} log={inspectionModal.data} onSave={completeInspection} />
        </div>
    );
};

const NavButton = ({ icon, label, active, onClick }: any) => (
    <button 
        onClick={onClick}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded transition-colors font-medium ${active ? 'bg-blue-600 text-white shadow-md' : 'text-slate-300 hover:bg-slate-700 hover:text-white'}`}
    >
        {icon}
        <span>{label}</span>
    </button>
);

const container = document.getElementById('root');
const root = createRoot(container!);
root.render(<App />);

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { createRoot } from 'react-dom/client';

// --- TYPES & ENUMS ---

enum VehicleType {
  PKW = 'PKW',
  LKW = 'LKW',
  TRANSPORTER = 'Transporter',
  ANHAENGER = 'Anhänger',
  AUFLIEGER = 'Auflieger',
  SONSTIGE = 'Sonstige',
  MASCHINE = 'Maschine'
}

enum Priority {
  LOW = 'Niedrig',
  NORMAL = 'Normal',
  HIGH = 'Dringend',
}

enum OrderStatus {
  OFFEN = 'Offen',
  BESTELLT = 'Bestellt',
  ERLEDIGT = 'Erledigt',
}

interface Attachment {
  name: string;
  data: string; // Base64
  type: string;
}

interface Vehicle {
  id: string;
  licensePlate: string;
  type: VehicleType | string;
  manufacturer: string;
  model: string; // Typ
  vin: string;
  year: number;
  notes: string;
  coupledVehicleId?: string | null; // For LKW <-> Auflieger

  // Inspection Due Dates (MM/YYYY)
  nextHU?: string;
  nextSP?: string;
  nextUVV?: string;
  nextTacho?: string;

  currentMileage?: number; // KM or Hours
}

interface LogEntry {
  id: string;
  vehicleId: string;
  type: string; // Generic 'Aufgabe'
  description: string;
  priority: Priority;
  dateAdded: string; // ISO Date
  dateCompleted?: string;
  status: 'OPEN' | 'IN_PROGRESS' | 'DONE';
  mileage?: number;

  // Specific for inspections
  inspectionType?: 'HU' | 'SP' | 'UVV' | 'Tacho';

  // Attachments
  attachments?: Attachment[];

  // Frontend specific
  isVirtual?: boolean; // If true, this is a generated inspection task, not saved in DB yet
}

interface Order {
  id: string;
  description: string;
  vehicleId?: string;
  dateAdded: string;
  status: OrderStatus;
}

