const mockDB = {
  load: (key: string) => {
      try {
          return JSON.parse(localStorage.getItem(`fuhrpark_${key}`) || '[]');
      } catch (e) {
          console.error("MockDB Load Error", e);
          return [];
      }
  },
  save: (key: string, data: any) => localStorage.setItem(`fuhrpark_${key}`, JSON.stringify(data)),

  // Helpers to mimic API delays slightly for realism
  async get(collection: string) {
    return this.load(collection);
  },
  async post(collection: string, item: any) {
    const items = this.load(collection);
    const newItem = { ...item, id: Math.random().toString(36).substr(2, 9) };
    items.push(newItem);
    this.save(collection, items);
    return { success: true, id: newItem.id };
  },
  async put(collection: string, id: string, item: any) {
    const items = this.load(collection);
    const idx = items.findIndex((i:any) => i.id === id);
    if (idx !== -1) {
      items[idx] = item;
      this.save(collection, items);
    }
    return { success: true };
  },
  async delete(collection: string, id: string) {
    const items = this.load(collection);
    const filtered = items.filter((i:any) => i.id !== id);
    this.save(collection, filtered);
    return { success: true };
  }
};

