  LKW = 'LKW',
  TRANSPORTER = 'Transporter',
  ANHAENGER = 'Anhänger',
  AUFLIEGER = 'Auflieger',
  SONSTIGE = 'Sonstige',
  MASCHINE = 'Maschine'
}

enum Priority {
  LOW = 'Niedrig',
  NORMAL = 'Normal',
  HIGH = 'Dringend',
}

enum OrderStatus {
  OFFEN = 'Offen',
  BESTELLT = 'Bestellt',
  ERLEDIGT = 'Erledigt',
}

interface Attachment {
  name: string;
  data: string; // Base64
  type: string;
}

interface Vehicle {
  id: string;
  licensePlate: string;
  type: VehicleType | string;
  manufacturer: string;
  model: string; // Typ
  vin: string;
  year: number;
