// --- HELPER FUNCTIONS ---

const getTodayDate = () => new Date().toISOString().split('T')[0];
const isValidDateMMYYYY = (val: string) => /^\d{2}\/\d{4}$/.test(val);

// Convert "MM/YYYY" (Storage) to "YYYY-MM" (Input type="month")
const toInputFormat = (dateStr?: string) => {
    if (!dateStr) return '';
    const [m, y] = dateStr.split('/');
    if (!m || !y) return '';
    return `${y}-${m}`;
};

// Convert "YYYY-MM" (Input type="month") to "MM/YYYY" (Storage)
const fromInputFormat = (dateStr: string) => {
    if (!dateStr) return '';
    const [y, m] = dateStr.split('-');
    return `${m}/${y}`;
};

const parseDateMMYYYY = (dateStr?: string) => {
    if (!dateStr) return 0;
    const parts = dateStr.split('/');
    if (parts.length < 2) return 0;
    const [m, y] = parts;
    if (!m || !y) return 0;
    return new Date(parseInt(y), parseInt(m)-1).getTime();
};

const getVehicleTypePriority = (type: string) => {
    switch(type) {
        case VehicleType.LKW: return 1;
        case VehicleType.TRANSPORTER: return 2;
        case VehicleType.PKW: return 3;
        case VehicleType.ANHAENGER: return 4;
        case VehicleType.AUFLIEGER: return 5;
        case VehicleType.MASCHINE: return 6;
        case VehicleType.SONSTIGE: return 7;
        default: return 99;
    }
}

const getPrioritySortValue = (p: string) => {
    if (p === Priority.HIGH || (typeof p === 'string' && p.includes('Dringend'))) return 0;
    if (p === Priority.LOW || (typeof p === 'string' && p.includes('Niedrig'))) return 2;
    return 1; // Normal
};

const sortVehicles = (vehicles: Vehicle[]) => {
  return [...vehicles].sort((a, b) => {
    // @ts-ignore
    if (a.type !== b.type) {
        // @ts-ignore
        return getVehicleTypePriority(a.type) - getVehicleTypePriority(b.type);
    }
    return a.licensePlate.localeCompare(b.licensePlate);
  });
};

const groupVehiclesByType = (vehicles: Vehicle[]) => {
    const sorted = sortVehicles(vehicles);
    const groups: { [key: string]: Vehicle[] } = {};
    sorted.forEach(v => {
        // @ts-ignore
        if(!groups[v.type]) groups[v.type] = [];
        // @ts-ignore
        groups[v.type].push(v);
    });
    return groups;
}

// --- ERROR BOUNDARY ---

interface ErrorBoundaryProps {
    children: ReactNode;
}

interface ErrorBoundaryState {
    hasError: boolean;
    error: any;
}

class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) { super(props); this.state = { hasError: false, error: null }; }
  static getDerivedStateFromError(error: any) { return { hasError: true, error }; }
  componentDidCatch(error: any, errorInfo: any) { console.error("Uncaught Error:", error, errorInfo); }
  render() {
    if (this.state.hasError) {
      return (
          <div className="p-8 text-center">
              <h1 className="text-2xl font-bold text-red-600 mb-4">Ein Fehler ist aufgetreten</h1>
              <div className="bg-red-50 p-4 rounded border border-red-200 text-left inline-block max-w-2xl overflow-auto">
                  <p className="font-mono text-sm text-red-800">{this.state.error?.message}</p>
              </div>
              <div className="mt-4">
                  <button onClick={() => window.location.reload()} className="bg-blue-600 text-white px-4 py-2 rounded">Seite neu laden</button>
              </div>
          </div>
      );
    }
    return this.props.children;
  }
}

// --- MOCK DB (LOCALSTORAGE) ---
const mockDB = {
  load: (key: string) => {
      try {
          return JSON.parse(localStorage.getItem(`fuhrpark_${key}`) || '[]');
      } catch (e) {
          console.error("MockDB Load Error", e);
          return [];
      }
  },
  save: (key: string, data: any) => localStorage.setItem(`fuhrpark_${key}`, JSON.stringify(data)),

  // Helpers to mimic API delays slightly for realism
  async get(collection: string) {
    return this.load(collection);
  },
  async post(collection: string, item: any) {
    const items = this.load(collection);
    const newItem = { ...item, id: Math.random().toString(36).substr(2, 9) };
    items.push(newItem);
    this.save(collection, items);
    return { success: true, id: newItem.id };
  },
  async put(collection: string, id: string, item: any) {
    const items = this.load(collection);
    const idx = items.findIndex((i:any) => i.id === id);
    if (idx !== -1) {
      items[idx] = item;
      this.save(collection, items);
    }
    return { success: true };
  },
  async delete(collection: string, id: string) {
    const items = this.load(collection);
    const filtered = items.filter((i:any) => i.id !== id);
    this.save(collection, filtered);
    return { success: true };
  }
};

// --- API HELPER WITH FALLBACK ---

let isOfflineMode = false;

const api = {
  // Try server first, fallback to mockDB if fails
  request: async (method: string, endpoint: string, data: any = null) => {
    // Extract collection and ID from endpoint like "/vehicles" or "/vehicles/123"
    const parts = endpoint.split('/').filter(Boolean); // ["vehicles"] or ["vehicles", "123"]
    const collection = parts[0];
    const id = parts[1];

    // If we already know we are offline, skip fetch
    if (isOfflineMode) {
       // @ts-ignore
       if (method === 'GET') return mockDB.get(collection);
       // @ts-ignore
       if (method === 'POST') return mockDB.post(collection, data);
       // @ts-ignore
       if (method === 'PUT') return mockDB.put(collection, id, data);
       // @ts-ignore
       if (method === 'DELETE') return mockDB.delete(collection, id);
    }

    try {
      const opts: any = { method, headers: { 'Content-Type': 'application/json' } };
      if (data) opts.body = JSON.stringify(data);

      const res = await fetch(`/api${endpoint}`, opts);
      if (!res.ok) throw new Error('API Error');
      return await res.json();
    } catch (e) {
      if (!isOfflineMode) {
        console.warn('Backend unavailable, switching to Offline Mode (LocalStorage).');
        isOfflineMode = true;
      }
      // Retry with MockDB immediately
      return api.request(method, endpoint, data);
    }
  },

  get: (url: string) => api.request('GET', url),
  post: (url: string, data: any) => api.request('POST', url, data),
  put: (url: string, data: any) => api.request('PUT', url, data),
  delete: (url: string) => api.request('DELETE', url)
};

