  SONSTIGE = 'Sonstige',
  MASCHINE = 'Maschine'
}

enum Priority {
  LOW = 'Niedrig',
  NORMAL = 'Normal',
  HIGH = 'Dringend',
}

enum OrderStatus {
  OFFEN = 'Offen',
  BESTELLT = 'Bestellt',
  ERLEDIGT = 'Erledigt',
}

interface Attachment {
  name: string;
  data: string; // Base64
  type: string;
}

interface Vehicle {
  id: string;
