// --- HELPER FUNCTIONS ---

const getTodayDate = () => new Date().toISOString().split('T')[0];
const isValidDateMMYYYY = (val: string) => /^\d{2}\/\d{4}$/.test(val);

// Convert "MM/YYYY" (Storage) to "YYYY-MM" (Input type="month")
const toInputFormat = (dateStr?: string) => {
    if (!dateStr) return '';
    const [m, y] = dateStr.split('/');
    if (!m || !y) return '';
    return `${y}-${m}`;
};

// Convert "YYYY-MM" (Input type="month") to "MM/YYYY" (Storage)
const fromInputFormat = (dateStr: string) => {
    if (!dateStr) return '';
    const [y, m] = dateStr.split('-');
    return `${m}/${y}`;
};

const parseDateMMYYYY = (dateStr?: string) => {
    if (!dateStr) return 0;
    const parts = dateStr.split('/');
    if (parts.length < 2) return 0;
    const [m, y] = parts;
    if (!m || !y) return 0;
    return new Date(parseInt(y), parseInt(m)-1).getTime();
};

const getVehicleTypePriority = (type: string) => {
    switch(type) {
        case VehicleType.LKW: return 1;
        case VehicleType.TRANSPORTER: return 2;
        case VehicleType.PKW: return 3;
        case VehicleType.ANHAENGER: return 4;
        case VehicleType.AUFLIEGER: return 5;
        case VehicleType.MASCHINE: return 6;
        case VehicleType.SONSTIGE: return 7;
        default: return 99;
    }
}

const getPrioritySortValue = (p: string) => {
    if (p === Priority.HIGH || (typeof p === 'string' && p.includes('Dringend'))) return 0;
    if (p === Priority.LOW || (typeof p === 'string' && p.includes('Niedrig'))) return 2;
    return 1; // Normal
};

const sortVehicles = (vehicles: Vehicle[]) => {
  return [...vehicles].sort((a, b) => {
    // @ts-ignore
    if (a.type !== b.type) {
        // @ts-ignore
        return getVehicleTypePriority(a.type) - getVehicleTypePriority(b.type);
    }
    return a.licensePlate.localeCompare(b.licensePlate);
  });
};

const groupVehiclesByType = (vehicles: Vehicle[]) => {
    const sorted = sortVehicles(vehicles);
    const groups: { [key: string]: Vehicle[] } = {};
    sorted.forEach(v => {
        // @ts-ignore
        if(!groups[v.type]) groups[v.type] = [];
        // @ts-ignore
        groups[v.type].push(v);
    });
    return groups;
}

// --- ERROR BOUNDARY ---

interface ErrorBoundaryProps {
    children?: ReactNode;
}

interface ErrorBoundaryState {
    hasError: boolean;
    error: any;
}

class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  state: ErrorBoundaryState = { hasError: false, error: null };

  static getDerivedStateFromError(error: any) { return { hasError: true, error }; }

  componentDidCatch(error: any, errorInfo: any) { console.error("Uncaught Error:", error, errorInfo); }

  render() {
    if (this.state.hasError) {
      return (
          <div className="p-8 text-center">
              <h1 className="text-2xl font-bold text-red-600 mb-4">Ein Fehler ist aufgetreten</h1>
              <div className="bg-red-50 p-4 rounded border border-red-200 text-left inline-block max-w-2xl overflow-auto">
                  <p className="font-mono text-sm text-red-800">{this.state.error?.message}</p>
              </div>
              <div className="mt-4">
                  <button onClick={() => window.location.reload()} className="bg-blue-600 text-white px-4 py-2 rounded">Seite neu laden</button>
              </div>
          </div>
      );
    }
    return this.props.children;
  }
}

// --- MOCK DB (LOCALSTORAGE) ---
const mockDB = {
  load: (key: string) => {
      try {
          return JSON.parse(localStorage.getItem(`fuhrpark_${key}`) || '[]');
      } catch (e) {
          console.error("MockDB Load Error", e);
          return [];
      }
  },
  save: (key: string, data: any) => localStorage.setItem(`fuhrpark_${key}`, JSON.stringify(data)),

  // Helpers to mimic API delays slightly for realism
  async get(collection: string) {
    return this.load(collection);
  },
  async post(collection: string, item: any) {
    const items = this.load(collection);
    const newItem = { ...item, id: Math.random().toString(36).substr(2, 9) };
    items.push(newItem);
    this.save(collection, items);
    return { success: true, id: newItem.id };
  },
  async put(collection: string, id: string, item: any) {
    const items = this.load(collection);
    const idx = items.findIndex((i:any) => i.id === id);
    if (idx !== -1) {
      items[idx] = item;
      this.save(collection, items);
    }
    return { success: true };
  },
  async delete(collection: string, id: string) {
    const items = this.load(collection);
    const filtered = items.filter((i:any) => i.id !== id);
    this.save(collection, filtered);
    return { success: true };
  }
};

// --- API HELPER WITH FALLBACK ---

let isOfflineMode = false;

const api = {
  // Try server first, fallback to mockDB if fails
  request: async (method: string, endpoint: string, data: any = null) => {
    // Extract collection and ID from endpoint like "/vehicles" or "/vehicles/123"
    const parts = endpoint.split('/').filter(Boolean); // ["vehicles"] or ["vehicles", "123"]
    const collection = parts[0];
    const id = parts[1];

    // If we already know we are offline, skip fetch
    if (isOfflineMode) {
       // @ts-ignore
       if (method === 'GET') return mockDB.get(collection);
       // @ts-ignore
       if (method === 'POST') return mockDB.post(collection, data);
       // @ts-ignore
       if (method === 'PUT') return mockDB.put(collection, id, data);
       // @ts-ignore
       if (method === 'DELETE') return mockDB.delete(collection, id);
    }

    try {
      const opts: any = { method, headers: { 'Content-Type': 'application/json' } };
      if (data) opts.body = JSON.stringify(data);

      const res = await fetch(`/api${endpoint}`, opts);
      if (!res.ok) throw new Error('API Error');
      return await res.json();
    } catch (e) {
      if (!isOfflineMode) {
        console.warn('Backend unavailable, switching to Offline Mode (LocalStorage).');
        isOfflineMode = true;
      }
      // Retry with MockDB immediately
      return api.request(method, endpoint, data);
    }
  },

  get: (url: string) => api.request('GET', url),
  post: (url: string, data: any) => api.request('POST', url, data),
  put: (url: string, data: any) => api.request('PUT', url, data),
  delete: (url: string) => api.request('DELETE', url)
};

// --- SUB-COMPONENTS ---

const DashboardView = ({ logs, vehicles = [], onStatusUpdate, onEdit, onDelete, onAdd, onInspect }: any) => {
  const safeVehicles = Array.isArray(vehicles) ? vehicles : [];
  const [showCompleted, setShowCompleted] = useState(false);
  const [filters, setFilters] = useState({
      licensePlate: '',
      type: '',
      priority: ''
  });

  // Generate virtual logs from upcoming/overdue inspections
  const generatedInspections: LogEntry[] = useMemo(() => {
    // NOTE: Previously there was logic here to return [] if showCompleted was true.
    // This has been removed so virtual tasks (Prüfungen) always show up, 
    // effectively treating them as "OPEN" tasks that persist regardless of the 'completed' toggle.

    const today = new Date();
    const currentMonthStr = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}`; // YYYY-MM

    const virtual: LogEntry[] = [];

    safeVehicles.forEach((v: Vehicle) => {
        const check = (type: 'HU'|'SP'|'UVV'|'Tacho', dateStr?: string) => {
            if (!dateStr) return;
            // dateStr is MM/YYYY
            const [m, y] = dateStr.split('/');
            if (!m || !y) return;
            const iso = `${y}-${m.padStart(2, '0')}`; // YYYY-MM

            let priority = Priority.NORMAL;
            // If strictly less than current month -> Overdue -> High Priority
            if (iso < currentMonthStr) priority = Priority.HIGH;
            // If equal to current month -> Normal Priority
            else if (iso === currentMonthStr) priority = Priority.NORMAL;
            else return; // Future

            virtual.push({
                id: `virt_${v.id}_${type}_${dateStr}`, // Unique ID
                vehicleId: v.id,
                type: 'Prüfung',
                description: `${type} Fällig (${dateStr})`,
                priority: priority,
                dateAdded: getTodayDate(), 
                status: 'OPEN',
                inspectionType: type,
                isVirtual: true // Flag to handle click differently
            });
        };

        check('HU', v.nextHU);
        check('SP', v.nextSP);
        check('UVV', v.nextUVV);
        check('Tacho', v.nextTacho);
    });

    return virtual;
  }, [safeVehicles]); // Removed showCompleted dependency

  // 1. Filter Logs + Merge Virtual
  const filteredLogs = useMemo(() => {
    // Combine real logs and virtual inspections
    const allItems = [...logs, ...generatedInspections];

    return allItems.filter((l: LogEntry) => {
        // Status Filter
        if (!showCompleted && l.status === 'DONE') return false;

        // Metadata for Filters
        const vehicle = safeVehicles.find((v:Vehicle) => v.id === l.vehicleId);
        const licensePlate = vehicle?.licensePlate || 'Allgemein';
        const type = vehicle?.type || 'Sonstige';

        // Apply Text/Select Filters
        if (filters.licensePlate && !licensePlate.toLowerCase().includes(filters.licensePlate.toLowerCase())) return false;
        if (filters.type && type !== filters.type) return false;
        if (filters.priority && l.priority !== filters.priority) return false;

        return true;
    });
  }, [logs, generatedInspections, safeVehicles, showCompleted, filters]);

  // 2. Group by Vehicle
  const groupedLogs = useMemo(() => {
      const groups: { [key: string]: LogEntry[] } = {};

      filteredLogs.forEach((log: LogEntry) => {
          const key = log.vehicleId || 'unknown';
          if (!groups[key]) groups[key] = [];
          groups[key].push(log);
      });

      // Sort tasks within groups by priority then date
      Object.keys(groups).forEach(key => {
          groups[key].sort((a, b) => {
              // Status order: IN_PROGRESS < OPEN < DONE (so open/in progress are top)
              const statusOrder = { 'IN_PROGRESS': 0, 'OPEN': 1, 'DONE': 2 };
              if (a.status !== b.status) return statusOrder[a.status] - statusOrder[b.status];

              const pA = getPrioritySortValue(a.priority);
              const pB = getPrioritySortValue(b.priority);
              if (pA !== pB) return pA - pB;

              return a.dateAdded.localeCompare(b.dateAdded);
          });
      });

      return groups;
  }, [filteredLogs]);

  // 3. Sort Groups (Vehicles with High Priority tasks first)
  const sortedGroupKeys = useMemo(() => {
      return Object.keys(groupedLogs).sort((a, b) => {
         const tasksA = groupedLogs[a];
         const tasksB = groupedLogs[b];

         // Helper to find highest priority in a list
         const minPrio = (tasks: LogEntry[]) => Math.min(...tasks.map(t => getPrioritySortValue(t.priority)));

         const pA = minPrio(tasksA);
         const pB = minPrio(tasksB);

         if (pA !== pB) return pA - pB;

         // Fallback: License Plate
         const vA = safeVehicles.find((v:Vehicle) => v.id === a);
         const vB = safeVehicles.find((v:Vehicle) => v.id === b);
         return (vA?.licensePlate || 'ZZ').localeCompare(vB?.licensePlate || 'ZZ');
      });
  }, [groupedLogs, safeVehicles]);

  return (
    <div className="space-y-4">
      {/* Compact Header & Controls */}
      <div className="bg-white p-3 rounded shadow-sm border border-gray-200 flex flex-col md:flex-row md:items-center justify-between gap-3">
          <div className="flex items-center gap-4 flex-wrap">
              <h2 className="text-xl font-bold text-gray-800 whitespace-nowrap">Aufgaben</h2>

              {/* Separator */}
              <div className="h-6 w-px bg-gray-300 hidden md:block"></div>

              {/* Compact Filters Inline */}
              <div className="flex flex-wrap items-center gap-2">
                  {/* Search */}
                  <div className="relative group">
                      <span className="absolute left-2.5 top-2 text-gray-400 group-focus-within:text-blue-500 pointer-events-none">
                          <Icons.Search /> 
                      </span>
                      <input 
                          type="text" 
                          placeholder="Suchen..." 
                          className="w-32 md:w-48 pl-8 pr-2 py-1.5 text-sm border border-gray-300 rounded focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none transition-all"
                          value={filters.licensePlate}
                          onChange={e => setFilters({...filters, licensePlate: e.target.value})}
                      />
                  </div>

                  {/* Type Select */}
                  <div className="relative">
                       <select 
                          className="w-28 py-1.5 pl-2 pr-6 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none bg-white text-gray-600 appearance-none cursor-pointer"
                          value={filters.type}
                          onChange={e => setFilters({...filters, type: e.target.value})}
                          style={{ backgroundImage: 'none' }} // Removing default arrow mostly for cleaner look, relying on placeholder context
                      >
                          <option value="">Alle Arten</option>
                          {Object.values(VehicleType).map(t => <option key={t} value={t}>{t}</option>)}
                      </select>
                      {/* Custom tiny arrow to indicate dropdown if standard appearance is removed/styled, but default is fine for now if styled simple */}
                      <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-500">
                        <svg className="fill-current h-4 w-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M9.293 12.95l.707.707L15.657 8l-1.414-1.414L10 10.828 5.757 6.586 4.343 8z"/></svg>
                      </div>
                  </div>

                  {/* Priority Select */}
                   <div className="relative">
                       <select 
                          className="w-28 py-1.5 pl-2 pr-6 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none bg-white text-gray-600 appearance-none cursor-pointer"
                          value={filters.priority}
                          onChange={e => setFilters({...filters, priority: e.target.value})}
                      >
                          <option value="">Alle Prio</option>
                          {Object.values(Priority).map(p => <option key={p} value={p}>{p}</option>)}
                      </select>
                      <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-500">
                        <svg className="fill-current h-4 w-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M9.293 12.95l.707.707L15.657 8l-1.414-1.414L10 10.828 5.757 6.586 4.343 8z"/></svg>
                      </div>
                  </div>

                  {(filters.licensePlate || filters.type || filters.priority) && (
                      <button onClick={() => setFilters({licensePlate: '', type: '', priority: ''})} className="text-gray-400 hover:text-red-500 p-1.5 rounded hover:bg-red-50" title="Filter löschen">
                          <Icons.Trash />
                      </button>
                  )}
              </div>
          </div>

          {/* Actions */}
          <div className="flex items-center gap-2 shrink-0 self-end md:self-auto">
               <button 
                  onClick={() => setShowCompleted(!showCompleted)} 
                  className={`p-2 rounded border transition-colors ${showCompleted ? 'bg-blue-50 text-blue-600 border-blue-200' : 'bg-white text-gray-400 border-gray-200 hover:border-gray-300'}`}
                  title={showCompleted ? 'Erledigte ausblenden' : 'Erledigte anzeigen'}
               >
                  {showCompleted ? <Icons.Eye /> : <Icons.EyeOff />}
               </button>
               <button onClick={onAdd} className="bg-blue-600 hover:bg-blue-700 text-white px-3 py-1.5 rounded flex items-center gap-2 shadow-sm font-bold text-sm">
                  <Icons.Plus /> Neu
              </button>
          </div>
      </div>

      {/* Grid Content */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 items-start">
        {sortedGroupKeys.length === 0 && (
            <div className="col-span-full text-center py-12 text-gray-400 bg-gray-50 rounded border border-dashed border-gray-300">
                Keine Aufgaben gefunden.
            </div>
        )}

        {sortedGroupKeys.map(vid => {
          const vehicleLogs = groupedLogs[vid];
          const vehicle = safeVehicles.find((v:Vehicle) => v.id === vid);
          const hasUrgent = vehicleLogs.some(l => l.priority === Priority.HIGH);

          return (
            <div key={vid} className="bg-white rounded shadow-sm border border-gray-200 overflow-hidden flex flex-col h-full">
               {/* Card Header */}
               <div className="bg-slate-50 border-b border-gray-200 px-4 py-3 flex justify-between items-center">
                   <div>
                       <div className="font-bold text-lg text-slate-800 flex items-center gap-2">
                           {vehicle ? vehicle.licensePlate : 'Allgemein / Lager'}
                       </div>
                       {vehicle && <div className="text-xs text-slate-500">{vehicle.manufacturer} {vehicle.model} • {vehicle.type}</div>}
                   </div>
                   <div className={`${hasUrgent ? 'bg-red-100 text-red-700 border border-red-200' : 'bg-slate-200 text-slate-600'} px-2 py-0.5 rounded-full text-xs font-bold`}>
                       {vehicleLogs.length}
                   </div>
               </div>

               {/* Tasks List */}
               <div className="divide-y divide-gray-100">
                   {vehicleLogs.map((log: LogEntry) => {
                       const isDone = log.status === 'DONE';
                       const isInProgress = log.status === 'IN_PROGRESS';

                       return (
                           <div key={log.id} className={`p-3 group transition-colors ${isInProgress ? 'bg-amber-50' : isDone ? 'bg-gray-50 opacity-75' : 'hover:bg-blue-50'}`}>
                               <div className="flex justify-between items-start gap-2">
                                   <div className="flex-1 min-w-0">
                                       <div className="flex items-center gap-2 mb-1">
                                            <span className={`px-1.5 py-0.5 rounded-[3px] text-[10px] font-bold uppercase tracking-wider border ${
                                                log.priority === Priority.HIGH ? 'bg-red-100 text-red-800 border-red-200' : 
                                                log.priority === Priority.LOW ? 'bg-gray-100 text-gray-600 border-gray-200' : 
                                                'bg-blue-50 text-blue-800 border-blue-100'
                                            }`}>
                                                {log.priority}
                                            </span>
                                            {isInProgress && (
                                                <span className="text-[10px] font-bold text-amber-600 flex items-center gap-1 bg-amber-100 px-1.5 py-0.5 rounded border border-amber-200">
                                                    <Icons.Clock /> In Bearbeitung
                                                </span>
                                            )}
                                            {log.isVirtual && (
                                                <span className="text-[10px] font-bold text-purple-600 bg-purple-100 px-1.5 py-0.5 rounded border border-purple-200 ml-1">
                                                    PRÜFUNG
                                                </span>
                                            )}
                                       </div>
                                       <div className={`text-sm text-gray-800 whitespace-pre-wrap ${isDone ? 'line-through text-gray-500' : ''}`}>
                                           {log.description}
                                       </div>
                                       <div className="text-[10px] text-gray-400 mt-1 flex gap-2">
                                           <span>Erstellt: {log.dateAdded}</span>
                                       </div>
                                   </div>

                                   {/* Actions */}
                                   <div className="flex flex-col gap-1 items-end">
                                       {!isDone && (
                                           <div className="flex gap-1">
                                               {!isInProgress && !log.isVirtual && (
                                                   <button 
                                                        onClick={() => onStatusUpdate(log, 'IN_PROGRESS')} 
                                                        className="p-1.5 bg-white border border-gray-200 text-amber-500 hover:bg-amber-50 hover:border-amber-300 rounded shadow-sm transition-all" 
                                                        title="In Bearbeitung setzen"
                                                   >
                                                       <Icons.Clock />
                                                   </button>
                                               )}
                                               <button 
                                                    onClick={() => log.isVirtual ? onInspect(log) : onStatusUpdate(log, 'DONE')} 
                                                    className="p-1.5 bg-white border border-gray-200 text-green-600 hover:bg-green-50 hover:border-green-300 rounded shadow-sm transition-all" 
                                                    title={log.isVirtual ? "Prüfung durchführen & Neuen Termin setzen" : "Erledigen"}
                                               >
                                                   <Icons.Check />
                                               </button>
                                           </div>
                                       )}
                                       <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                           {!log.isVirtual && (
                                            <>
                                               <button onClick={() => onEdit(log)} className="p-1 text-blue-400 hover:text-blue-600"><Icons.Edit /></button>
                                               <button onClick={() => onDelete(log.id)} className="p-1 text-red-300 hover:text-red-600"><Icons.Trash /></button>
                                            </>
                                           )}
                                       </div>
                                   </div>
                               </div>
                           </div>
                       );
                   })}
               </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

const VehicleListView = ({ vehicles = [], onEdit, onDelete, onAdd }: any) => {
  const [sortConfig, setSortConfig] = useState<{ key: keyof Vehicle | 'modelFull' | null, direction: 'asc' | 'desc' }>({ key: null, direction: 'asc' });
  const [filters, setFilters] = useState<{ [key: string]: string }>({});

  const handleSort = (key: keyof Vehicle | 'modelFull') => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const handleFilterChange = (key: string, value: string) => {
    setFilters(prev => ({ ...prev, [key]: value }));
  };

  const processedVehicles = useMemo(() => {
    if (!vehicles || !Array.isArray(vehicles)) return [];

    let filtered = [...vehicles];

    // Filter
    Object.keys(filters).forEach(key => {
        const filterVal = filters[key].toLowerCase();
        if(!filterVal) return;

        filtered = filtered.filter(v => {
            let valToCheck = '';
            if (key === 'modelFull') valToCheck = `${v.manufacturer || ''} ${v.model || ''}`;
            // @ts-ignore
            else if (v[key]) valToCheck = String(v[key]);

            return valToCheck.toLowerCase().includes(filterVal);
        });
    });

    // Sort
    if (sortConfig.key) {
        filtered.sort((a, b) => {
            let valA: any = sortConfig.key === 'modelFull' ? `${a.manufacturer || ''} ${a.model || ''}` : a[sortConfig.key as keyof Vehicle];
            let valB: any = sortConfig.key === 'modelFull' ? `${b.manufacturer || ''} ${b.model || ''}` : b[sortConfig.key as keyof Vehicle];

            // Handle undefined/null safely
            if (valA === undefined || valA === null) valA = '';
            if (valB === undefined || valB === null) valB = '';

            // Number sort
            if (sortConfig.key === 'currentMileage') {
                const numA = Number(valA) || 0;
                const numB = Number(valB) || 0;
                return sortConfig.direction === 'asc' ? (numA - numB) : (numB - numA);
            }

            // Date Sort (MM/YYYY)
            if (sortConfig.key === 'nextHU') {
                const dateA = parseDateMMYYYY(String(valA));
                const dateB = parseDateMMYYYY(String(valB));
                return sortConfig.direction === 'asc' ? (dateA - dateB) : (dateB - dateA);
            }

            // Type Sort
            if (sortConfig.key === 'type') {
                // @ts-ignore
                const pA = getVehicleTypePriority(valA);
                // @ts-ignore
                const pB = getVehicleTypePriority(valB);
                return sortConfig.direction === 'asc' ? (pA - pB) : (pB - pA);
            }

            // String sort
            return sortConfig.direction === 'asc'
                ? String(valA).localeCompare(String(valB))
                : String(valB).localeCompare(String(valA));
        });
    }

    return filtered;
  }, [vehicles, sortConfig, filters]);

  const getSortIcon = (colKey: string) => {
     if (sortConfig.key !== colKey) return <span className="text-gray-300"><Icons.SortDefault /></span>;
     return sortConfig.direction === 'asc' ? <span className="text-blue-600"><Icons.SortAsc /></span> : <span className="text-blue-600"><Icons.SortDesc /></span>;
  };

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-gray-800">Fahrzeuge</h2>
        <div className="flex gap-2">
          <button onClick={onAdd} className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded flex items-center gap-2">
            <Icons.Plus /> Neu
          </button>
        </div>
      </div>
      <div className="bg-white rounded shadow overflow-x-auto border border-gray-200">
        <table className="w-full text-left border-collapse">
          <thead className="bg-gray-50 text-gray-600 text-sm uppercase tracking-wider">
            {/* Header Row for Sorting */}
            <tr className="border-b border-gray-200">
              <th className="p-3 cursor-pointer hover:bg-gray-100 transition-colors select-none" onClick={() => handleSort('licensePlate')}>
                  <div className="flex items-center gap-2">Kennzeichen {getSortIcon('licensePlate')}</div>
              </th>
              <th className="p-3 cursor-pointer hover:bg-gray-100 transition-colors select-none" onClick={() => handleSort('type')}>
                  <div className="flex items-center gap-2">Typ {getSortIcon('type')}</div>
              </th>
              <th className="p-3 cursor-pointer hover:bg-gray-100 transition-colors select-none" onClick={() => handleSort('modelFull')}>
                  <div className="flex items-center gap-2">Modell {getSortIcon('modelFull')}</div>
              </th>
              <th className="p-3 cursor-pointer hover:bg-gray-100 transition-colors select-none" onClick={() => handleSort('currentMileage')}>
                  <div className="flex items-center gap-2">KM-Stand {getSortIcon('currentMileage')}</div>
              </th>
              <th className="p-3 cursor-pointer hover:bg-gray-100 transition-colors select-none" onClick={() => handleSort('nextHU')}>
                  <div className="flex items-center gap-2">Nächste HU {getSortIcon('nextHU')}</div>
              </th>
              <th className="p-3 w-32">Aktionen</th>
            </tr>
            {/* Input Row for Filtering */}
            <tr className="bg-gray-50 border-b border-gray-300">
                <th className="p-2">
                    <input 
                        className="w-full text-xs font-normal border border-gray-300 rounded px-2 py-1 outline-none focus:border-blue-500"
                        placeholder="Filter..." 
                        value={filters.licensePlate || ''}
                        onChange={e => handleFilterChange('licensePlate', e.target.value)}
                    />
                </th>
                <th className="p-2">
                    <select 
                        className="w-full text-xs font-normal border border-gray-300 rounded px-2 py-1 outline-none focus:border-blue-500 bg-white"
                        value={filters.type || ''}
                        onChange={e => handleFilterChange('type', e.target.value)}
                    >
                        <option value="">Alle</option>
                        {Object.values(VehicleType).map(t => <option key={t} value={t}>{t}</option>)}
                    </select>
                </th>
                <th className="p-2">
                    <input 
                        className="w-full text-xs font-normal border border-gray-300 rounded px-2 py-1 outline-none focus:border-blue-500"
                        placeholder="Filter Modell..." 
                        value={filters.modelFull || ''}
                        onChange={e => handleFilterChange('modelFull', e.target.value)}
                    />
                </th>
                <th className="p-2"></th>
                <th className="p-2">
                    <input 
                        className="w-full text-xs font-normal border border-gray-300 rounded px-2 py-1 outline-none focus:border-blue-500"
                        placeholder="MM/YYYY" 
                        value={filters.nextHU || ''}
                        onChange={e => handleFilterChange('nextHU', e.target.value)}
                    />
                </th>
                <th className="p-2"></th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {processedVehicles.length === 0 && (
                <tr>
                    <td colSpan={6} className="p-8 text-center text-gray-500 italic">
                        Keine Fahrzeuge gefunden.
                    </td>
                </tr>
            )}
            {processedVehicles.map((v: Vehicle) => (
              <tr key={v.id} className="hover:bg-blue-50 transition-colors">
                <td className="p-3 font-bold text-gray-800">{v.licensePlate}</td>
                <td className="p-3">
                    <span className="px-2 py-0.5 rounded-full bg-gray-100 text-gray-600 text-xs font-bold border border-gray-200">
                        {v.type}
                    </span>
                </td>
                <td className="p-3 text-gray-700">{v.manufacturer} {v.model}</td>
                <td className="p-3 font-mono text-gray-600">{v.currentMileage?.toLocaleString()}</td>
                <td className="p-3">
                    {v.nextHU && (
                        <span className={`font-mono font-bold ${parseDateMMYYYY(v.nextHU) < Date.now() ? 'text-red-600' : 'text-green-700'}`}>
                            {v.nextHU}
                        </span>
                    )}
                </td>
                <td className="p-3 flex gap-2">
                  <button onClick={() => onEdit(v)} className="p-1.5 text-blue-600 hover:bg-blue-100 rounded transition-colors" title="Bearbeiten"><Icons.Edit /></button>
                  <button onClick={() => onDelete(v.id)} className="p-1.5 text-red-600 hover:bg-red-100 rounded transition-colors" title="Löschen"><Icons.Trash /></button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

const CombinationsView = ({ vehicles = [], onCouple, onUncouple }: any) => {
    const [selectedMotor, setSelectedMotor] = useState('');
    const [selectedTrailer, setSelectedTrailer] = useState('');

    const isMotor = (v: Vehicle) => [VehicleType.LKW, VehicleType.TRANSPORTER, VehicleType.PKW, VehicleType.MASCHINE].includes(v.type as VehicleType);
    const isTrailer = (v: Vehicle) => [VehicleType.ANHAENGER, VehicleType.AUFLIEGER].includes(v.type as VehicleType);

    // Available Motor Vehicles (Not currently coupled)
    const availableMotors = vehicles.filter((v: Vehicle) => isMotor(v) && !v.coupledVehicleId);

    // Available Trailers (Not currently coupled)
    const availableTrailers = vehicles.filter((v: Vehicle) => isTrailer(v) && !v.coupledVehicleId);

    // Existing Combinations
    // We iterate through vehicles. If a vehicle has a coupledId, we show it. 
    // To avoid duplicates (since linkage is bidirectional), we only render from the "Motor" side perspective.
    const combinations = vehicles.filter((v: Vehicle) => isMotor(v) && v.coupledVehicleId).map((motor: Vehicle) => {
        const trailer = vehicles.find((t: Vehicle) => t.id === motor.coupledVehicleId);
        return { motor, trailer };
    });

    const handleCouple = () => {
        if(selectedMotor && selectedTrailer) {
            onCouple(selectedMotor, selectedTrailer);
            setSelectedMotor('');
            setSelectedTrailer('');
        }
    };

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-bold text-gray-800">Gespanne verwalten</h2>

            {/* Create New Combination */}
            <div className="bg-white p-6 rounded shadow-sm border border-gray-200">
                <h3 className="font-bold text-lg mb-4 text-gray-700 flex items-center gap-2">
                    <Icons.Link /> Neues Gespann bilden
                </h3>
                <div className="flex flex-col md:flex-row gap-4 items-end">
                    <div className="flex-1 w-full">
                        <label className="block text-sm font-bold text-gray-600 mb-1">Motorwagen / Zugmaschine</label>
                        <select 
                            className="w-full border border-gray-300 p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                            value={selectedMotor}
                            onChange={(e) => setSelectedMotor(e.target.value)}
                        >
                            <option value="">Bitte wählen...</option>
                            {availableMotors.map((v: Vehicle) => (
                                <option key={v.id} value={v.id}>{v.licensePlate} ({v.model})</option>
                            ))}
                        </select>
                    </div>
                    <div className="flex items-center justify-center pb-2 text-gray-400">
                        <Icons.Link />
                    </div>
                    <div className="flex-1 w-full">
                         <label className="block text-sm font-bold text-gray-600 mb-1">Anhänger / Auflieger</label>
                         <select 
                            className="w-full border border-gray-300 p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                            value={selectedTrailer}
                            onChange={(e) => setSelectedTrailer(e.target.value)}
                        >
                            <option value="">Bitte wählen...</option>
                            {availableTrailers.map((v: Vehicle) => (
                                <option key={v.id} value={v.id}>{v.licensePlate} ({v.type})</option>
                            ))}
                        </select>
                    </div>
                    <button 
                        onClick={handleCouple}
                        disabled={!selectedMotor || !selectedTrailer}
                        className={`px-6 py-2 rounded font-bold text-white transition-colors ${
                            selectedMotor && selectedTrailer ? 'bg-blue-600 hover:bg-blue-700' : 'bg-gray-300 cursor-not-allowed'
                        }`}
                    >
                        Koppeln
                    </button>
                </div>
            </div>

            {/* List Existing Combinations */}
            <div>
                <h3 className="font-bold text-gray-600 mb-3 uppercase tracking-wide text-sm">Aktuelle Gespanne</h3>
                <div className="bg-white rounded shadow border border-gray-200 overflow-hidden">
                    {combinations.length === 0 ? (
                         <div className="p-8 text-center text-gray-500 italic">Keine aktiven Gespanne.</div>
                    ) : (
                        <table className="w-full text-left">
                            <thead className="bg-gray-50 border-b border-gray-200 text-xs text-gray-500 uppercase">
                                <tr>
                                    <th className="p-3">Motorwagen</th>
                                    <th className="p-3">Anhänger</th>
                                    <th className="p-3 text-right">Aktion</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {combinations.map(({ motor, trailer }: any) => (
                                    <tr key={motor.id} className="hover:bg-gray-50">
                                        <td className="p-3">
                                            <div className="font-bold text-gray-800">{motor.licensePlate}</div>
                                            <div className="text-xs text-gray-500">{motor.manufacturer} {motor.model}</div>
                                        </td>
                                        <td className="p-3">
                                            {trailer ? (
                                                <>
                                                    <div className="font-bold text-gray-800">{trailer.licensePlate}</div>
                                                    <div className="text-xs text-gray-500">{trailer.type}</div>
                                                </>
                                            ) : (
                                                <span className="text-red-500 text-xs italic">Fahrzeug nicht gefunden (ID: {motor.coupledVehicleId})</span>
                                            )}
                                        </td>
                                        <td className="p-3 text-right">
                                            <button 
                                                onClick={() => onUncouple(motor.id, trailer?.id)}
                                                className="text-red-600 hover:bg-red-50 px-3 py-1 rounded text-sm font-medium border border-red-200 hover:border-red-300 transition-colors"
                                            >
                                                Trennen
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    )}
                </div>
            </div>
        </div>
    );
};

const AppointmentsView = ({ vehicles = [], onComplete }: any) => {
  const [selectedMonth, setSelectedMonth] = useState(getTodayDate().substring(0, 7));

  const safeVehicles = Array.isArray(vehicles) ? vehicles : [];

  const appointments = useMemo(() => {
    const list: any[] = [];
    safeVehicles.forEach((v: Vehicle) => {
      if (v.nextHU) list.push({ id: v.id + 'HU', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'HU', date: v.nextHU });
      if (v.nextSP) list.push({ id: v.id + 'SP', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'SP', date: v.nextSP });
      if (v.nextUVV) list.push({ id: v.id + 'UVV', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'UVV', date: v.nextUVV });
      if (v.nextTacho) list.push({ id: v.id + 'Tacho', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'Tacho', date: v.nextTacho });
    });
    return list.sort((a, b) => {
       const [ma, ya] = a.date.split('/');
       const [mb, yb] = b.date.split('/');
       return new Date(parseInt(ya), parseInt(ma)-1).getTime() - new Date(parseInt(yb), parseInt(mb)-1).getTime();
    });
  }, [safeVehicles]);

  const getBadgeColor = (type: string) => {
      switch(type) {
          case 'HU': return 'bg-rose-100 text-rose-800 border-rose-200';
          case 'SP': return 'bg-orange-100 text-orange-800 border-orange-200';
          case 'UVV': return 'bg-blue-100 text-blue-800 border-blue-200';
          case 'Tacho': return 'bg-purple-100 text-purple-800 border-purple-200';
          default: return 'bg-gray-100 text-gray-800';
      }
  };

  const { overdue, dueThisMonth, upcoming } = useMemo(() => {
    const ov: any[] = [];
    const curr: any[] = [];
    const up: any[] = [];

    appointments.forEach(apt => {
        const [m, y] = apt.date.split('/');
        const aptIso = `${y}-${m.padStart(2, '0')}`;

        if (aptIso < selectedMonth) {
            ov.push({...apt, isOverdue: true});
        } else if (aptIso === selectedMonth) {
            curr.push({...apt, isOverdue: false});
        } else {
            up.push(apt);
        }
    });
    return { overdue: ov, dueThisMonth: curr, upcoming: up };
  }, [appointments, selectedMonth]);

  const upcomingGrouped = useMemo(() => {
      const groups: Record<string, any[]> = {};
      upcoming.forEach(apt => {
          if(!groups[apt.date]) groups[apt.date] = [];
          groups[apt.date].push(apt);
      });
      return groups;
  }, [upcoming]);

  const AppointmentCard = ({ apt, isOverdue }: any) => (
      <div className={`bg-white rounded shadow-sm border-l-4 overflow-hidden relative ${isOverdue ? 'border-red-600 bg-red-50' : 'border-blue-400'}`}>
         <div className="p-2">
             <div className="flex justify-between items-center mb-1">
                 <span className={`inline-block px-1.5 py-0.5 rounded-[2px] text-[10px] font-bold uppercase tracking-wide ${isOverdue ? 'bg-red-600 text-white' : 'bg-blue-100 text-blue-800'}`}>
                     {isOverdue ? 'ÜBERFÄLLIG' : 'Diesen Monat'}
                 </span>
                 <span className={`font-mono font-bold text-xs ${isOverdue ? 'text-red-700' : 'text-blue-600'}`}>{apt.date}</span>
             </div>

             <div className="mb-2">
                 <div className="text-base font-bold text-gray-800 leading-tight truncate" title={apt.license}>{apt.license}</div>
                 <div className="text-[10px] text-gray-500 truncate">{apt.vehicleType}</div>
             </div>

             <div className="flex items-center justify-between mt-2 pt-2 border-t border-gray-100/50">
                 <span className={`px-1.5 py-0.5 rounded text-[10px] font-bold border ${getBadgeColor(apt.inspectionType)}`}>
                     {apt.inspectionType}
                 </span>
                 <button 
                     onClick={() => onComplete(apt)}
                     className={`flex items-center gap-1 text-white px-2 py-1 rounded shadow-sm transition-colors text-[10px] font-bold ${isOverdue ? 'bg-red-600 hover:bg-red-700' : 'bg-slate-700 hover:bg-slate-800'}`}
                     title="Prüfung erledigen"
                 >
                     <Icons.Check />
                     <span className="hidden sm:inline">Erledigen</span>
                 </button>
             </div>
         </div>
     </div>
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-end justify-between border-b pb-2 gap-2">
          <div>
