                <h3 className="text-xl font-bold mb-6 text-gray-800 border-b pb-2">{vehicle ? 'Fahrzeug bearbeiten' : 'Neues Fahrzeug'}</h3>
                <div className="space-y-4 max-h-[75vh] overflow-y-auto pr-1">

                    {/* Stammdaten */}
