                  {(filters.licensePlate || filters.type || filters.priority) && (
                      <button onClick={() => setFilters({licensePlate: '', type: '', priority: ''})} className="text-gray-400 hover:text-red-500 p-1.5 rounded hover:bg-red-50" title="Filter löschen">
                          <Icons.Trash />
                      </button>
