// printUtils.ts
// Dieses Modul ist exklusiv für das Layout der Druckansicht / PDF Erstellung zuständig.
// Änderungen hier betreffen NICHT das Design der Web-App.

export const printMaintenanceReport = (vehicle: any, repairs: any[]) => {
    // Öffne ein neues Fenster für den Druck
    const printWindow = window.open('', '_blank', 'width=900,height=800');
    if (!printWindow) {
        alert('Bitte Popups erlauben, um das PDF zu generieren.');
        return;
    }

    const totalCost = repairs.reduce((acc, curr) => acc + (parseFloat(curr.cost) || 0), 0).toFixed(2);
    const sortedRepairs = [...repairs].sort((a, b) => b.date.localeCompare(a.date));

    const htmlContent = `
        <!DOCTYPE html>
        <html>
        <head>
            <title>Wartungsheft - ${vehicle.licensePlate}</title>
            <style>
                body { font-family: 'Helvetica', 'Arial', sans-serif; padding: 40px; color: #333; }
                .header { border-bottom: 2px solid #333; padding-bottom: 20px; margin-bottom: 30px; display: flex; justify-content: space-between; align-items: flex-end; }
                .title { font-size: 24px; font-weight: bold; text-transform: uppercase; }
                .meta { text-align: right; font-size: 12px; color: #666; }

                .vehicle-info { background: #f4f4f4; padding: 20px; border-radius: 8px; margin-bottom: 30px; display: flex; gap: 40px; }
                .info-item { display: flex; flex-direction: column; }
                .label { font-size: 10px; text-transform: uppercase; font-weight: bold; color: #888; margin-bottom: 4px; }
                .value { font-size: 16px; font-weight: bold; }

                table { w-100%; width: 100%; border-collapse: collapse; font-size: 12px; }
                th { text-align: left; border-bottom: 2px solid #ddd; padding: 10px 8px; text-transform: uppercase; color: #555; font-size: 10px; }
                td { padding: 12px 8px; border-bottom: 1px solid #eee; vertical-align: top; }
                tr:last-child td { border-bottom: none; }

                .type-badge { display: inline-block; padding: 2px 6px; border-radius: 4px; font-size: 9px; font-weight: bold; text-transform: uppercase; background: #eee; }
                .cost { font-family: 'Courier New', monospace; font-weight: bold; text-align: right; }
                .sum-row { background: #333; color: white; }
                .sum-row td { padding: 10px 8px; font-weight: bold; font-size: 14px; border: none; }

                @media print {
                    body { -webkit-print-color-adjust: exact; }
                    .no-print { display: none; }
                }
            </style>
        </head>
        <body>
            <div class="header">
                <div class="title">Wartungsheft</div>
                <div class="meta">
                    Erstellt am: ${new Date().toLocaleDateString('de-DE')}<br>
                    Fuhrpark Manager
                </div>
            </div>

            <div class="vehicle-info">
                <div class="info-item">
                    <span class="label">Kennzeichen</span>
                    <span class="value">${vehicle.licensePlate}</span>
                </div>
                <div class="info-item">
                    <span class="label">Fahrzeug</span>
                    <span class="value">${vehicle.manufacturer} ${vehicle.model}</span>
                </div>
                <div class="info-item">
                    <span class="label">FIN / VIN</span>
                    <span class="value">${vehicle.vin}</span>
                </div>
                 <div class="info-item">
                    <span class="label">Typ</span>
                    <span class="value">${vehicle.type}</span>
                </div>
            </div>

            <table>
                <thead>
                    <tr>
                        <th width="100">Datum</th>
                        <th width="80">KM-Stand</th>
                        <th width="100">Art</th>
                        <th>Beschreibung</th>
                        <th width="150">Ausgeführt durch</th>
                        <th width="100" style="text-align:right">Kosten (€)</th>
                    </tr>
                </thead>
                <tbody>
                    ${sortedRepairs.map(r => `
                        <tr>
                            <td>${new Date(r.date).toLocaleDateString('de-DE')}</td>
                            <td>${r.mileage ? r.mileage.toLocaleString() : '-'}</td>
                            <td><span class="type-badge">${r.type}</span></td>
                            <td>${r.description.replace(/\n/g, '<br>')}</td>
                            <td>${r.performer}</td>
                            <td class="cost">${parseFloat(r.cost || 0).toFixed(2)}</td>
                        </tr>
                    `).join('')}
                    <tr class="sum-row">
                        <td colspan="5" style="text-align:right">GESAMTKOSTEN</td>
                        <td class="cost">${totalCost} €</td>
                    </tr>
                </tbody>
            </table>

            <script>
                window.onload = function() { window.print(); }
            </script>
        </body>
        </html>
    `;

    printWindow.document.write(htmlContent);
    printWindow.document.close();
};

import React, { useState, useEffect, useMemo, useCallback, Component, ReactNode } from 'react';
import { createRoot } from 'react-dom/client';
import { printMaintenanceReport } from './printUtils';

// --- TYPES & ENUMS ---

enum VehicleType {
  PKW = 'PKW',
  LKW = 'LKW',
  TRANSPORTER = 'Transporter',
  ANHAENGER = 'Anhänger',
  AUFLIEGER = 'Auflieger',
  SONSTIGE = 'Sonstige',
  MASCHINE = 'Maschine'
}

enum Priority {
  LOW = 'Niedrig',
  NORMAL = 'Normal',
  HIGH = 'Dringend',
}

enum OrderStatus {
  OFFEN = 'Offen',
  BESTELLT = 'Bestellt',
  ERLEDIGT = 'Erledigt',
}

interface Attachment {
  name: string;
  data: string; // Base64
  type: string;
}

interface Vehicle {
  id: string;
  licensePlate: string;
  type: VehicleType | string;
  manufacturer: string;
  model: string; // Typ
  vin: string;
  year: number;
  notes: string;
  coupledVehicleId?: string | null; // For LKW <-> Auflieger

  // Inspection Due Dates (MM/YYYY)
  nextHU?: string;
  nextSP?: string;
  nextUVV?: string;
  nextTacho?: string;

  currentMileage?: number; // KM or Hours
}

interface LogEntry {
  id: string;
  vehicleId: string;
  type: string; // Generic 'Aufgabe'
  description: string;
  priority: Priority;
  dateAdded: string; // ISO Date
  dateCompleted?: string;
  status: 'OPEN' | 'IN_PROGRESS' | 'DONE';
  mileage?: number;

  // Specific for inspections
  inspectionType?: 'HU' | 'SP' | 'UVV' | 'Tacho';

  // Attachments
  attachments?: Attachment[];

  // Frontend specific
  isVirtual?: boolean; // If true, this is a generated inspection task, not saved in DB yet
}

interface Order {
  id: string;
  description: string;
  vehicleId?: string;
  dateAdded: string;
  status: OrderStatus;
}

interface RepairEntry {
  id: string;
  vehicleId: string;
  date: string;
  type: 'Wartung' | 'Reparatur' | 'Reifen' | 'Sonstiges';
  description: string;
  performer: string; // Wer hat es gemacht (Werkstatt/Eigen)
  cost: number;
  mileage: number;
  invoiceData?: string; // Base64 Placeholder
}

