};

const App = () => {
    const [view, setView] = useState('dashboard');
    const [vehicles, setVehicles] = useState<Vehicle[]>([]);
    const [logs, setLogs] = useState<LogEntry[]>([]);
    const [orders, setOrders] = useState<Order[]>([]);
    const [loading, setLoading] = useState(true);

    // Modal States
    const [vehicleModal, setVehicleModal] = useState({ open: false, data: null as Vehicle | null });
    const [entryModal, setEntryModal] = useState({ open: false, data: null as LogEntry | null });
    const [orderModal, setOrderModal] = useState({ open: false, data: null as Order | null });
    const [inspectionModal, setInspectionModal] = useState({ open: false, data: null as LogEntry | null });

    // Load Data
    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const [v, l, o] = await Promise.all([
                api.get('/vehicles'),
                api.get('/logs'),
                api.get('/orders')
            ]);
            setVehicles(Array.isArray(v) ? v : []);
            setLogs(Array.isArray(l) ? l : []);
            setOrders(Array.isArray(o) ? o : []);
        } catch (e) {
            console.error(e);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => { loadData(); }, [loadData]);

    // Handlers
    const saveVehicle = async (v: Vehicle) => {
        if(v.id && vehicles.find(x => x.id === v.id)) {
             await api.put(`/vehicles/${v.id}`, v);
        } else {
             await api.post('/vehicles', v);
        }
        setVehicleModal({ open: false, data: null });
        loadData();
    };

    const deleteVehicle = async (id: string) => {
        if(confirm('Fahrzeug wirklich löschen?')) {
            await api.delete(`/vehicles/${id}`);
            loadData();
        }
    };

    const saveEntry = async (entries: any[]) => {
        for (const entry of entries) {
            if(entry.id && logs.find(x => x.id === entry.id)) {
                await api.put(`/logs/${entry.id}`, entry);
            } else {
                await api.post('/logs', entry);
            }
        }
        setEntryModal({ open: false, data: null });
        loadData();
    };

    // Updated generic handler for status changes (In Progress, Done, etc.)
    const updateLogStatus = async (log: LogEntry, newStatus: 'IN_PROGRESS' | 'DONE') => {
        const updateData: any = { ...log, status: newStatus };
        if(newStatus === 'DONE') {
             updateData.dateCompleted = getTodayDate();
        }
        await api.put(`/logs/${log.id}`, updateData);
        loadData();
    };

    const completeInspection = async (log: LogEntry, nextDate: string) => {
        // 1. Create a DONE log for the inspection
        // Note: nextDate comes as YYYY-MM from input type="month", save as string
        // The log itself is the "record" of the inspection.
        const vehicle = vehicles.find(v => v.id === log.vehicleId);

        // Convert YYYY-MM back to MM/YYYY for storage if needed, but standardizing on what backend expects
        const [y, m] = nextDate.split('-');
        const nextDateStorage = `${m}/${y}`;

        await api.post('/logs', {
            vehicleId: log.vehicleId,
            type: 'Wartung',
            description: `${log.inspectionType} Prüfung durchgeführt`,
            priority: Priority.NORMAL,
            dateAdded: getTodayDate(),
            status: 'DONE',
            dateCompleted: getTodayDate(),
            inspectionType: log.inspectionType
        });

        // 2. Update Vehicle Next Date
        if (vehicle) {
            const updateKey = `next${log.inspectionType}`;
            const updatedVehicle = { ...vehicle, [updateKey]: nextDateStorage };
            await api.put(`/vehicles/${vehicle.id}`, updatedVehicle);
        }

        setInspectionModal({ open: false, data: null });
        loadData();
    };

    const deleteLog = async (id: string) => {
        if(confirm('Eintrag löschen?')) {
            await api.delete(`/logs/${id}`);
            loadData();
        }
    };

    const saveOrder = async (ordersList: any[]) => {
        for (const o of ordersList) {
             if(o.id && orders.find(x => x.id === o.id)) {
                await api.put(`/orders/${o.id}`, o);
            } else {
                await api.post('/orders', o);
            }
        }
        setOrderModal({ open: false, data: null });
        loadData();
    };

    const updateOrderStatus = async (id: string, status: OrderStatus) => {
        const order = orders.find(o => o.id === id);
        if(order) {
            await api.put(`/orders/${id}`, { ...order, status });
            loadData();
        }
    };

    const deleteOrder = async (id: string) => {
        if(confirm('Bestellung löschen?')) {
            await api.delete(`/orders/${id}`);
            loadData();
        }
    };

    // Couple / Uncouple Logic
    const coupleVehicles = async (motorId: string, trailerId: string) => {
        const motor = vehicles.find(v => v.id === motorId);
        const trailer = vehicles.find(v => v.id === trailerId);
        if(motor && trailer) {
            await api.put(`/vehicles/${motor.id}`, { ...motor, coupledVehicleId: trailer.id });
            await api.put(`/vehicles/${trailer.id}`, { ...trailer, coupledVehicleId: motor.id });
            loadData();
        }
    };

    const uncoupleVehicles = async (motorId: string, trailerId: string) => {
        const motor = vehicles.find(v => v.id === motorId);
        if(motor) await api.put(`/vehicles/${motor.id}`, { ...motor, coupledVehicleId: null });

        if(trailerId) {
            const trailer = vehicles.find(v => v.id === trailerId);
            if(trailer) await api.put(`/vehicles/${trailer.id}`, { ...trailer, coupledVehicleId: null });
        }
        loadData();
    };

    return (
        <div className="flex h-full bg-gray-100 font-sans text-gray-900">
            {/* Sidebar */}
            <div className="w-64 bg-slate-800 text-white flex flex-col shadow-xl z-10 no-print">
                <div className="p-6 border-b border-slate-700">
                    <h1 className="text-xl font-bold tracking-tight">Fuhrpark<span className="text-blue-400">Manager</span></h1>
                </div>
                <nav className="flex-1 p-4 space-y-2">
                    <NavButton icon={<Icons.Dashboard />} label="ToDo" active={view === 'dashboard'} onClick={() => setView('dashboard')} />
                    <NavButton icon={<Icons.Calendar />} label="Termine" active={view === 'appointments'} onClick={() => setView('appointments')} />
                    <NavButton icon={<Icons.ShoppingCart />} label="Bestellungen" active={view === 'orders'} onClick={() => setView('orders')} />
                    <NavButton icon={<Icons.History />} label="Historie" active={view === 'history'} onClick={() => setView('history')} />
                    <NavButton icon={<Icons.Link />} label="Gespanne" active={view === 'combinations'} onClick={() => setView('combinations')} />
                    <NavButton icon={<Icons.Truck />} label="Fahrzeuge" active={view === 'vehicles'} onClick={() => setView('vehicles')} />
                </nav>
                <div className="p-4 border-t border-slate-700 text-xs text-slate-400">
                    v2.2.0 • {isOfflineMode ? 'Offline Mode' : 'Online'}
                </div>
            </div>

            {/* Main Content */}
            <div className="flex-1 flex flex-col h-full overflow-hidden">
                <header className="bg-white shadow-sm border-b px-8 py-4 flex justify-between items-center no-print">
                     <h2 className="text-xl font-bold text-gray-800 capitalize">{view === 'dashboard' ? 'ToDo' : view}</h2>
                     <div className="flex gap-2">
                         <button onClick={loadData} className="p-2 text-gray-500 hover:bg-gray-100 rounded" title="Refresh">
                            <Icons.History /> {/* Using history icon as refresh roughly */}
                         </button>
                     </div>
                </header>

                <main className="flex-1 overflow-auto p-8">
                    <ErrorBoundary>
                        {loading ? (
                            <div className="flex justify-center items-center h-full text-gray-400">Laden...</div>
                        ) : (
                            <>
                                {view === 'dashboard' && <DashboardView logs={logs} vehicles={vehicles} onAdd={() => setEntryModal({open:true, data:null})} onInspect={(l:any) => setInspectionModal({open: true, data: l})} onStatusUpdate={updateLogStatus} onEdit={(l:any) => setEntryModal({open:true, data:l})} onDelete={deleteLog} />}
                                {view === 'vehicles' && <VehicleListView vehicles={vehicles} onAdd={() => setVehicleModal({open:true, data:null})} onEdit={(v:any) => setVehicleModal({open:true, data:v})} onDelete={deleteVehicle} />}
                                {view === 'combinations' && <CombinationsView vehicles={vehicles} onCouple={coupleVehicles} onUncouple={uncoupleVehicles} />}
                                {view === 'appointments' && <AppointmentsView vehicles={vehicles} onComplete={(apt: any) => {
                                    setInspectionModal({
                                        open: true, 
                                        data: {
                                            id: `virt_${apt.vid}_${apt.inspectionType}`, 
                                            vehicleId: apt.vid, 
                                            type: 'Prüfung', 
                                            description: `${apt.inspectionType} Fällig (${apt.date})`, 
                                            priority: Priority.NORMAL, 
                                            dateAdded: getTodayDate(), 
                                            status: 'OPEN',
                                            inspectionType: apt.inspectionType,
                                            isVirtual: true
                                        } as LogEntry
                                    });
                                }} />}
                                {view === 'orders' && <OrdersView orders={orders} vehicles={vehicles} onAdd={() => setOrderModal({open:true, data:null})} onEdit={(o:any) => setOrderModal({open:true, data:o})} onStatusChange={updateOrderStatus} onDelete={deleteOrder} />}
                                {view === 'history' && <HistoryView logs={logs} vehicles={vehicles} isAdmin={true} onEdit={(l:any) => setEntryModal({open:true, data:l})} onDelete={deleteLog} />}
                            </>
                        )}
                    </ErrorBoundary>
                </main>
            </div>

            {/* Modals */}
            <VehicleModal isOpen={vehicleModal.open} onClose={() => setVehicleModal({open:false, data:null})} vehicle={vehicleModal.data} allVehicles={vehicles} onSave={saveVehicle} />
            <EntryModal isOpen={entryModal.open} onClose={() => setEntryModal({open:false, data:null})} entry={entryModal.data} vehicles={vehicles} onSave={saveEntry} />
            <OrderModal isOpen={orderModal.open} onClose={() => setOrderModal({open:false, data:null})} order={orderModal.data} vehicles={vehicles} onSave={saveOrder} />
            <InspectionModal isOpen={inspectionModal.open} onClose={() => setInspectionModal({open:false, data:null})} log={inspectionModal.data} onSave={completeInspection} />
        </div>
    );
};

const NavButton = ({ icon, label, active, onClick }: any) => (
    <button 
        onClick={onClick}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded transition-colors font-medium ${active ? 'bg-blue-600 text-white shadow-md' : 'text-slate-300 hover:bg-slate-700 hover:text-white'}`}
    >
        {icon}
        <span>{label}</span>
    </button>
);

const container = document.getElementById('root');
const root = createRoot(container!);
root.render(<App />);

export enum VehicleType {
  PKW = 'PKW',
  LKW = 'LKW',
  TRANSPORTER = 'Transporter',
  ANHAENGER = 'Anhänger',
  AUFLIEGER = 'Auflieger',
  SONSTIGE = 'Sonstige',
  MASCHINE = 'Maschine'
}

export enum Priority {
  LOW = 'Niedrig',
  NORMAL = 'Normal',
  HIGH = 'Dringend',
}

export enum OrderStatus {
  OFFEN = 'Offen',
  BESTELLT = 'Bestellt',
  ERLEDIGT = 'Erledigt',
}

export interface Attachment {
  name: string;
  data: string; // Base64
  type: string;
}

export interface Vehicle {
  id: string;
  licensePlate: string;
  type: VehicleType | string;
  manufacturer: string;
  model: string; // Typ
  vin: string;
  year: number;
  notes: string;
  coupledVehicleId?: string | null; // For LKW <-> Auflieger

  // Inspection Due Dates (MM/YYYY)
  nextHU?: string;
  nextSP?: string;
  nextUVV?: string;
  nextTacho?: string;

  currentMileage?: number; // KM or Hours
}

export interface LogEntry {
  id: string;
  vehicleId: string;
  type: string; // Generic 'Aufgabe'
  description: string;
  priority: Priority;
  dateAdded: string; // ISO Date
  dateCompleted?: string;
  status: 'OPEN' | 'IN_PROGRESS' | 'DONE';
  mileage?: number;

  // Specific for inspections
  inspectionType?: 'HU' | 'SP' | 'UVV' | 'Tacho';

  // Attachments
  attachments?: Attachment[];

  // Frontend specific
  isVirtual?: boolean; // If true, this is a generated inspection task, not saved in DB yet
}

export interface Order {
  id: string;
  description: string;
  vehicleId?: string;
  dateAdded: string;
  status: OrderStatus;
}

import { Vehicle, Priority, VehicleType, LogEntry } from './types';

export const getTodayDate = () => new Date().toISOString().split('T')[0];
export const isValidDateMMYYYY = (val: string) => /^\d{2}\/\d{4}$/.test(val);

// Convert "MM/YYYY" (Storage) to "YYYY-MM" (Input type="month")
export const toInputFormat = (dateStr?: string) => {
    if (!dateStr) return '';
    const [m, y] = dateStr.split('/');
    if (!m || !y) return '';
    return `${y}-${m}`;
};

// Convert "YYYY-MM" (Input type="month") to "MM/YYYY" (Storage)
export const fromInputFormat = (dateStr: string) => {
    if (!dateStr) return '';
    const [y, m] = dateStr.split('-');
    return `${m}/${y}`;
};

export const parseDateMMYYYY = (dateStr?: string) => {
    if (!dateStr) return 0;
    const parts = dateStr.split('/');
    if (parts.length < 2) return 0;
    const [m, y] = parts;
    if (!m || !y) return 0;
    return new Date(parseInt(y), parseInt(m)-1).getTime();
};

export const getVehicleTypePriority = (type: string | any) => {
    switch(type) {
        case VehicleType.LKW: return 1;
        case VehicleType.TRANSPORTER: return 2;
        case VehicleType.PKW: return 3;
        case VehicleType.ANHAENGER: return 4;
        case VehicleType.AUFLIEGER: return 5;
        case VehicleType.MASCHINE: return 6;
        case VehicleType.SONSTIGE: return 7;
        default: return 99;
    }
}

export const getPrioritySortValue = (p: string | Priority) => {
    if (p === Priority.HIGH || (typeof p === 'string' && p.includes('Dringend'))) return 0;
    if (p === Priority.LOW || (typeof p === 'string' && p.includes('Niedrig'))) return 2;
    return 1; // Normal
};

export const getBadgeColor = (type: string) => {
    switch(type) {
        case 'HU': return 'bg-rose-100 text-rose-800 border-rose-200';
        case 'SP': return 'bg-orange-100 text-orange-800 border-orange-200';
        case 'UVV': return 'bg-blue-100 text-blue-800 border-blue-200';
        case 'Tacho': return 'bg-purple-100 text-purple-800 border-purple-200';
        default: return 'bg-gray-100 text-gray-800';
    }
};

export const sortVehicles = (vehicles: Vehicle[]) => {
  return [...vehicles].sort((a, b) => {
    if (a.type !== b.type) {
        return getVehicleTypePriority(a.type) - getVehicleTypePriority(b.type);
    }
    return a.licensePlate.localeCompare(b.licensePlate);
  });
};

export const groupVehiclesByType = (vehicles: Vehicle[]) => {
    const sorted = sortVehicles(vehicles);
    const groups: { [key: string]: Vehicle[] } = {};
    sorted.forEach(v => {
        const typeKey = String(v.type);
        if(!groups[typeKey]) groups[typeKey] = [];
        groups[typeKey].push(v);
    });
    return groups;
}

// Generates virtual log entries for overdue inspections
export const generateVirtualInspections = (vehicles: Vehicle[]): LogEntry[] => {
    const today = new Date();
    const currentMonthStr = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}`; // YYYY-MM

    const virtual: LogEntry[] = [];

    vehicles.forEach((v: Vehicle) => {
        const check = (type: 'HU'|'SP'|'UVV'|'Tacho', dateStr?: string) => {
            if (!dateStr) return;
            // dateStr is MM/YYYY
            const [m, y] = dateStr.split('/');
            if (!m || !y) return;
            const iso = `${y}-${m.padStart(2, '0')}`; // YYYY-MM

            let priority = Priority.NORMAL;
            // If strictly less than current month -> Overdue -> High Priority
            if (iso < currentMonthStr) priority = Priority.HIGH;
            // If equal to current month -> Normal Priority
            else if (iso === currentMonthStr) priority = Priority.NORMAL;
            else return; // Future

            virtual.push({
                id: `virt_${v.id}_${type}_${dateStr}`, // Unique ID
                vehicleId: v.id,
                type: 'Prüfung',
                description: `${type} Fällig (${dateStr})`,
                priority: priority,
                dateAdded: getTodayDate(), 
                status: 'OPEN',
                inspectionType: type,
                isVirtual: true // Flag to handle click differently
            });
        };

        check('HU', v.nextHU);
        check('SP', v.nextSP);
        check('UVV', v.nextUVV);
        check('Tacho', v.nextTacho);
    });

    return virtual;
}

// MockDB for offline fallback
const mockDB = {
    load: (key: string) => {
        try {
            return JSON.parse(localStorage.getItem(`fuhrpark_${key}`) || '[]');
        } catch (e) {
            console.error("MockDB Load Error", e);
            return [];
        }
    },
    save: (key: string, data: any) => localStorage.setItem(`fuhrpark_${key}`, JSON.stringify(data)),

    // Helpers to mimic API delays slightly for realism
    async get(collection: string) {
      return this.load(collection);
    },
    async post(collection: string, item: any) {
      const items = this.load(collection);
      const newItem = { ...item, id: Math.random().toString(36).substr(2, 9) };
      items.push(newItem);
      this.save(collection, items);
      return { success: true, id: newItem.id };
    },
    async put(collection: string, id: string, item: any) {
      const items = this.load(collection);
      const idx = items.findIndex((i:any) => i.id === id);
      if (idx !== -1) {
        items[idx] = item;
        this.save(collection, items);
      }
      return { success: true };
    },
    async delete(collection: string, id: string) {
      const items = this.load(collection);
      const filtered = items.filter((i:any) => i.id !== id);
      this.save(collection, filtered);
      return { success: true };
    }
  };

  let isOfflineMode = false;

  export const getIsOfflineMode = () => isOfflineMode;

  export const api = {
    // Try server first, fallback to mockDB if fails
    request: async (method: string, endpoint: string, data: any = null) => {
      // Extract collection and ID from endpoint like "/vehicles" or "/vehicles/123"
      const parts = endpoint.split('/').filter(Boolean); // ["vehicles"] or ["vehicles", "123"]
      const collection = parts[0];
      const id = parts[1];

      // If we already know we are offline, skip fetch
      if (isOfflineMode) {
         // @ts-ignore
         if (method === 'GET') return mockDB.get(collection);
         // @ts-ignore
         if (method === 'POST') return mockDB.post(collection, data);
         // @ts-ignore
         if (method === 'PUT') return mockDB.put(collection, id, data);
         // @ts-ignore
         if (method === 'DELETE') return mockDB.delete(collection, id);
      }

      try {
        const opts: any = { method, headers: { 'Content-Type': 'application/json' } };
        if (data) opts.body = JSON.stringify(data);

        const res = await fetch(`/api${endpoint}`, opts);
        if (!res.ok) throw new Error('API Error');
        return await res.json();
      } catch (e) {
        if (!isOfflineMode) {
          console.warn('Backend unavailable, switching to Offline Mode (LocalStorage).');
          isOfflineMode = true;
        }
        // Retry with MockDB immediately
        return api.request(method, endpoint, data);
      }
    },

    get: (url: string) => api.request('GET', url),
    post: (url: string, data: any) => api.request('POST', url, data),
    put: (url: string, data: any) => api.request('PUT', url, data),
    delete: (url: string) => api.request('DELETE', url)
  };

