const HistoryView = ({ logs, vehicles = [], isAdmin, onEdit, onDelete }: any) => {
  const [filters, setFilters] = useState({
    text: '',
    licensePlate: '',
    type: ''
  });
  const safeVehicles = Array.isArray(vehicles) ? vehicles : [];

  const completedLogs = useMemo(() => {
      return logs.filter((l: LogEntry) => {
        if (l.status !== 'DONE') return false;

        const vehicle = safeVehicles.find((v:Vehicle) => v.id === l.vehicleId);
        const plate = vehicle?.licensePlate || '';
        const vType = vehicle?.type || '';

        // Text Search (Description)
        if (filters.text && !l.description.toLowerCase().includes(filters.text.toLowerCase())) return false;

        // License Plate Filter
        if (filters.licensePlate && !plate.toLowerCase().includes(filters.licensePlate.toLowerCase())) return false;

        // Type Filter
        if (filters.type && vType !== filters.type) return false;

        return true;
      }).sort((a: LogEntry, b: LogEntry) => {
          // Sort by date completed desc
          return (b.dateCompleted || '').localeCompare(a.dateCompleted || '');
      });
  }, [logs, safeVehicles, filters]);

  return (
    <div className="space-y-4">
      {/* Header & Filters */}
      <div className="bg-white p-3 rounded shadow-sm border border-gray-200 flex flex-col md:flex-row md:items-center justify-between gap-3">
        <h2 className="text-xl font-bold text-gray-800">Historie</h2>

        <div className="flex flex-wrap items-center gap-2">
           {/* Text Search */}
           <div className="relative group">
                <span className="absolute left-2.5 top-2 text-gray-400 pointer-events-none">
                    <Icons.Search /> 
                </span>
                <input 
                    type="text" 
                    placeholder="Stichwort..." 
                    className="w-32 md:w-48 pl-8 pr-2 py-1.5 text-sm border border-gray-300 rounded focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none transition-all"
                    value={filters.text}
                    onChange={e => setFilters({...filters, text: e.target.value})}
                />
            </div>

            {/* License Plate Search */}
            <div className="relative group">
                <span className="absolute left-2.5 top-2 text-gray-400 pointer-events-none">
                    <Icons.Truck /> 
                </span>
                <input 
                    type="text" 
                    placeholder="Kennzeichen..." 
                    className="w-32 md:w-40 pl-8 pr-2 py-1.5 text-sm border border-gray-300 rounded focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none transition-all"
                    value={filters.licensePlate}
                    onChange={e => setFilters({...filters, licensePlate: e.target.value})}
                />
            </div>

            {/* Type Select */}
            <div className="relative">
                 <select 
                    className="w-32 py-1.5 pl-2 pr-6 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none bg-white text-gray-600 appearance-none cursor-pointer"
                    value={filters.type}
                    onChange={e => setFilters({...filters, type: e.target.value})}
                >
                    <option value="">Alle Arten</option>
                    {Object.values(VehicleType).map(t => <option key={t} value={t}>{t}</option>)}
                </select>
                <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-500">
                    <svg className="fill-current h-4 w-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M9.293 12.95l.707.707L15.657 8l-1.414-1.414L10 10.828 5.757 6.586 4.343 8z"/></svg>
                </div>
            </div>

            {/* Reset Button */}
            {(filters.text || filters.licensePlate || filters.type) && (
                <button 
                    onClick={() => setFilters({text: '', licensePlate: '', type: ''})} 
                    className="text-gray-400 hover:text-red-500 p-1.5 rounded hover:bg-red-50 transition-colors" 
                    title="Filter löschen"
                >
                    <Icons.Trash />
                </button>
            )}
        </div>
      </div>

      <div className="bg-white rounded shadow border border-gray-200 overflow-hidden">
        {completedLogs.length === 0 ? (
            <div className="p-8 text-center text-gray-500 italic">Keine Einträge gefunden.</div>
        ) : (
            <div className="divide-y divide-gray-100">
                {completedLogs.map((l: LogEntry) => {
                    const vehicle = safeVehicles.find((v:Vehicle) => v.id === l.vehicleId);
                    return (
                        <div key={l.id} className="p-4 hover:bg-gray-50 transition-colors">
                            <div className="flex justify-between items-start mb-1">
                                <div className="font-bold text-gray-800 whitespace-pre-wrap">{l.description}</div>
                                <div className="text-xs text-gray-500 whitespace-nowrap bg-gray-100 px-2 py-1 rounded">{l.dateCompleted}</div>
                            </div>
                            <div className="flex justify-between items-center">
                                <div className="flex items-center gap-2">
                                     <span className="text-sm font-medium text-blue-600 bg-blue-50 px-2 py-0.5 rounded border border-blue-100">
                                        {vehicle ? vehicle.licensePlate : 'Allgemein / Gelöscht'}
                                     </span>
                                     {vehicle && <span className="text-xs text-gray-400 hidden sm:inline">• {vehicle.type}</span>}
                                     {l.inspectionType && <span className="text-[10px] font-bold px-1.5 py-0.5 rounded border bg-purple-50 text-purple-700 border-purple-200">{l.inspectionType}</span>}
                                </div>
