                                    </div>

                                    {/* Extra Badges */}
                                    {l.inspectionType && (
                                        <div className="mt-1">
                                            <span className="text-[10px] px-1.5 py-0.5 rounded border bg-purple-50 text-purple-700 border-purple-200">
                                                {l.inspectionType}
                                            </span>
                                        </div>
                                    )}
                                </div>

                                {/* Actions */}
                                {isAdmin && (
                                    <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity self-center">
                                        <button onClick={() => onEdit(l)} className="text-gray-400 hover:text-blue-600"><Icons.Edit /></button>
                                        <button onClick={() => onDelete(l.id)} className="text-gray-400 hover:text-red-600"><Icons.Trash /></button>
                                    </div>
                                )}
                            </div>
                         </div>
                    );
                })}
            </div>
        )}
      </div>
    </div>
  );
};

