                        <svg className="fill-current h-4 w-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M9.293 12.95l.707.707L15.657 8l-1.414-1.414L10 10.828 5.757 6.586 4.343 8z"/></svg>
                      </div>
                  </div>

                  {/* Category Select (New) */}
                   <div className="relative">
                       <select 
                          className="w-32 py-1.5 pl-2 pr-6 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none bg-white text-gray-600 appearance-none cursor-pointer"
                          value={filters.category}
                          onChange={e => setFilters({...filters, category: e.target.value})}
                      >
                          <option value="">Alle Einträge</option>
                          <option value="inspection">Nur Prüfungen</option>
                          <option value="task">Nur Aufgaben</option>
                      </select>
                      <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-500">
                        <svg className="fill-current h-4 w-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M9.293 12.95l.707.707L15.657 8l-1.414-1.414L10 10.828 5.757 6.586 4.343 8z"/></svg>
                      </div>
                  </div>

                  {(filters.licensePlate || filters.type || filters.priority || filters.category) && (
                      <button onClick={() => setFilters({licensePlate: '', type: '', priority: '', category: ''})} className="text-gray-400 hover:text-red-500 p-1.5 rounded hover:bg-red-50" title="Filter löschen">
                          <Icons.Trash />
                      </button>
