const AppointmentsView = ({ vehicles = [], onComplete }: any) => {
  const [selectedMonth, setSelectedMonth] = useState(getTodayDate().substring(0, 7));

  const safeVehicles = Array.isArray(vehicles) ? vehicles : [];

  const appointments = useMemo(() => {
    const list: any[] = [];
    safeVehicles.forEach((v: Vehicle) => {
      if (v.nextHU) list.push({ id: v.id + 'HU', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'HU', date: v.nextHU });
      if (v.nextSP) list.push({ id: v.id + 'SP', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'SP', date: v.nextSP });
      if (v.nextUVV) list.push({ id: v.id + 'UVV', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'UVV', date: v.nextUVV });
      if (v.nextTacho) list.push({ id: v.id + 'Tacho', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'Tacho', date: v.nextTacho });
    });
    return list.sort((a, b) => {
       const [ma, ya] = a.date.split('/');
       const [mb, yb] = b.date.split('/');
       return new Date(parseInt(ya), parseInt(ma)-1).getTime() - new Date(parseInt(yb), parseInt(mb)-1).getTime();
    });
  }, [safeVehicles]);

  const { overdue, dueThisMonth, upcoming } = useMemo(() => {
    const ov: any[] = [];
    const curr: any[] = [];
    const up: any[] = [];

    appointments.forEach(apt => {
        const [m, y] = apt.date.split('/');
        const aptIso = `${y}-${m.padStart(2, '0')}`;

        if (aptIso < selectedMonth) {
            ov.push({...apt, isOverdue: true});
        } else if (aptIso === selectedMonth) {
            curr.push({...apt, isOverdue: false});
        } else {
            up.push(apt);
        }
    });
    return { overdue: ov, dueThisMonth: curr, upcoming: up };
  }, [appointments, selectedMonth]);

  const upcomingGrouped = useMemo(() => {
      const groups: Record<string, any[]> = {};
      upcoming.forEach(apt => {
          if(!groups[apt.date]) groups[apt.date] = [];
          groups[apt.date].push(apt);
      });
      return groups;
  }, [upcoming]);

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-end justify-between border-b pb-2 gap-2">
          <div>
            <h2 className="text-xl font-bold text-gray-800">Prüfungs-Monitor</h2>
            <div className="text-xs text-gray-500 mt-0.5">
                Anzeige für: <span className="font-mono font-bold text-gray-700">{selectedMonth}</span>
            </div>
          </div>

          <div className="flex items-center gap-2 bg-white p-1 rounded border shadow-sm">
             <span className="text-xs font-bold text-gray-600">Monat:</span>
             <input 
                type="month" 
                value={selectedMonth}
                onChange={(e) => setSelectedMonth(e.target.value)}
                className="border border-gray-300 rounded px-1 py-0.5 text-xs font-sans focus:outline-none focus:ring-1 focus:ring-blue-500"
             />
             {selectedMonth !== getTodayDate().substring(0, 7) && (
                 <button 
                    onClick={() => setSelectedMonth(getTodayDate().substring(0, 7))}
                    className="ml-1 text-[10px] bg-blue-100 text-blue-700 px-2 py-1 rounded font-bold hover:bg-blue-200 transition-colors"
                    title="Zurück zum aktuellen Monat"
                 >
                    Heute
                 </button>
             )}
          </div>
      </div>

      {/* SECTION 1: OVERDUE */}
      {overdue.length > 0 && (
          <div className="space-y-2 animate-pulse-once">
              <h3 className="font-bold text-red-700 text-sm flex items-center gap-2 bg-red-50 p-2 rounded border border-red-200">
                  <Icons.Alert />
                  ÜBERFÄLLIG ({overdue.length})
                  <span className="text-xs font-normal text-red-800 ml-auto hidden sm:inline">Aus Vormonaten</span>
              </h3>
              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-3">
                  {overdue.map(apt => (
                      <AppointmentCard key={apt.id} apt={apt} isOverdue={true} onComplete={onComplete} />
                  ))}
              </div>
          </div>
      )}

      {/* SECTION 2: CURRENT MONTH */}
      <div className="space-y-2">
          <h3 className="font-bold text-blue-800 text-sm flex items-center gap-2 border-b border-blue-200 pb-1">
              <Icons.Calendar />
              FÄLLIG IM {selectedMonth} ({dueThisMonth.length})
          </h3>

          {dueThisMonth.length === 0 && (
             <div className="bg-blue-50 border border-blue-100 text-blue-800 p-4 rounded text-center">
                 <div className="text-xl mb-1">📅</div>
                 <div className="font-bold text-sm">Nichts geplant</div>
             </div>
          )}

          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-3">
             {dueThisMonth.map(apt => (
                 <AppointmentCard key={apt.id} apt={apt} isOverdue={false} onComplete={onComplete} />
             ))}
          </div>
      </div>

      {/* SECTION 3: FORECAST (Quarterly View) */}
      <div className="pt-6 border-t mt-4">
          <h3 className="text-sm font-bold text-gray-500 mb-4 uppercase tracking-wider">Vorschau (Quartalsansicht)</h3>

          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
              {Object.keys(upcomingGrouped).length === 0 && (
                  <div className="col-span-full text-xs text-gray-400 italic">Keine späteren Termine.</div>
              )}

              {Object.keys(upcomingGrouped).map(dateKey => (
                  <div key={dateKey} className="bg-white border border-gray-200 rounded shadow-sm flex flex-col h-full">
                      {/* Card Header: Month/Date */}
                      <div className="bg-gray-50 px-3 py-2 border-b border-gray-100 flex justify-between items-center">
                          <span className="font-bold text-gray-700 text-sm">{dateKey}</span>
                          <span className="text-[10px] bg-white border border-gray-200 px-1.5 rounded text-gray-500 font-bold shadow-sm">
                              {upcomingGrouped[dateKey].length}
                          </span>
                      </div>

                      {/* Card Body: List of Appointments */}
                      <div className="divide-y divide-gray-100 p-1">
                          {upcomingGrouped[dateKey].map(apt => (
                              <div key={apt.id} className="p-2 flex justify-between items-center hover:bg-gray-50 transition-colors rounded">
                                  <div className="flex items-center gap-2 overflow-hidden">
                                      {/* Tiny Badge */}
                                      <div className={`shrink-0 w-9 text-center text-[9px] font-bold px-0.5 py-0.5 rounded border ${getBadgeColor(apt.inspectionType)}`}>
                                          {apt.inspectionType}
