                                          <div className="text-[9px] text-gray-500 truncate">{apt.vehicleType}</div>
                                      </div>
                                  </div>

                                  {/* Compact Check Action */}
                                  <button 
                                    onClick={() => onComplete(apt)} 
                                    className="text-gray-300 hover:text-green-600 p-1.5 hover:bg-green-50 rounded transition-colors" 
                                    title="Jetzt schon erledigen"
                                  >
                                     <Icons.Check />
                                  </button>
                              </div>
                          ))}
