                    <div className="flex gap-1 border-l pl-4 border-gray-200">
                        <button onClick={() => onEdit(o)} className="text-blue-400 hover:text-blue-600 p-1.5 hover:bg-blue-50 rounded transition-colors" title="Bearbeiten"><Icons.Edit /></button>
                        <button onClick={() => onDelete(o.id)} className="text-red-300 hover:text-red-600 p-1.5 hover:bg-red-50 rounded transition-colors" title="Löschen"><Icons.Trash /></button>
                    </div>
                </div>
              </div>
            );
        })}
      </div>
    </div>
  );
};

const HistoryView = ({ logs, vehicles = [], isAdmin, onEdit, onDelete }: any) => {
  const [filters, setFilters] = useState({
    text: '',
    licensePlate: '',
    type: '',
    category: '' // New category filter
  });
  const safeVehicles = Array.isArray(vehicles) ? vehicles : [];

  const completedLogs = useMemo(() => {
      return logs.filter((l: LogEntry) => {
        if (l.status !== 'DONE') return false;

        const vehicle = safeVehicles.find((v:Vehicle) => v.id === l.vehicleId);
        const plate = vehicle?.licensePlate || '';
        const vType = vehicle?.type || '';

        // Text Search (Description)
        if (filters.text && !l.description.toLowerCase().includes(filters.text.toLowerCase())) return false;

        // License Plate Filter
        if (filters.licensePlate && !plate.toLowerCase().includes(filters.licensePlate.toLowerCase())) return false;

        // Type Filter
        if (filters.type && vType !== filters.type) return false;

        // Category Filter
        if (filters.category === 'inspection') {
             // Show only inspections (have inspectionType or type is 'Wartung')
             if (!l.inspectionType && l.type !== 'Wartung') return false;
        } else if (filters.category === 'task') {
             // Show only general tasks (no inspectionType and type not 'Wartung')
             if (l.inspectionType || l.type === 'Wartung') return false;
        }

        return true;
      }).sort((a: LogEntry, b: LogEntry) => {
          // Sort by date completed desc
          return (b.dateCompleted || '').localeCompare(a.dateCompleted || '');
      });
  }, [logs, safeVehicles, filters]);

  return (
    <div className="space-y-4">
      {/* Header & Filters */}
      <div className="bg-white p-3 rounded shadow-sm border border-gray-200 flex flex-col md:flex-row md:items-center justify-between gap-3">
        <h2 className="text-xl font-bold text-gray-800">Historie</h2>

        <div className="flex flex-wrap items-center gap-2">
