      <div className="bg-white rounded shadow border border-gray-200 overflow-hidden">
        {completedLogs.length === 0 ? (
            <div className="p-8 text-center text-gray-500 italic">Keine Einträge gefunden.</div>
        ) : (
            <div className="divide-y divide-gray-100">
                {completedLogs.map((l: LogEntry) => {
                    const vehicle = safeVehicles.find((v:Vehicle) => v.id === l.vehicleId);
                    return (
                        <div key={l.id} className="p-2 border-b last:border-b-0 border-gray-100 hover:bg-gray-50 transition-colors">
                            <div className="flex justify-between items-start">
                                <div className="flex-1 min-w-0 pr-4">
                                     {/* Header: License Plate + Date */}
                                    <div className="flex items-center gap-2 mb-0.5">
                                        <span className="text-sm text-gray-900 font-medium">
                                            {vehicle ? vehicle.licensePlate : 'Allgemein / Gelöscht'}
                                        </span>
                                        <span className="text-xs text-gray-400">
                                            {l.dateCompleted}
                                        </span>
                                        {vehicle && <span className="text-[10px] text-gray-400 px-1 border border-gray-200 rounded">{vehicle.type}</span>}
                                    </div>

                                    {/* Description - No Bold */}
                                    <div className="text-sm text-gray-600 whitespace-pre-wrap leading-tight">
                                        {l.description}
                                    </div>

                                    {/* Extra Badges */}
                                    {l.inspectionType && (
                                        <div className="mt-1">
                                            <span className="text-[10px] px-1.5 py-0.5 rounded border bg-purple-50 text-purple-700 border-purple-200">
                                                {l.inspectionType}
                                            </span>
                                        </div>
                                    )}
                                </div>

                                {/* Actions */}
                                {isAdmin && (
                                    <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity self-center">
                                        <button onClick={() => onEdit(l)} className="text-gray-400 hover:text-blue-600"><Icons.Edit /></button>
                                        <button onClick={() => onDelete(l.id)} className="text-gray-400 hover:text-red-600"><Icons.Trash /></button>
                                    </div>
                                )}
                            </div>
                         </div>
                    );
                })}
            </div>
        )}
      </div>
    </div>
  );
};

const AdminView = () => {
    const [dbStats, setDbStats] = useState<any>(null);
    const [checkResult, setCheckResult] = useState<any[]>([]);
    const [loading, setLoading] = useState(false);
    const [message, setMessage] = useState('');
    const offline = getIsOfflineMode();

    // AUTH STATE
    const [isAuthenticated, setIsAuthenticated] = useState(false);
    const [passwordInput, setPasswordInput] = useState('');
    const [loginError, setLoginError] = useState('');

    const fetchStats = async () => {
        try {
            const data = await api.get('/admin/db-stats');
            setDbStats(data);
        } catch(e) { console.error(e); }
    };

    useEffect(() => {
        if(!offline && isAuthenticated) fetchStats();
    }, [offline, isAuthenticated]);

    const handleIntegrityCheck = async () => {
        setLoading(true);
        setMessage('');
        try {
            const res = await api.get('/admin/db-check');
            setCheckResult(Array.isArray(res) ? res : []);
        } catch(e) {
            setMessage('Fehler bei der Prüfung.');
        } finally {
            setLoading(false);
        }
    };

    const handleVacuum = async () => {
         if(!confirm("Diese Aktion reorganisiert die Datenbank, um Speicherplatz freizugeben. Dies kann einen Moment dauern. Fortfahren?")) return;
         setLoading(true);
         setMessage('');
         try {
             const res = await api.post('/admin/db-vacuum', {});
             if(res.success) {
                 setMessage('Optimierung erfolgreich abgeschlossen.');
                 fetchStats();
             }
         } catch(e) {
             setMessage('Fehler bei der Optimierung.');
         } finally {
             setLoading(false);
         }
    };

    if (offline) {
        return (
            <div className="p-8 text-center bg-white rounded border border-gray-200">
                <Icons.WifiOff />
                <h2 className="text-lg font-bold mt-2 text-gray-600">Admin-Modus nicht verfügbar</h2>
                <p className="text-sm text-gray-400">Datenbank-Wartung ist nur im Online-Modus möglich.</p>
            </div>
        );
    }

    if (!isAuthenticated) {
        return (
            <div className="max-w-md mx-auto mt-20 bg-white p-8 rounded shadow-md border border-gray-200">
                <h2 className="text-2xl font-bold text-gray-800 mb-6 flex items-center gap-2">
                    <Icons.Lock /> Admin-Bereich
                </h2>
                <p className="text-sm text-gray-500 mb-4">Bitte geben Sie das Passwort ein.</p>
                <form onSubmit={(e) => {
                    e.preventDefault();
                    if(passwordInput === 'administrator') {
                        setIsAuthenticated(true);
                        setLoginError('');
                    } else {
                        setLoginError('Falsches Passwort.');
                    }
                }}>
                    <input 
                        type="password"
                        className="w-full border border-gray-300 p-2 rounded mb-4 outline-none focus:border-blue-500"
                        placeholder="Passwort"
                        value={passwordInput}
                        onChange={e => setPasswordInput(e.target.value)}
                        autoFocus
                    />
                    {loginError && <div className="text-red-600 text-sm mb-4 font-bold">{loginError}</div>}
                    <button type="submit" className="w-full bg-blue-600 text-white font-bold py-2 rounded hover:bg-blue-700 transition-colors">
                        Anmelden
                    </button>
                </form>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                <Icons.Database /> Datenbank Wartung
            </h2>

            {/* Info Card */}
            <div className="bg-white p-6 rounded shadow-sm border border-gray-200">
                 <h3 className="font-bold text-gray-700 mb-4 border-b pb-2">Status</h3>
                 <div className="grid grid-cols-2 gap-4">
                     <div>
                         <div className="text-sm text-gray-500 uppercase font-bold">Größe</div>
                         <div className="text-2xl font-mono text-blue-600">{dbStats?.size || '-'}</div>
                     </div>
                     <div>
                         <div className="text-sm text-gray-500 uppercase font-bold">Backend</div>
                         <div className="text-lg font-bold text-green-600">Online</div>
                     </div>
                 </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Integrity Check */}
                <div className="bg-white p-6 rounded shadow-sm border border-gray-200">
                    <h3 className="font-bold text-gray-700 mb-2">Integrität prüfen</h3>
                    <p className="text-sm text-gray-500 mb-4">Prüft die Datenbank auf Korruption oder Fehler.</p>
                    <button 
                        onClick={handleIntegrityCheck} 
                        disabled={loading}
                        className="bg-slate-700 hover:bg-slate-800 text-white px-4 py-2 rounded text-sm font-bold w-full disabled:opacity-50"
                    >
                        {loading ? 'Prüfe...' : 'Jetzt prüfen'}
                    </button>
                    {checkResult.length > 0 && (
                        <div className="mt-4 bg-gray-50 p-2 rounded text-xs font-mono max-h-40 overflow-auto border border-gray-200">
                            {JSON.stringify(checkResult, null, 2)}
                        </div>
                    )}
                </div>

                {/* Vacuum */}
                <div className="bg-white p-6 rounded shadow-sm border border-gray-200">
                    <h3 className="font-bold text-gray-700 mb-2">Optimierung (VACUUM)</h3>
                    <p className="text-sm text-gray-500 mb-4">Reorganisiert die Datenbank und gibt nicht genutzten Speicherplatz frei.</p>
                     <button 
                        onClick={handleVacuum} 
                        disabled={loading}
                        className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded text-sm font-bold w-full disabled:opacity-50"
                    >
                        {loading ? 'Arbeite...' : 'Optimierung starten'}
                    </button>
                    {message && (
                        <div className="mt-4 text-sm text-green-700 font-bold text-center bg-green-50 p-2 rounded border border-green-200">
                            {message}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

