const CombinationsView = ({ vehicles = [], onCouple, onUncouple }: any) => {
    const [selectedMotor, setSelectedMotor] = useState('');
    const [selectedTrailer, setSelectedTrailer] = useState('');

    const isMotor = (v: Vehicle) => [VehicleType.LKW, VehicleType.TRANSPORTER, VehicleType.PKW, VehicleType.MASCHINE].includes(v.type as VehicleType);
    const isTrailer = (v: Vehicle) => [VehicleType.ANHAENGER, VehicleType.AUFLIEGER].includes(v.type as VehicleType);

    // Available Motor Vehicles (Not currently coupled)
    const availableMotors = vehicles.filter((v: Vehicle) => isMotor(v) && !v.coupledVehicleId);

    // Available Trailers (Not currently coupled)
    const availableTrailers = vehicles.filter((v: Vehicle) => isTrailer(v) && !v.coupledVehicleId);

    // Existing Combinations
    // We iterate through vehicles. If a vehicle has a coupledId, we show it. 
    // To avoid duplicates (since linkage is bidirectional), we only render from the "Motor" side perspective.
    const combinations = vehicles.filter((v: Vehicle) => isMotor(v) && v.coupledVehicleId).map((motor: Vehicle) => {
        const trailer = vehicles.find((t: Vehicle) => t.id === motor.coupledVehicleId);
        return { motor, trailer };
    });

    const handleCouple = () => {
        if(selectedMotor && selectedTrailer) {
            onCouple(selectedMotor, selectedTrailer);
            setSelectedMotor('');
            setSelectedTrailer('');
        }
    };

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-bold text-gray-800">Gespanne verwalten</h2>

            {/* Create New Combination */}
            <div className="bg-white p-6 rounded shadow-sm border border-gray-200">
                <h3 className="font-bold text-lg mb-4 text-gray-700 flex items-center gap-2">
                    <Icons.Link /> Neues Gespann bilden
                </h3>
                <div className="flex flex-col md:flex-row gap-4 items-end">
                    <div className="flex-1 w-full">
                        <label className="block text-sm font-bold text-gray-600 mb-1">Motorwagen / Zugmaschine</label>
                        <select 
                            className="w-full border border-gray-300 p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                            value={selectedMotor}
                            onChange={(e) => setSelectedMotor(e.target.value)}
                        >
                            <option value="">Bitte wählen...</option>
                            {availableMotors.map((v: Vehicle) => (
                                <option key={v.id} value={v.id}>{v.licensePlate} ({v.model})</option>
                            ))}
                        </select>
                    </div>
                    <div className="flex items-center justify-center pb-2 text-gray-400">
                        <Icons.Link />
                    </div>
                    <div className="flex-1 w-full">
                         <label className="block text-sm font-bold text-gray-600 mb-1">Anhänger / Auflieger</label>
                         <select 
                            className="w-full border border-gray-300 p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                            value={selectedTrailer}
                            onChange={(e) => setSelectedTrailer(e.target.value)}
                        >
                            <option value="">Bitte wählen...</option>
                            {availableTrailers.map((v: Vehicle) => (
                                <option key={v.id} value={v.id}>{v.licensePlate} ({v.type})</option>
                            ))}
                        </select>
                    </div>
                    <button 
                        onClick={handleCouple}
                        disabled={!selectedMotor || !selectedTrailer}
                        className={`px-6 py-2 rounded font-bold text-white transition-colors ${
                            selectedMotor && selectedTrailer ? 'bg-blue-600 hover:bg-blue-700' : 'bg-gray-300 cursor-not-allowed'
                        }`}
                    >
                        Koppeln
                    </button>
                </div>
            </div>

            {/* List Existing Combinations */}
            <div>
                <h3 className="font-bold text-gray-600 mb-3 uppercase tracking-wide text-sm">Aktuelle Gespanne</h3>
                <div className="bg-white rounded shadow border border-gray-200 overflow-hidden">
                    {combinations.length === 0 ? (
                         <div className="p-8 text-center text-gray-500 italic">Keine aktiven Gespanne.</div>
                    ) : (
                        <table className="w-full text-left">
                            <thead className="bg-gray-50 border-b border-gray-200 text-xs text-gray-500 uppercase">
                                <tr>
                                    <th className="p-3">Motorwagen</th>
                                    <th className="p-3">Anhänger</th>
                                    <th className="p-3 text-right">Aktion</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {combinations.map(({ motor, trailer }: any) => (
                                    <tr key={motor.id} className="hover:bg-gray-50">
                                        <td className="p-3">
                                            <div className="font-bold text-gray-800">{motor.licensePlate}</div>
                                            <div className="text-xs text-gray-500">{motor.manufacturer} {motor.model}</div>
                                        </td>
                                        <td className="p-3">
                                            {trailer ? (
                                                <>
                                                    <div className="font-bold text-gray-800">{trailer.licensePlate}</div>
                                                    <div className="text-xs text-gray-500">{trailer.type}</div>
                                                </>
                                            ) : (
                                                <span className="text-red-500 text-xs italic">Fahrzeug nicht gefunden (ID: {motor.coupledVehicleId})</span>
                                            )}
                                        </td>
                                        <td className="p-3 text-right">
                                            <button 
                                                onClick={() => onUncouple(motor.id, trailer?.id)}
