                                        <td className="p-3 text-right"><button onClick={() => onUncouple(motor.id, trailer?.id)} className="text-red-600 hover:bg-red-50 px-3 py-1 rounded text-sm font-medium border border-red-200">Trennen</button></td>
                                    </tr>
                                ))}
