     <div className="p-2">
         <div className="flex justify-between items-center mb-1">
             <span className={`inline-block px-1.5 py-0.5 rounded-[2px] text-[10px] font-bold uppercase tracking-wide ${isOverdue ? 'bg-red-600 text-white' : 'bg-blue-100 text-blue-800'}`}>{isOverdue ? 'ÜBERFÄLLIG' : 'Diesen Monat'}</span>
             <span className={`font-mono font-bold text-xs ${isOverdue ? 'text-red-700' : 'text-blue-600'}`}>{apt.date}</span>
         </div>
         <div className="mb-2"><div className="text-base font-bold text-gray-800 leading-tight truncate" title={apt.license}>{apt.license}</div><div className="text-[10px] text-gray-500 truncate">{apt.vehicleType}</div></div>
         <div className="flex items-center justify-between mt-2 pt-2 border-t border-gray-100/50">
             <span className={`px-1.5 py-0.5 rounded text-[10px] font-bold border ${getBadgeColor(apt.inspectionType)}`}>{apt.inspectionType}</span>
             <button onClick={() => onComplete(apt)} className={`flex items-center gap-1 text-white px-2 py-1 rounded shadow-sm transition-colors text-[10px] font-bold ${isOverdue ? 'bg-red-600 hover:bg-red-700' : 'bg-slate-700 hover:bg-slate-800'}`} title="Prüfung erledigen"><Icons.Check /><span className="hidden sm:inline">Erledigen</span></button>
         </div>
     </div>
 </div>
);

const StatusButton = ({ currentStatus, targetStatus, icon, colorClass, onClick, label }: any) => (
    <button onClick={onClick} className={`flex items-center gap-1 px-2 py-1 rounded text-xs font-bold border transition-all ${currentStatus === targetStatus ? colorClass : 'bg-white text-gray-400 border-gray-200 hover:bg-gray-50'}`} title={label}>
        {icon}<span className={currentStatus === targetStatus ? 'inline' : 'hidden xl:inline'}>{label}</span>
    </button>
);

export const AppointmentsView = ({ vehicles = [], onComplete }: any) => {
  const [selectedMonth, setSelectedMonth] = useState(getTodayDate().substring(0, 7));
  const safeVehicles = Array.isArray(vehicles) ? vehicles : [];

  const appointments = useMemo(() => {
    const list: any[] = [];
    safeVehicles.forEach((v: Vehicle) => {
      if (v.nextHU) list.push({ id: v.id + 'HU', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'HU', date: v.nextHU });
      if (v.nextSP) list.push({ id: v.id + 'SP', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'SP', date: v.nextSP });
      if (v.nextUVV) list.push({ id: v.id + 'UVV', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'UVV', date: v.nextUVV });
      if (v.nextTacho) list.push({ id: v.id + 'Tacho', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'Tacho', date: v.nextTacho });
    });
    return list.sort((a, b) => {
       const [ma, ya] = a.date.split('/'); const [mb, yb] = b.date.split('/');
       return new Date(parseInt(ya), parseInt(ma)-1).getTime() - new Date(parseInt(yb), parseInt(mb)-1).getTime();
    });
  }, [safeVehicles]);

  const { overdue, dueThisMonth, upcomingGrouped } = useMemo(() => {
    const ov: any[] = [], curr: any[] = [], up: any[] = [];
    appointments.forEach(apt => {
        const [m, y] = apt.date.split('/');
        const aptIso = `${y}-${m.padStart(2, '0')}`;
        if (aptIso < selectedMonth) ov.push({...apt, isOverdue: true});
        else if (aptIso === selectedMonth) curr.push({...apt, isOverdue: false});
        else up.push(apt);
    });
    const groups: Record<string, any[]> = {};
    up.forEach(apt => { if(!groups[apt.date]) groups[apt.date] = []; groups[apt.date].push(apt); });
    return { overdue: ov, dueThisMonth: curr, upcomingGrouped: groups };
  }, [appointments, selectedMonth]);

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-end justify-between border-b pb-2 gap-2">
          <div><h2 className="text-xl font-bold text-gray-800">Prüfungs-Monitor</h2><div className="text-xs text-gray-500 mt-0.5">Anzeige für: <span className="font-mono font-bold text-gray-700">{selectedMonth}</span></div></div>
          <div className="flex items-center gap-2 bg-white p-1 rounded border shadow-sm">
             <span className="text-xs font-bold text-gray-600">Monat:</span>
             <input type="month" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} className="border border-gray-300 rounded px-1 py-0.5 text-xs font-sans focus:outline-none" />
             {selectedMonth !== getTodayDate().substring(0, 7) && <button onClick={() => setSelectedMonth(getTodayDate().substring(0, 7))} className="ml-1 text-[10px] bg-blue-100 text-blue-700 px-2 py-1 rounded font-bold">Heute</button>}
          </div>
      </div>
      {overdue.length > 0 && (
          <div className="space-y-2 animate-pulse-once">
              <h3 className="font-bold text-red-700 text-sm flex items-center gap-2 bg-red-50 p-2 rounded border border-red-200"><Icons.Alert /> ÜBERFÄLLIG ({overdue.length})</h3>
              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-3">{overdue.map(apt => <AppointmentCard key={apt.id} apt={apt} isOverdue={true} onComplete={onComplete} />)}</div>
          </div>
      )}
      <div className="space-y-2">
          <h3 className="font-bold text-blue-800 text-sm flex items-center gap-2 border-b border-blue-200 pb-1"><Icons.Calendar /> FÄLLIG IM {selectedMonth} ({dueThisMonth.length})</h3>
          {dueThisMonth.length === 0 && <div className="bg-blue-50 border border-blue-100 text-blue-800 p-4 rounded text-center">📅 Nichts geplant</div>}
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-3">{dueThisMonth.map(apt => <AppointmentCard key={apt.id} apt={apt} isOverdue={false} onComplete={onComplete} />)}</div>
      </div>
      <div className="pt-6 border-t mt-4">
          <h3 className="text-sm font-bold text-gray-500 mb-4 uppercase tracking-wider">Vorschau (Quartalsansicht)</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
              {Object.keys(upcomingGrouped).length === 0 && <div className="col-span-full text-xs text-gray-400 italic">Keine späteren Termine.</div>}
              {Object.keys(upcomingGrouped).map(dateKey => (
                  <div key={dateKey} className="bg-white border border-gray-200 rounded shadow-sm flex flex-col h-full">
                      <div className="bg-gray-50 px-3 py-2 border-b border-gray-100 flex justify-between items-center"><span className="font-bold text-gray-700 text-sm">{dateKey}</span><span className="text-[10px] bg-white border border-gray-200 px-1.5 rounded text-gray-500 font-bold shadow-sm">{upcomingGrouped[dateKey].length}</span></div>
                      <div className="divide-y divide-gray-100 p-1">
                          {upcomingGrouped[dateKey].map(apt => (
                              <div key={apt.id} className="p-2 flex justify-between items-center hover:bg-gray-50 transition-colors rounded">
                                  <div className="flex items-center gap-2 overflow-hidden"><div className={`shrink-0 w-9 text-center text-[9px] font-bold px-0.5 py-0.5 rounded border ${getBadgeColor(apt.inspectionType)}`}>{apt.inspectionType}</div><div className="min-w-0"><div className="font-bold text-gray-800 text-xs truncate">{apt.license}</div><div className="text-[9px] text-gray-500 truncate">{apt.vehicleType}</div></div></div>
                                  <button onClick={() => onComplete(apt)} className="text-gray-300 hover:text-green-600 p-1.5 hover:bg-green-50 rounded transition-colors" title="Jetzt schon erledigen"><Icons.Check /></button>
                              </div>
                          ))}
                      </div>
                  </div>
              ))}
          </div>
      </div>
    </div>
  );
};

export const OrdersView = ({ orders, vehicles = [], onAdd, onEdit, onStatusChange, onDelete }: any) => {
  const safeVehicles = Array.isArray(vehicles) ? vehicles : [];
  const [showCompleted, setShowCompleted] = useState(false);

  const filteredOrders = useMemo(() => {
    return orders.filter((o: Order) => {
        if (!showCompleted && o.status === OrderStatus.ERLEDIGT) return false;
        return true;
    }).sort((a: Order, b: Order) => {
       const vA = safeVehicles.find((v:Vehicle) => v.id === a.vehicleId);
       const vB = safeVehicles.find((v:Vehicle) => v.id === b.vehicleId);
       const plateCompare = (vA?.licensePlate || 'ZZZ').localeCompare(vB?.licensePlate || 'ZZZ');
       if (plateCompare !== 0) return plateCompare;
       return getPrioritySortValue(a.description) - getPrioritySortValue(b.description);
    });
  }, [orders, safeVehicles, showCompleted]);

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center bg-white p-3 rounded shadow-sm border border-gray-200">
        <h2 className="text-xl font-bold text-gray-800">Bestellungen</h2>
        <div className="flex gap-2">
            <button onClick={() => setShowCompleted(!showCompleted)} className={`p-2 rounded border transition-colors ${showCompleted ? 'bg-blue-50 text-blue-600 border-blue-200' : 'bg-white text-gray-400 border-gray-200 hover:border-gray-300'}`}>{showCompleted ? <Icons.Eye /> : <Icons.EyeOff />}</button>
            <button onClick={onAdd} className="bg-blue-600 hover:bg-blue-700 text-white px-3 py-1.5 rounded flex items-center gap-2 shadow-sm font-bold text-sm"><Icons.Plus /> Neu</button>
        </div>
      </div>
      <div className="bg-white rounded shadow border border-gray-200 overflow-hidden">
        {filteredOrders.length === 0 && <div className="p-12 text-center text-gray-400 italic">Keine Bestellungen vorhanden.</div>}
        {filteredOrders.map((o: Order) => {
            const vehicle = safeVehicles.find((v:Vehicle) => v.id === o.vehicleId);
            const isUrgent = o.description.includes('[Dringend]');
            const isLow = o.description.includes('[Niedrig]');
            return (
              <div key={o.id} className="p-4 border-b last:border-b-0 flex flex-col md:flex-row md:items-center justify-between hover:bg-gray-50 gap-4 transition-colors">
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-2"><span className="font-bold text-lg text-gray-800 bg-gray-100 px-2 py-0.5 rounded border border-gray-200">{vehicle?.licensePlate || 'Lager/Allgemein'}</span>{(isUrgent || isLow) && <span className={`px-2 py-0.5 rounded text-xs font-bold uppercase tracking-wider ${isUrgent ? 'bg-red-100 text-red-800 border border-red-200' : 'bg-gray-100 text-gray-600 border border-gray-200'}`}>{isUrgent ? 'Dringend' : 'Niedrig'}</span>}</div>
                  <div className={`font-normal text-gray-700 whitespace-pre-wrap ${o.status === OrderStatus.ERLEDIGT ? 'line-through text-gray-400' : ''}`}>{o.description.replace(/\[Dringend\]|\[Niedrig\]/g, '').trim()}</div>
                  <div className="text-[10px] text-gray-400 mt-1 flex gap-2"><span>Erstellt: {o.dateAdded}</span></div>
                </div>
                <div className="flex items-center gap-4 self-end md:self-center">
                    <div className="flex bg-gray-100 p-1 rounded-md gap-1">
                        <StatusButton currentStatus={o.status} targetStatus={OrderStatus.OFFEN} label="Offen" icon={<Icons.Box />} colorClass="bg-white text-gray-700 shadow-sm border-gray-300" onClick={() => onStatusChange(o.id, OrderStatus.OFFEN)} />
                        <StatusButton currentStatus={o.status} targetStatus={OrderStatus.BESTELLT} label="Bestellt" icon={<Icons.FileText />} colorClass="bg-blue-100 text-blue-700 border-blue-200" onClick={() => onStatusChange(o.id, OrderStatus.BESTELLT)} />
                        <StatusButton currentStatus={o.status} targetStatus={OrderStatus.ERLEDIGT} label="Erledigt" icon={<Icons.CheckCircle />} colorClass="bg-green-100 text-green-700 border-green-200" onClick={() => onStatusChange(o.id, OrderStatus.ERLEDIGT)} />
                    </div>
                    <div className="flex gap-1 border-l pl-4 border-gray-200"><button onClick={() => onEdit(o)} className="text-blue-400 hover:text-blue-600 p-1.5 hover:bg-blue-50 rounded" title="Bearbeiten"><Icons.Edit /></button><button onClick={() => onDelete(o.id)} className="text-red-300 hover:text-red-600 p-1.5 hover:bg-red-50 rounded" title="Löschen"><Icons.Trash /></button></div>
                </div>
              </div>
            );
        })}
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { LogEntry, Vehicle, VehicleType } from '../types';
import { Icons } from '../icons';
import { api, getIsOfflineMode } from '../api';

export const HistoryView = ({ logs, vehicles = [], isAdmin, onEdit, onDelete }: any) => {
  const [filters, setFilters] = useState({ text: '', licensePlate: '', type: '', category: '' });
  const safeVehicles = Array.isArray(vehicles) ? vehicles : [];

  const completedLogs = useMemo(() => {
      return logs.filter((l: LogEntry) => {
        if (l.status !== 'DONE') return false;
        const vehicle = safeVehicles.find((v:Vehicle) => v.id === l.vehicleId);
        const plate = vehicle?.licensePlate || '';
        const vType = vehicle?.type || '';
        if (filters.text && !l.description.toLowerCase().includes(filters.text.toLowerCase())) return false;
        if (filters.licensePlate && !plate.toLowerCase().includes(filters.licensePlate.toLowerCase())) return false;
        if (filters.type && vType !== filters.type) return false;
        if (filters.category === 'inspection' && (!l.inspectionType && l.type !== 'Wartung')) return false;
        if (filters.category === 'task' && (l.inspectionType || l.type === 'Wartung')) return false;
        return true;
      }).sort((a: LogEntry, b: LogEntry) => (b.dateCompleted || '').localeCompare(a.dateCompleted || ''));
  }, [logs, safeVehicles, filters]);

  return (
    <div className="space-y-4">
      <div className="bg-white p-3 rounded shadow-sm border border-gray-200 flex flex-col md:flex-row md:items-center justify-between gap-3">
        <h2 className="text-xl font-bold text-gray-800">Historie</h2>
        <div className="flex flex-wrap items-center gap-2">
           <div className="relative group"><span className="absolute left-2.5 top-2 text-gray-400 pointer-events-none"><Icons.Search /></span><input type="text" placeholder="Stichwort..." className="w-32 md:w-48 pl-8 pr-2 py-1.5 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none" value={filters.text} onChange={e => setFilters({...filters, text: e.target.value})} /></div>
           <div className="relative group"><span className="absolute left-2.5 top-2 text-gray-400 pointer-events-none"><Icons.Truck /></span><input type="text" placeholder="Kennzeichen..." className="w-32 md:w-40 pl-8 pr-2 py-1.5 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none" value={filters.licensePlate} onChange={e => setFilters({...filters, licensePlate: e.target.value})} /></div>
           <div className="relative"><select className="w-32 py-1.5 pl-2 pr-6 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none bg-white text-gray-600 cursor-pointer" value={filters.type} onChange={e => setFilters({...filters, type: e.target.value})}><option value="">Alle Arten</option>{Object.values(VehicleType).map(t => <option key={t} value={t}>{t}</option>)}</select></div>
           <div className="relative"><select className="w-36 py-1.5 pl-2 pr-6 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none bg-white text-gray-600 cursor-pointer" value={filters.category} onChange={e => setFilters({...filters, category: e.target.value})}><option value="">Alle Einträge</option><option value="inspection">Nur Prüfungen</option><option value="task">Nur Aufgaben</option></select></div>
           {(filters.text || filters.licensePlate || filters.type || filters.category) && <button onClick={() => setFilters({text: '', licensePlate: '', type: '', category: ''})} className="text-gray-400 hover:text-red-500 p-1.5 rounded hover:bg-red-50" title="Filter löschen"><Icons.Trash /></button>}
        </div>
      </div>
      <div className="bg-white rounded shadow border border-gray-200 overflow-hidden">
        {completedLogs.length === 0 ? <div className="p-8 text-center text-gray-500 italic">Keine Einträge gefunden.</div> : (
            <div className="divide-y divide-gray-100">
                {completedLogs.map((l: LogEntry) => {
                    const vehicle = safeVehicles.find((v:Vehicle) => v.id === l.vehicleId);
                    return (
                        <div key={l.id} className="p-2 border-b last:border-b-0 border-gray-100 hover:bg-gray-50 transition-colors">
                            <div className="flex justify-between items-start">
                                <div className="flex-1 min-w-0 pr-4">
                                    <div className="flex items-center gap-2 mb-0.5 flex-wrap"><span className="text-sm text-gray-900 font-medium">{vehicle ? vehicle.licensePlate : 'Allgemein / Gelöscht'}</span><span className="text-xs text-gray-400">{l.dateCompleted}</span>{l.mileage && <span className="text-[10px] text-gray-500 bg-gray-50 border border-gray-200 px-1.5 py-0.5 rounded font-mono">KM: {l.mileage}</span>}{vehicle && <span className="text-[10px] text-gray-400 px-1 border border-gray-200 rounded">{vehicle.type}</span>}</div>
                                    <div className="text-sm text-gray-600 whitespace-pre-wrap leading-tight">{l.description}</div>
                                    {l.inspectionType && <div className="mt-1"><span className="text-[10px] px-1.5 py-0.5 rounded border bg-purple-50 text-purple-700 border-purple-200">{l.inspectionType}</span></div>}
                                </div>
                                {isAdmin && <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity self-center"><button onClick={() => onEdit(l)} className="text-gray-400 hover:text-blue-600"><Icons.Edit /></button><button onClick={() => onDelete(l.id)} className="text-gray-400 hover:text-red-600"><Icons.Trash /></button></div>}
                            </div>
                         </div>
                    );
                })}
            </div>
        )}
      </div>
    </div>
  );
};

export const AdminView = () => {
    const [dbStats, setDbStats] = useState<any>(null);
    const [checkResult, setCheckResult] = useState<any[]>([]);
    const [loading, setLoading] = useState(false);
    const [message, setMessage] = useState('');
    const offline = getIsOfflineMode();
    const [isAuthenticated, setIsAuthenticated] = useState(false);
    const [passwordInput, setPasswordInput] = useState('');
    const [loginError, setLoginError] = useState('');

    const fetchStats = async () => { try { const data = await api.get('/admin/db-stats'); setDbStats(data); } catch(e) { console.error(e); } };
    useEffect(() => { if(!offline && isAuthenticated) fetchStats(); }, [offline, isAuthenticated]);

    const handleIntegrityCheck = async () => {
        setLoading(true); setMessage('');
        try { const res = await api.get('/admin/db-check'); setCheckResult(Array.isArray(res) ? res : []); } catch(e) { setMessage('Fehler bei der Prüfung.'); } finally { setLoading(false); }
    };

    const handleVacuum = async () => {
         if(!confirm("Diese Aktion reorganisiert die Datenbank...")) return;
         setLoading(true); setMessage('');
         try { const res = await api.post('/admin/db-vacuum', {}); if(res.success) { setMessage('Optimierung erfolgreich.'); fetchStats(); } } catch(e) { setMessage('Fehler.'); } finally { setLoading(false); }
    };

    if (offline) return <div className="p-8 text-center bg-white rounded border border-gray-200"><Icons.WifiOff /><h2 className="text-lg font-bold mt-2">Admin-Modus nicht verfügbar</h2></div>;

    if (!isAuthenticated) {
        return (
            <div className="max-w-md mx-auto mt-20 bg-white p-8 rounded shadow-md border border-gray-200">
                <h2 className="text-2xl font-bold text-gray-800 mb-6 flex items-center gap-2"><Icons.Lock /> Admin-Bereich</h2>
                <form onSubmit={(e) => { e.preventDefault(); if(passwordInput === 'administrator') { setIsAuthenticated(true); setLoginError(''); } else { setLoginError('Falsches Passwort.'); } }}>
                    <input type="password" className="w-full border border-gray-300 p-2 rounded mb-4" placeholder="Passwort" value={passwordInput} onChange={e => setPasswordInput(e.target.value)} autoFocus />
                    {loginError && <div className="text-red-600 text-sm mb-4 font-bold">{loginError}</div>}
                    <button type="submit" className="w-full bg-blue-600 text-white font-bold py-2 rounded hover:bg-blue-700">Anmelden</button>
                </form>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2"><Icons.Database /> Datenbank Wartung</h2>
            <div className="bg-white p-6 rounded shadow-sm border border-gray-200">
                 <h3 className="font-bold text-gray-700 mb-4 border-b pb-2">Status</h3>
                 <div className="grid grid-cols-2 gap-4"><div><div className="text-sm text-gray-500 uppercase font-bold">Größe</div><div className="text-2xl font-mono text-blue-600">{dbStats?.size || '-'}</div></div><div><div className="text-sm text-gray-500 uppercase font-bold">Backend</div><div className="text-lg font-bold text-green-600">Online</div></div></div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-white p-6 rounded shadow-sm border border-gray-200">
                    <h3 className="font-bold text-gray-700 mb-2">Integrität prüfen</h3>
                    <button onClick={handleIntegrityCheck} disabled={loading} className="bg-slate-700 hover:bg-slate-800 text-white px-4 py-2 rounded text-sm font-bold w-full disabled:opacity-50">{loading ? 'Prüfe...' : 'Jetzt prüfen'}</button>
                    {checkResult.length > 0 && <div className="mt-4 bg-gray-50 p-2 rounded text-xs font-mono max-h-40 overflow-auto border border-gray-200">{JSON.stringify(checkResult, null, 2)}</div>}
                </div>
                <div className="bg-white p-6 rounded shadow-sm border border-gray-200">
                    <h3 className="font-bold text-gray-700 mb-2">Optimierung (VACUUM)</h3>
                     <button onClick={handleVacuum} disabled={loading} className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded text-sm font-bold w-full disabled:opacity-50">{loading ? 'Arbeite...' : 'Optimierung starten'}</button>
                    {message && <div className="mt-4 text-sm text-green-700 font-bold text-center bg-green-50 p-2 rounded border border-green-200">{message}</div>}
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useCallback } from 'react';
import { createRoot } from 'react-dom/client';
import { Vehicle, LogEntry, Order, OrderStatus, Priority } from './types';
import { Icons } from './icons';
import { api, getIsOfflineMode } from './api';
import { getTodayDate } from './utils';

// Components
import { ErrorBoundary, NavButton } from './components/Common';
import { VehicleModal, EntryModal, OrderModal, InspectionModal, CompletionModal } from './components/Modals';

// Views
import { DashboardView } from './views/DashboardView';
import { VehicleListView, CombinationsView } from './views/VehicleView';
import { AppointmentsView, OrdersView } from './views/PlanningView';
import { HistoryView, AdminView } from './views/ReportView';

const App = () => {
    const [view, setView] = useState('dashboard');
    const [vehicles, setVehicles] = useState<Vehicle[]>([]);
    const [logs, setLogs] = useState<LogEntry[]>([]);
    const [orders, setOrders] = useState<Order[]>([]);
    const [loading, setLoading] = useState(true);

    // Modal States
    const [vehicleModal, setVehicleModal] = useState({ open: false, data: null as Vehicle | null });
    const [entryModal, setEntryModal] = useState({ open: false, data: null as LogEntry | null });
    const [orderModal, setOrderModal] = useState({ open: false, data: null as Order | null });
    const [inspectionModal, setInspectionModal] = useState({ open: false, data: null as LogEntry | null });
    const [completionModal, setCompletionModal] = useState({ open: false, data: null as LogEntry | null });

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const [v, l, o] = await Promise.all([
                api.get('/vehicles'),
                api.get('/logs'),
                api.get('/orders')
            ]);
            setVehicles(Array.isArray(v) ? v : []);
            setLogs(Array.isArray(l) ? l : []);
            setOrders(Array.isArray(o) ? o : []);
        } catch (e) {
            console.error(e);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => { loadData(); }, [loadData]);

    const saveVehicle = async (v: Vehicle) => {
        if(v.id && vehicles.find(x => x.id === v.id)) await api.put(`/vehicles/${v.id}`, v);
        else await api.post('/vehicles', v);
        setVehicleModal({ open: false, data: null });
        loadData();
    };

    const deleteVehicle = async (id: string) => {
        if(confirm('Fahrzeug wirklich löschen?')) { await api.delete(`/vehicles/${id}`); loadData(); }
    };

    const saveEntry = async (entries: any[]) => {
        for (const entry of entries) {
            if(entry.id && logs.find(x => x.id === entry.id)) await api.put(`/logs/${entry.id}`, entry);
            else await api.post('/logs', entry);
        }
        setEntryModal({ open: false, data: null });
        loadData();
    };

    const updateLogStatus = async (log: LogEntry, newStatus: 'IN_PROGRESS' | 'DONE') => {
        if (newStatus === 'DONE') { setCompletionModal({ open: true, data: log }); return; }
        await api.put(`/logs/${log.id}`, { ...log, status: newStatus });
        loadData();
    };

    const finalizeCompletion = async (log: LogEntry, mileage: number) => {
        await api.put(`/logs/${log.id}`, { ...log, status: 'DONE', dateCompleted: getTodayDate(), mileage: mileage });
        const vehicle = vehicles.find(v => v.id === log.vehicleId);
        if(vehicle && mileage > (vehicle.currentMileage || 0)) await api.put(`/vehicles/${vehicle.id}`, { ...vehicle, currentMileage: mileage });
        setCompletionModal({ open: false, data: null });
        loadData();
    };

    const completeInspection = async (log: LogEntry, nextDate: string) => {
        const [y, m] = nextDate.split('-');
        await api.post('/logs', {
            vehicleId: log.vehicleId, type: 'Wartung', description: `${log.inspectionType} Prüfung durchgeführt`,
            priority: Priority.NORMAL, dateAdded: getTodayDate(), status: 'DONE', dateCompleted: getTodayDate(), inspectionType: log.inspectionType
        });
        const vehicle = vehicles.find(v => v.id === log.vehicleId);
        if (vehicle) {
            await api.put(`/vehicles/${vehicle.id}`, { ...vehicle, [`next${log.inspectionType}`]: `${m}/${y}` });
        }
        setInspectionModal({ open: false, data: null });
        loadData();
    };

    const deleteLog = async (id: string) => { if(confirm('Eintrag löschen?')) { await api.delete(`/logs/${id}`); loadData(); } };

    const saveOrder = async (ordersList: any[]) => {
        for (const o of ordersList) {
             if(o.id && orders.find(x => x.id === o.id)) await api.put(`/orders/${o.id}`, o);
             else await api.post('/orders', o);
        }
        setOrderModal({ open: false, data: null });
        loadData();
    };

    const updateOrderStatus = async (id: string, status: OrderStatus) => {
        const order = orders.find(o => o.id === id);
        if(order) { await api.put(`/orders/${id}`, { ...order, status }); loadData(); }
    };

    const deleteOrder = async (id: string) => { if(confirm('Bestellung löschen?')) { await api.delete(`/orders/${id}`); loadData(); } };

    const coupleVehicles = async (motorId: string, trailerId: string) => {
        const motor = vehicles.find(v => v.id === motorId), trailer = vehicles.find(v => v.id === trailerId);
        if(motor && trailer) {
            await api.put(`/vehicles/${motor.id}`, { ...motor, coupledVehicleId: trailer.id });
            await api.put(`/vehicles/${trailer.id}`, { ...trailer, coupledVehicleId: motor.id });
            loadData();
        }
    };

    const uncoupleVehicles = async (motorId: string, trailerId: string) => {
        const motor = vehicles.find(v => v.id === motorId);
        if(motor) await api.put(`/vehicles/${motor.id}`, { ...motor, coupledVehicleId: null });
        if(trailerId) {
            const trailer = vehicles.find(v => v.id === trailerId);
            if(trailer) await api.put(`/vehicles/${trailer.id}`, { ...trailer, coupledVehicleId: null });
        }
        loadData();
    };

    return (
        <div className="flex h-full bg-gray-100 font-sans text-gray-900">
            <div className="w-64 bg-slate-800 text-white flex flex-col shadow-xl z-10 no-print">
                <div className="p-6 border-b border-slate-700">
                    <h1 className="text-xl font-bold tracking-tight">Fuhrpark<span className="text-blue-400">Manager</span></h1>
                </div>
                <nav className="flex-1 p-4 space-y-2">
                    <NavButton icon={<Icons.Dashboard />} label="ToDo" active={view === 'dashboard'} onClick={() => setView('dashboard')} />
                    <NavButton icon={<Icons.Calendar />} label="Termine" active={view === 'appointments'} onClick={() => setView('appointments')} />
                    <NavButton icon={<Icons.ShoppingCart />} label="Bestellungen" active={view === 'orders'} onClick={() => setView('orders')} />
                    <NavButton icon={<Icons.History />} label="Historie" active={view === 'history'} onClick={() => setView('history')} />
                    <NavButton icon={<Icons.Link />} label="Gespanne" active={view === 'combinations'} onClick={() => setView('combinations')} />
                    <NavButton icon={<Icons.Truck />} label="Fahrzeuge" active={view === 'vehicles'} onClick={() => setView('vehicles')} />
                    <div className="pt-4 mt-4 border-t border-slate-700">
                        <NavButton icon={<Icons.Database />} label="Admin" active={view === 'admin'} onClick={() => setView('admin')} />
                    </div>
                </nav>
                <div className="p-4 border-t border-slate-700 text-xs text-slate-400">v2.3.0 • {getIsOfflineMode() ? 'Offline Mode' : 'Online'}</div>
            </div>

            <div className="flex-1 flex flex-col h-full overflow-hidden">
                <header className="bg-white shadow-sm border-b px-8 py-4 flex justify-between items-center no-print">
                     <h2 className="text-xl font-bold text-gray-800 capitalize">{view === 'dashboard' ? 'ToDo' : view}</h2>
                     <button onClick={loadData} className="p-2 text-gray-500 hover:bg-gray-100 rounded" title="Refresh"><Icons.History /></button>
                </header>

                <main className="flex-1 overflow-auto p-8">
                    <ErrorBoundary>
                        {loading ? <div className="flex justify-center items-center h-full text-gray-400">Laden...</div> : (
                            <>
                                {view === 'dashboard' && <DashboardView logs={logs} vehicles={vehicles} onAdd={() => setEntryModal({open:true, data:null})} onInspect={(l:any) => setInspectionModal({open: true, data: l})} onStatusUpdate={updateLogStatus} onEdit={(l:any) => setEntryModal({open:true, data:l})} onDelete={deleteLog} />}
                                {view === 'vehicles' && <VehicleListView vehicles={vehicles} onAdd={() => setVehicleModal({open:true, data:null})} onEdit={(v:any) => setVehicleModal({open:true, data:v})} onDelete={deleteVehicle} />}
                                {view === 'combinations' && <CombinationsView vehicles={vehicles} onCouple={coupleVehicles} onUncouple={uncoupleVehicles} />}
                                {view === 'appointments' && <AppointmentsView vehicles={vehicles} onComplete={(apt: any) => {
                                    setInspectionModal({ open: true, data: { id: `virt_${apt.vid}_${apt.inspectionType}`, vehicleId: apt.vid, type: 'Prüfung', description: `${apt.inspectionType} Fällig (${apt.date})`, priority: Priority.NORMAL, dateAdded: getTodayDate(), status: 'OPEN', inspectionType: apt.inspectionType, isVirtual: true } as LogEntry });
                                }} />}
                                {view === 'orders' && <OrdersView orders={orders} vehicles={vehicles} onAdd={() => setOrderModal({open:true, data:null})} onEdit={(o:any) => setOrderModal({open:true, data:o})} onStatusChange={updateOrderStatus} onDelete={deleteOrder} />}
                                {view === 'history' && <HistoryView logs={logs} vehicles={vehicles} isAdmin={true} onEdit={(l:any) => setEntryModal({open:true, data:l})} onDelete={deleteLog} />}
                                {view === 'admin' && <AdminView />}
                            </>
                        )}
                    </ErrorBoundary>
                </main>
            </div>

            <VehicleModal isOpen={vehicleModal.open} onClose={() => setVehicleModal({open:false, data:null})} vehicle={vehicleModal.data} onSave={saveVehicle} />
            <EntryModal isOpen={entryModal.open} onClose={() => setEntryModal({open:false, data:null})} entry={entryModal.data} vehicles={vehicles} onSave={saveEntry} />
            <OrderModal isOpen={orderModal.open} onClose={() => setOrderModal({open:false, data:null})} order={orderModal.data} vehicles={vehicles} onSave={saveOrder} />
            <InspectionModal isOpen={inspectionModal.open} onClose={() => setInspectionModal({open:false, data:null})} log={inspectionModal.data} onSave={completeInspection} />
            <CompletionModal isOpen={completionModal.open} onClose={() => setCompletionModal({open:false, data:null})} log={completionModal.data} onConfirm={finalizeCompletion} />
        </div>
    );
};

const container = document.getElementById('root');
const root = createRoot(container!);
root.render(<App />);

import { useState, useEffect, useCallback } from 'react';
import { Vehicle, LogEntry, Order, OrderStatus, Priority } from '../types';
import { api } from '../api';
import { getTodayDate } from '../utils';

export const useFleetData = () => {
    const [vehicles, setVehicles] = useState<Vehicle[]>([]);
    const [logs, setLogs] = useState<LogEntry[]>([]);
    const [orders, setOrders] = useState<Order[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    const loadData = useCallback(async () => {
        setLoading(true);
        setError(null);
        try {
            const [v, l, o] = await Promise.all([
                api.get('/vehicles'),
                api.get('/logs'),
                api.get('/orders')
            ]);
            setVehicles(Array.isArray(v) ? v : []);
            setLogs(Array.isArray(l) ? l : []);
            setOrders(Array.isArray(o) ? o : []);
        } catch (e: any) {
            console.error(e);
            setError(e.message || "Fehler beim Laden der Daten");
        } finally {
            setLoading(false);
        }
    }, []);

    // Initial Load
    useEffect(() => { loadData(); }, [loadData]);

    // --- VEHICLE OPERATIONS ---

    const saveVehicle = async (v: Vehicle) => {
        try {
            if(v.id && vehicles.find(x => x.id === v.id)) {
                await api.put(`/vehicles/${v.id}`, v);
            } else {
                await api.post('/vehicles', v);
            }
            await loadData();
            return true;
        } catch (e) { console.error(e); return false; }
    };

    const deleteVehicle = async (id: string) => {
        if(!confirm('Fahrzeug wirklich löschen?')) return false;
        try {
            await api.delete(`/vehicles/${id}`);
            await loadData();
            return true;
        } catch (e) { console.error(e); return false; }
    };

    const coupleVehicles = async (motorId: string, trailerId: string) => {
        const motor = vehicles.find(v => v.id === motorId);
        const trailer = vehicles.find(v => v.id === trailerId);
        if(motor && trailer) {
            await api.put(`/vehicles/${motor.id}`, { ...motor, coupledVehicleId: trailer.id });
            await api.put(`/vehicles/${trailer.id}`, { ...trailer, coupledVehicleId: motor.id });
            await loadData();
        }
    };

    const uncoupleVehicles = async (motorId: string, trailerId?: string) => {
        const motor = vehicles.find(v => v.id === motorId);
        if(motor) await api.put(`/vehicles/${motor.id}`, { ...motor, coupledVehicleId: null });

        if(trailerId) {
            const trailer = vehicles.find(v => v.id === trailerId);
            if(trailer) await api.put(`/vehicles/${trailer.id}`, { ...trailer, coupledVehicleId: null });
        }
        await loadData();
    };

    // --- LOG / TASK OPERATIONS ---

    const saveLogEntry = async (entries: any[]) => {
        try {
            for (const entry of entries) {
                if(entry.id && logs.find(x => x.id === entry.id)) {
                    await api.put(`/logs/${entry.id}`, entry);
                } else {
                    await api.post('/logs', entry);
                }
            }
            await loadData();
            return true;
        } catch (e) { console.error(e); return false; }
    };

    const updateLogStatus = async (log: LogEntry, newStatus: 'IN_PROGRESS' | 'DONE') => {
        try {
            await api.put(`/logs/${log.id}`, { ...log, status: newStatus });
            await loadData();
        } catch (e) { console.error(e); }
    };

    const deleteLog = async (id: string) => {
        if(!confirm('Eintrag löschen?')) return false;
        try {
            await api.delete(`/logs/${id}`);
            await loadData();
            return true;
        } catch (e) { console.error(e); return false; }
    };

    // --- BUSINESS LOGIC: COMPLETIONS ---

    // Completes a generic task and updates vehicle mileage
    const completeTask = async (log: LogEntry, mileage: number) => {
        try {
            // 1. Update Log
            await api.put(`/logs/${log.id}`, { 
                ...log, 
                status: 'DONE', 
                dateCompleted: getTodayDate(), 
                mileage: mileage 
            });

            // 2. Update Vehicle Mileage (Business Logic: Only update if higher)
            const vehicle = vehicles.find(v => v.id === log.vehicleId);
            if(vehicle && mileage > (vehicle.currentMileage || 0)) {
                await api.put(`/vehicles/${vehicle.id}`, { ...vehicle, currentMileage: mileage });
            }

            await loadData();
            return true;
        } catch(e) { console.error(e); return false; }
    };

    // Completes an inspection and calculates next date
    const completeInspection = async (log: LogEntry, nextDate: string) => {
        try {
            const [y, m] = nextDate.split('-'); // YYYY-MM from input

            // 1. Create archival log
            await api.post('/logs', {
                vehicleId: log.vehicleId,
                type: 'Wartung',
                description: `${log.inspectionType} Prüfung durchgeführt`,
                priority: Priority.NORMAL,
                dateAdded: getTodayDate(),
                status: 'DONE',
                dateCompleted: getTodayDate(),
                inspectionType: log.inspectionType
            });

            // 2. Update Vehicle Next Date
            const vehicle = vehicles.find(v => v.id === log.vehicleId);
            if (vehicle && log.inspectionType) {
                // Determine which field to update based on inspection type
                const updateField = `next${log.inspectionType}`; 
                // Store as MM/YYYY
                await api.put(`/vehicles/${vehicle.id}`, { ...vehicle, [updateField]: `${m}/${y}` });
            }

            await loadData();
            return true;
        } catch(e) { console.error(e); return false; }
    };

    // --- ORDER OPERATIONS ---

    const saveOrder = async (ordersList: any[]) => {
        try {
            for (const o of ordersList) {
                if(o.id && orders.find(x => x.id === o.id)) {
                    await api.put(`/orders/${o.id}`, o);
                } else {
                    await api.post('/orders', o);
                }
            }
            await loadData();
            return true;
        } catch (e) { console.error(e); return false; }
    };

    const updateOrderStatus = async (id: string, status: OrderStatus) => {
        const order = orders.find(o => o.id === id);
        if(order) {
            await api.put(`/orders/${id}`, { ...order, status });
            await loadData();
        }
    };

    const deleteOrder = async (id: string) => {
        if(!confirm('Bestellung löschen?')) return false;
        try {
            await api.delete(`/orders/${id}`);
            await loadData();
            return true;
        } catch (e) { console.error(e); return false; }
    };

    return {
        // State
        vehicles,
        logs,
        orders,
        loading,
        error,

        // Actions
        loadData,
        saveVehicle,
        deleteVehicle,
        coupleVehicles,
        uncoupleVehicles,

        saveLogEntry,
        updateLogStatus,
        deleteLog,
        completeTask,
        completeInspection,

        saveOrder,
        updateOrderStatus,
        deleteOrder
    };
};

import React, { useState } from 'react';
import { createRoot } from 'react-dom/client';
import { Vehicle, LogEntry, Order, Priority } from './types';
import { Icons } from './icons';
import { getIsOfflineMode } from './api';
import { getTodayDate } from './utils';

// Hooks
import { useFleetData } from './hooks/useFleetData';

// Components
import { ErrorBoundary, NavButton } from './components/Common';
import { VehicleModal, EntryModal, OrderModal, InspectionModal, CompletionModal } from './components/Modals';

// Views
import { DashboardView } from './views/DashboardView';
import { VehicleListView, CombinationsView } from './views/VehicleView';
import { AppointmentsView, OrdersView } from './views/PlanningView';
import { HistoryView, AdminView } from './views/ReportView';

const App = () => {
    const [view, setView] = useState('dashboard');

    // Use Custom Hook for Data & Business Logic
    const { 
        vehicles, logs, orders, loading, loadData,
        saveVehicle, deleteVehicle, coupleVehicles, uncoupleVehicles,
        saveLogEntry, updateLogStatus, deleteLog, completeTask, completeInspection,
        saveOrder, updateOrderStatus, deleteOrder
    } = useFleetData();

    // Modal UI States (Only UI concern left here)
