            {/* Main Content */}
            <div className="flex-1 flex flex-col h-full overflow-hidden">
                <header className="bg-white shadow-sm border-b px-8 py-4 flex justify-between items-center no-print">
                     <h2 className="text-xl font-bold text-gray-800 capitalize">{view === 'dashboard' ? 'ToDo' : view}</h2>
                     <button onClick={loadData} className="p-2 text-gray-500 hover:bg-gray-100 rounded" title="Refresh"><Icons.History /></button>
                </header>

                <main className="flex-1 overflow-auto p-8">
                    <ErrorBoundary>
                        {loading ? <div className="flex justify-center items-center h-full text-gray-400">Laden...</div> : (
                            <>
                                {view === 'dashboard' && (
                                    <DashboardView 
                                        logs={logs} 
                                        vehicles={vehicles} 
                                        onAdd={() => setEntryModal({open:true, data:null})} 
                                        onInspect={(l:any) => setInspectionModal({open: true, data: l})} 
                                        onStatusUpdate={handleStatusUpdate} 
                                        onEdit={(l:any) => setEntryModal({open:true, data:l})} 
                                        onDelete={deleteLog} 
                                    />
                                )}
                                {view === 'vehicles' && (
                                    <VehicleListView 
                                        vehicles={vehicles} 
                                        onAdd={() => setVehicleModal({open:true, data:null})} 
                                        onEdit={(v:any) => setVehicleModal({open:true, data:v})} 
                                        onDelete={deleteVehicle} 
                                    />
                                )}
                                {view === 'combinations' && (
                                    <CombinationsView 
                                        vehicles={vehicles} 
                                        onCouple={coupleVehicles} 
                                        onUncouple={uncoupleVehicles} 
                                    />
                                )}
                                {view === 'appointments' && (
                                    <AppointmentsView 
                                        vehicles={vehicles} 
                                        onComplete={(apt: any) => {
                                            setInspectionModal({ open: true, data: { id: `virt_${apt.vid}_${apt.inspectionType}`, vehicleId: apt.vid, type: 'Prüfung', description: `${apt.inspectionType} Fällig (${apt.date})`, priority: Priority.NORMAL, dateAdded: getTodayDate(), status: 'OPEN', inspectionType: apt.inspectionType, isVirtual: true } as LogEntry });
                                        }} 
                                    />
                                )}
                                {view === 'orders' && (
                                    <OrdersView 
                                        orders={orders} 
                                        vehicles={vehicles} 
                                        onAdd={() => setOrderModal({open:true, data:null})} 
                                        onEdit={(o:any) => setOrderModal({open:true, data:o})} 
                                        onStatusChange={updateOrderStatus} 
                                        onDelete={deleteOrder} 
                                    />
                                )}
                                {view === 'history' && (
                                    <HistoryView 
                                        logs={logs} 
                                        vehicles={vehicles} 
                                        isAdmin={true} 
                                        onEdit={(l:any) => setEntryModal({open:true, data:l})} 
                                        onDelete={deleteLog} 
                                    />
                                )}
                                {view === 'admin' && <AdminView />}
                            </>
                        )}
                    </ErrorBoundary>
                </main>
            </div>

            {/* Modals */}
            <VehicleModal 
                isOpen={vehicleModal.open} 
                onClose={() => setVehicleModal({open:false, data:null})} 
                vehicle={vehicleModal.data} 
                onSave={handleSaveVehicle} 
            />
            <EntryModal 
                isOpen={entryModal.open} 
                onClose={() => setEntryModal({open:false, data:null})} 
                entry={entryModal.data} 
                vehicles={vehicles} 
                onSave={handleSaveEntry} 
            />
            <OrderModal 
                isOpen={orderModal.open} 
                onClose={() => setOrderModal({open:false, data:null})} 
                order={orderModal.data} 
                vehicles={vehicles} 
                onSave={handleSaveOrder} 
            />
            <InspectionModal 
                isOpen={inspectionModal.open} 
                onClose={() => setInspectionModal({open:false, data:null})} 
                log={inspectionModal.data} 
                onSave={handleInspectionCompletion} 
            />
            <CompletionModal 
                isOpen={completionModal.open} 
                onClose={() => setCompletionModal({open:false, data:null})} 
                log={completionModal.data} 
                onConfirm={handleTaskCompletion} 
            />
        </div>
    );
};

