import { useState, useEffect, useCallback } from 'react';
import { Vehicle, LogEntry, Order, OrderStatus, Priority } from '../types';
import { api } from '../api';
import { getTodayDate } from '../utils';

export const useFleetData = () => {
    const [vehicles, setVehicles] = useState<Vehicle[]>([]);
    const [logs, setLogs] = useState<LogEntry[]>([]);
    const [orders, setOrders] = useState<Order[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    const loadData = useCallback(async (silentArg: boolean | any = false) => {
        // If called from an Event (onClick), silentArg is an Object. Treat as false (show loading).
        // If called from Interval, silentArg is true. Treat as true (silent).
        const isSilent = typeof silentArg === 'boolean' ? silentArg : false;

        if (!isSilent) {
            setLoading(true);
            setError(null);
        }

        try {
            const [v, l, o] = await Promise.all([
                api.get('/vehicles'),
                api.get('/logs'),
                api.get('/orders')
            ]);
            setVehicles(Array.isArray(v) ? v : []);
            setLogs(Array.isArray(l) ? l : []);
            setOrders(Array.isArray(o) ? o : []);
        } catch (e: any) {
            console.error(e);
            if (!isSilent) setError(e.message || "Fehler beim Laden der Daten");
        } finally {
            if (!isSilent) setLoading(false);
        }
    }, []);

    // Initial Load & Polling
    useEffect(() => { 
        loadData(); 

        const interval = setInterval(() => {
            loadData(true); // Silent update
        }, 30000);

        return () => clearInterval(interval);
    }, [loadData]);

    // --- VEHICLE OPERATIONS ---

    const saveVehicle = async (v: Vehicle) => {
        try {
            if(v.id && vehicles.find(x => x.id === v.id)) {
                await api.put(`/vehicles/${v.id}`, v);
            } else {
                await api.post('/vehicles', v);
            }
            await loadData(true); // Refresh silently to keep UI stable
            return true;
        } catch (e) { console.error(e); return false; }
    };

    const deleteVehicle = async (id: string) => {
        if(!confirm('Fahrzeug wirklich löschen?')) return false;
        try {
            await api.delete(`/vehicles/${id}`);
            await loadData(true);
            return true;
        } catch (e) { console.error(e); return false; }
    };

    const coupleVehicles = async (motorId: string, trailerId: string) => {
        const motor = vehicles.find(v => v.id === motorId);
        const trailer = vehicles.find(v => v.id === trailerId);
        if(motor && trailer) {
            await api.put(`/vehicles/${motor.id}`, { ...motor, coupledVehicleId: trailer.id });
            await api.put(`/vehicles/${trailer.id}`, { ...trailer, coupledVehicleId: motor.id });
            await loadData(true);
        }
    };

    const uncoupleVehicles = async (motorId: string, trailerId?: string) => {
        const motor = vehicles.find(v => v.id === motorId);
        if(motor) await api.put(`/vehicles/${motor.id}`, { ...motor, coupledVehicleId: null });

        if(trailerId) {
            const trailer = vehicles.find(v => v.id === trailerId);
            if(trailer) await api.put(`/vehicles/${trailer.id}`, { ...trailer, coupledVehicleId: null });
        }
        await loadData(true);
    };

    // --- LOG / TASK OPERATIONS ---

    const saveLogEntry = async (entries: any[]) => {
        try {
            for (const entry of entries) {
                if(entry.id && logs.find(x => x.id === entry.id)) {
                    await api.put(`/logs/${entry.id}`, entry);
                } else {
                    await api.post('/logs', entry);
                }
            }
            await loadData(true);
            return true;
        } catch (e) { console.error(e); return false; }
    };

    const updateLogStatus = async (log: LogEntry, newStatus: 'IN_PROGRESS' | 'DONE') => {
        try {
            await api.put(`/logs/${log.id}`, { ...log, status: newStatus });
            await loadData(true);
        } catch (e) { console.error(e); }
    };

    const deleteLog = async (id: string) => {
        if(!confirm('Eintrag löschen?')) return false;
        try {
            await api.delete(`/logs/${id}`);
            await loadData(true);
            return true;
        } catch (e) { console.error(e); return false; }
    };

    // --- BUSINESS LOGIC: COMPLETIONS ---

    // Completes a generic task and updates vehicle mileage
    const completeTask = async (log: LogEntry, mileage: number) => {
        try {
            // 1. Update Log
            await api.put(`/logs/${log.id}`, { 
                ...log, 
                status: 'DONE', 
                dateCompleted: getTodayDate(), 
                mileage: mileage 
            });

            // 2. Update Vehicle Mileage (Business Logic: Only update if higher)
            const vehicle = vehicles.find(v => v.id === log.vehicleId);
            if(vehicle && mileage > (vehicle.currentMileage || 0)) {
                await api.put(`/vehicles/${vehicle.id}`, { ...vehicle, currentMileage: mileage });
            }

            await loadData(true);
            return true;
        } catch(e) { console.error(e); return false; }
    };

    // Completes an inspection and calculates next date
    const completeInspection = async (log: LogEntry, nextDate: string) => {
        try {
            const [y, m] = nextDate.split('-'); // YYYY-MM from input

            // 1. Create archival log
            await api.post('/logs', {
                vehicleId: log.vehicleId,
                type: 'Wartung',
                description: `${log.inspectionType} Prüfung durchgeführt`,
                priority: Priority.NORMAL,
                dateAdded: getTodayDate(),
                status: 'DONE',
                dateCompleted: getTodayDate(),
                inspectionType: log.inspectionType
            });

            // 2. Update Vehicle Next Date
            const vehicle = vehicles.find(v => v.id === log.vehicleId);
            if (vehicle && log.inspectionType) {
                // Determine which field to update based on inspection type
                const updateField = `next${log.inspectionType}`; 
                // Store as MM/YYYY
                await api.put(`/vehicles/${vehicle.id}`, { ...vehicle, [updateField]: `${m}/${y}` });
            }

            await loadData(true);
            return true;
        } catch(e) { console.error(e); return false; }
    };

    // --- ORDER OPERATIONS ---

    const saveOrder = async (ordersList: any[]) => {
        try {
            for (const o of ordersList) {
                if(o.id && orders.find(x => x.id === o.id)) {
                    await api.put(`/orders/${o.id}`, o);
                } else {
                    await api.post('/orders', o);
                }
            }
            await loadData(true);
            return true;
        } catch (e) { console.error(e); return false; }
    };

    const updateOrderStatus = async (id: string, status: OrderStatus) => {
        const order = orders.find(o => o.id === id);
        if(order) {
            await api.put(`/orders/${id}`, { ...order, status });
            await loadData(true);
        }
    };

    const deleteOrder = async (id: string) => {
        if(!confirm('Bestellung löschen?')) return false;
        try {
            await api.delete(`/orders/${id}`);
            await loadData(true);
            return true;
        } catch (e) { console.error(e); return false; }
    };

    return {
        // State
        vehicles,
        logs,
        orders,
        loading,
        error,

        // Actions
        loadData,
        saveVehicle,
        deleteVehicle,
        coupleVehicles,
        uncoupleVehicles,

        saveLogEntry,
        updateLogStatus,
        deleteLog,
        completeTask,
        completeInspection,

        saveOrder,
        updateOrderStatus,
        deleteOrder
    };
};

import React, { useState, useMemo, useEffect } from 'react';
import { LogEntry, Vehicle, VehicleType } from '../types';
import { Icons } from '../icons';
import { api, getIsOfflineMode } from '../api';

export const HistoryView = ({ logs, vehicles = [], isAdmin, onEdit, onDelete }: any) => {
  const [filters, setFilters] = useState({ text: '', licensePlate: '', type: '', category: '' });
  const safeVehicles = Array.isArray(vehicles) ? vehicles : [];

  const completedLogs = useMemo(() => {
      return logs.filter((l: LogEntry) => {
        if (l.status !== 'DONE') return false;
        const vehicle = safeVehicles.find((v:Vehicle) => v.id === l.vehicleId);
        const plate = vehicle?.licensePlate || '';
        const vType = vehicle?.type || '';
        if (filters.text && !l.description.toLowerCase().includes(filters.text.toLowerCase())) return false;
        if (filters.licensePlate && !plate.toLowerCase().includes(filters.licensePlate.toLowerCase())) return false;
        if (filters.type && vType !== filters.type) return false;
        if (filters.category === 'inspection' && (!l.inspectionType && l.type !== 'Wartung')) return false;
        if (filters.category === 'task' && (l.inspectionType || l.type === 'Wartung')) return false;
        return true;
      }).sort((a: LogEntry, b: LogEntry) => (b.dateCompleted || '').localeCompare(a.dateCompleted || ''));
  }, [logs, safeVehicles, filters]);

  return (
    <div className="space-y-4">
      <div className="bg-white p-3 rounded shadow-sm border border-gray-200 flex flex-col md:flex-row md:items-center justify-between gap-3">
        <h2 className="text-xl font-bold text-gray-800">Historie</h2>
        <div className="flex flex-wrap items-center gap-2">
           <div className="relative group"><span className="absolute left-2.5 top-2 text-gray-400 pointer-events-none"><Icons.Search /></span><input type="text" placeholder="Stichwort..." className="w-32 md:w-48 pl-8 pr-2 py-1.5 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none" value={filters.text} onChange={e => setFilters({...filters, text: e.target.value})} /></div>
           <div className="relative group"><span className="absolute left-2.5 top-2 text-gray-400 pointer-events-none"><Icons.Truck /></span><input type="text" placeholder="Kennzeichen..." className="w-32 md:w-40 pl-8 pr-2 py-1.5 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none" value={filters.licensePlate} onChange={e => setFilters({...filters, licensePlate: e.target.value})} /></div>
           <div className="relative"><select className="w-32 py-1.5 pl-2 pr-6 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none bg-white text-gray-600 cursor-pointer" value={filters.type} onChange={e => setFilters({...filters, type: e.target.value})}><option value="">Alle Arten</option>{Object.values(VehicleType).map(t => <option key={t} value={t}>{t}</option>)}</select></div>
           <div className="relative"><select className="w-36 py-1.5 pl-2 pr-6 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none bg-white text-gray-600 cursor-pointer" value={filters.category} onChange={e => setFilters({...filters, category: e.target.value})}><option value="">Alle Einträge</option><option value="inspection">Nur Prüfungen</option><option value="task">Nur Aufgaben</option></select></div>
           {(filters.text || filters.licensePlate || filters.type || filters.category) && <button onClick={() => setFilters({text: '', licensePlate: '', type: '', category: ''})} className="text-gray-400 hover:text-red-500 p-1.5 rounded hover:bg-red-50" title="Filter löschen"><Icons.Trash /></button>}
        </div>
      </div>
      <div className="bg-white rounded shadow border border-gray-200 overflow-hidden">
        {completedLogs.length === 0 ? <div className="p-8 text-center text-gray-500 italic">Keine Einträge gefunden.</div> : (
            <div className="divide-y divide-gray-100">
                {completedLogs.map((l: LogEntry) => {
                    const vehicle = safeVehicles.find((v:Vehicle) => v.id === l.vehicleId);
                    return (
                        <div key={l.id} className="p-2 border-b last:border-b-0 border-gray-100 hover:bg-gray-50 transition-colors">
                            <div className="flex justify-between items-start">
                                <div className="flex-1 min-w-0 pr-4">
                                    <div className="flex items-center gap-6 mb-1 flex-wrap">
                                        <span className="text-sm text-gray-900 font-medium">{vehicle ? vehicle.licensePlate : 'Allgemein / Gelöscht'}</span>
                                        <span className="text-xs text-gray-900 font-medium">{l.dateCompleted}</span>
                                        {l.mileage && <span className="text-[10px] text-gray-900 bg-gray-100 border border-gray-200 px-2 py-0.5 rounded font-mono font-bold">KM: {l.mileage}</span>}
                                        {vehicle && <span className="text-[10px] text-gray-400 px-1 border border-gray-200 rounded">{vehicle.type}</span>}
                                    </div>
                                    <div className="text-sm text-gray-600 whitespace-pre-wrap leading-tight">{l.description}</div>
                                    {l.inspectionType && <div className="mt-1"><span className="text-[10px] px-1.5 py-0.5 rounded border bg-purple-50 text-purple-700 border-purple-200">{l.inspectionType}</span></div>}
                                </div>
                                {isAdmin && <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity self-center"><button onClick={() => onEdit(l)} className="text-gray-400 hover:text-blue-600"><Icons.Edit /></button><button onClick={() => onDelete(l.id)} className="text-gray-400 hover:text-red-600"><Icons.Trash /></button></div>}
                            </div>
                         </div>
                    );
                })}
            </div>
        )}
      </div>
    </div>
  );
};

