        <div className="space-y-6">
            <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2"><Icons.Database /> Datenbank Wartung</h2>
            <div className="bg-white p-6 rounded shadow-sm border border-gray-200">
                 <h3 className="font-bold text-gray-700 mb-4 border-b pb-2">Status</h3>
                 <div className="grid grid-cols-2 gap-4"><div><div className="text-sm text-gray-500 uppercase font-bold">Größe</div><div className="text-2xl font-mono text-blue-600">{dbStats?.size || '-'}</div></div><div><div className="text-sm text-gray-500 uppercase font-bold">Backend</div><div className="text-lg font-bold text-green-600">Online</div></div></div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-white p-6 rounded shadow-sm border border-gray-200">
                    <h3 className="font-bold text-gray-700 mb-2">Integrität prüfen</h3>
                    <button onClick={handleIntegrityCheck} disabled={loading} className="bg-slate-700 hover:bg-slate-800 text-white px-4 py-2 rounded text-sm font-bold w-full disabled:opacity-50">{loading ? 'Prüfe...' : 'Jetzt prüfen'}</button>
