                     <button onClick={handleVacuum} disabled={loading} className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded text-sm font-bold w-full disabled:opacity-50">{loading ? 'Arbeite...' : 'Optimierung starten'}</button>
                    {message && <div className="mt-4 text-sm text-green-700 font-bold text-center bg-green-50 p-2 rounded border border-green-200">{message}</div>}
                </div>
