import React, { useState, useMemo } from 'react';
import { Vehicle, LogEntry, VehicleType, Priority } from '../types';
import { Icons } from '../icons';
import { getVehicleTypePriority, getPrioritySortValue, generateVirtualInspections } from '../utils';

export const DashboardView = ({ logs, vehicles = [], onStatusUpdate, onEdit, onDelete, onAdd, onInspect }: any) => {
  const safeVehicles = Array.isArray(vehicles) ? vehicles : [];
  const [showCompleted, setShowCompleted] = useState(false);
  const [sortMode, setSortMode] = useState<'priority' | 'type' | 'license'>('priority');
  const [filters, setFilters] = useState({ licensePlate: '', type: '', priority: '', category: '' });

  const generatedInspections: LogEntry[] = useMemo(() => generateVirtualInspections(safeVehicles), [safeVehicles]);

  const filteredLogs = useMemo(() => {
    const allItems = [...logs, ...generatedInspections];
    return allItems.filter((l: LogEntry) => {
        if (!showCompleted && l.status === 'DONE') return false;
        const vehicle = safeVehicles.find((v:Vehicle) => v.id === l.vehicleId);
        const licensePlate = vehicle?.licensePlate || 'Allgemein';
        const type = vehicle?.type || 'Sonstige';

        if (filters.licensePlate && !licensePlate.toLowerCase().includes(filters.licensePlate.toLowerCase())) return false;
        if (filters.type && type !== filters.type) return false;
        if (filters.priority && l.priority !== filters.priority) return false;
        if (filters.category === 'inspection' && (!l.inspectionType && l.type !== 'Wartung' && l.type !== 'Prüfung')) return false;
        if (filters.category === 'task' && (l.inspectionType || l.type === 'Wartung' || l.type === 'Prüfung')) return false;
        return true;
    });
  }, [logs, generatedInspections, safeVehicles, showCompleted, filters]);

  const groupedLogs = useMemo(() => {
      const groups: { [key: string]: LogEntry[] } = {};
      filteredLogs.forEach((log: LogEntry) => {
          const key = log.vehicleId || 'unknown';
          if (!groups[key]) groups[key] = [];
          groups[key].push(log);
      });
      Object.keys(groups).forEach(key => {
          groups[key].sort((a, b) => {
              const statusOrder = { 'IN_PROGRESS': 0, 'OPEN': 1, 'DONE': 2 };
              if (a.status !== b.status) return statusOrder[a.status] - statusOrder[b.status];
              const pA = getPrioritySortValue(a.priority);
              const pB = getPrioritySortValue(b.priority);
              if (pA !== pB) return pA - pB;
              return a.dateAdded.localeCompare(b.dateAdded);
          });
      });
      return groups;
  }, [filteredLogs]);

  const sortedGroupKeys = useMemo(() => {
      const keys = Object.keys(groupedLogs);
      return keys.sort((a, b) => {
         const vA = safeVehicles.find((v:Vehicle) => v.id === a);
         const vB = safeVehicles.find((v:Vehicle) => v.id === b);
         if (sortMode === 'priority') {
             const minPrio = (tasks: LogEntry[]) => tasks.length === 0 ? 99 : Math.min(...tasks.map(t => getPrioritySortValue(t.priority)));
             const pA = minPrio(groupedLogs[a]), pB = minPrio(groupedLogs[b]);
             if (pA !== pB) return pA - pB;
             return (vA?.licensePlate || 'ZZ').localeCompare(vB?.licensePlate || 'ZZ');
         } else if (sortMode === 'type') {
             const pA = getVehicleTypePriority(vA?.type || 'Sonstige'), pB = getVehicleTypePriority(vB?.type || 'Sonstige');
             if (pA !== pB) return pA - pB;
             return (vA?.licensePlate || 'ZZ').localeCompare(vB?.licensePlate || 'ZZ');
         } else {
             return (vA?.licensePlate || 'ZZ').localeCompare(vB?.licensePlate || 'ZZ');
         }
      });
  }, [groupedLogs, safeVehicles, sortMode]);

  return (
    <div className="space-y-4">
      <div className="bg-white p-3 rounded shadow-sm border border-gray-200 flex flex-col md:flex-row md:items-center justify-between gap-3">
          <div className="flex items-center gap-4 flex-wrap">
              <h2 className="text-xl font-bold text-gray-800 whitespace-nowrap">Aufgaben</h2>
              <div className="h-6 w-px bg-gray-300 hidden md:block"></div>
              <div className="flex items-center gap-2">
                 <div className="relative group">
                      <span className="absolute left-2.5 top-2 text-gray-400 pointer-events-none"><Icons.SortAsc /></span>
                       <select className="w-36 py-1.5 pl-8 pr-6 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none bg-white text-gray-700 appearance-none cursor-pointer font-bold" value={sortMode} onChange={e => setSortMode(e.target.value as any)}>
                          <option value="priority">Priorität</option>
                          <option value="type">Fahrzeugtyp</option>
                          <option value="license">Kennzeichen</option>
                      </select>
                 </div>
              </div>
              <div className="h-6 w-px bg-gray-300 hidden md:block"></div>
              <div className="flex flex-wrap items-center gap-2">
                  <div className="relative group">
                      <span className="absolute left-2.5 top-2 text-gray-400 group-focus-within:text-blue-500 pointer-events-none"><Icons.Search /></span>
                      <input type="text" placeholder="Suchen..." className="w-32 md:w-48 pl-8 pr-2 py-1.5 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none" value={filters.licensePlate} onChange={e => setFilters({...filters, licensePlate: e.target.value})} />
                  </div>
                  <div className="relative">
                       <select className="w-28 py-1.5 pl-2 pr-6 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none bg-white text-gray-600 appearance-none cursor-pointer" value={filters.type} onChange={e => setFilters({...filters, type: e.target.value})}>
                          <option value="">Alle Arten</option>
                          {Object.values(VehicleType).map(t => <option key={t} value={t}>{t}</option>)}
                      </select>
                  </div>
                   <div className="relative">
                       <select className="w-28 py-1.5 pl-2 pr-6 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none bg-white text-gray-600 appearance-none cursor-pointer" value={filters.priority} onChange={e => setFilters({...filters, priority: e.target.value})}>
