                          {Object.values(Priority).map(p => <option key={p} value={p}>{p}</option>)}
                      </select>
                  </div>
                   <div className="relative">
                       <select className="w-32 py-1.5 pl-2 pr-6 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none bg-white text-gray-600 appearance-none cursor-pointer" value={filters.category} onChange={e => setFilters({...filters, category: e.target.value})}>
                          <option value="">Alle Einträge</option>
                          <option value="inspection">Nur Prüfungen</option>
                          <option value="task">Nur Aufgaben</option>
                      </select>
                  </div>
                  {(filters.licensePlate || filters.type || filters.priority || filters.category) && (
                      <button onClick={() => setFilters({licensePlate: '', type: '', priority: '', category: ''})} className="text-gray-400 hover:text-red-500 p-1.5 rounded hover:bg-red-50" title="Filter löschen"><Icons.Trash /></button>
                  )}
              </div>
          </div>
          <div className="flex items-center gap-2 shrink-0 self-end md:self-auto">
               <button onClick={() => setShowCompleted(!showCompleted)} className={`p-2 rounded border transition-colors ${showCompleted ? 'bg-blue-50 text-blue-600 border-blue-200' : 'bg-white text-gray-400 border-gray-200 hover:border-gray-300'}`}>{showCompleted ? <Icons.Eye /> : <Icons.EyeOff />}</button>
               <button onClick={onAdd} className="bg-blue-600 hover:bg-blue-700 text-white px-3 py-1.5 rounded flex items-center gap-2 shadow-sm font-bold text-sm"><Icons.Plus /> Neu</button>
          </div>
      </div>

      <div className="flex flex-col gap-4">
        {sortedGroupKeys.length === 0 && <div className="col-span-full text-center py-12 text-gray-400 bg-gray-50 rounded border border-dashed border-gray-300">Keine Aufgaben gefunden.</div>}
        {sortedGroupKeys.map((vid, index) => {
          const vehicleLogs = groupedLogs[vid];
          const vehicle = safeVehicles.find((v:Vehicle) => v.id === vid);
          const coupledVehicle = vehicle?.coupledVehicleId ? safeVehicles.find((v:Vehicle) => v.id === vehicle.coupledVehicleId) : null;
          const hasUrgent = vehicleLogs.some(l => l.priority === Priority.HIGH);
          const currentType = vehicle?.type || 'Sonstige';
          const prevVid = sortedGroupKeys[index - 1];
          const prevVehicle = safeVehicles.find((v:Vehicle) => v.id === prevVid);
          const prevType = prevVehicle?.type || 'Sonstige';
          const showGroupHeader = sortMode === 'type' && (index === 0 || currentType !== prevType);

          return (
            <React.Fragment key={vid}>
                {showGroupHeader && (
                    <div className="mt-4 first:mt-0 flex items-center gap-3">
                         <div className="text-gray-500 font-bold uppercase text-xs tracking-wider bg-gray-100 px-3 py-1 rounded-full border border-gray-200">{currentType}</div>
                         <div className="h-px bg-gray-300 flex-1 opacity-50"></div>
                    </div>
                )}
                <div className="bg-white rounded shadow-sm border border-gray-200 overflow-hidden flex flex-col w-full">
                <div className="bg-slate-50 border-b border-gray-200 px-3 py-2 flex justify-between items-center">
                    <div>
                        <div className="font-bold text-base text-slate-800 flex items-center gap-2">
                            {vehicle ? vehicle.licensePlate : 'Allgemein / Lager'}
                            {coupledVehicle && (
                                <span className="text-xs text-gray-400 font-normal flex items-center gap-1 ml-2" title={`Gekoppelt mit: ${coupledVehicle.licensePlate}`}>
                                    <span className="opacity-50 scale-75"><Icons.Link /></span> {coupledVehicle.licensePlate}
                                </span>
                            )}
                        </div>
                        {vehicle && <div className="text-[10px] text-slate-500">{vehicle.manufacturer} {vehicle.model} • {vehicle.type}</div>}
                    </div>
                    <div className={`${hasUrgent ? 'bg-red-100 text-red-700 border border-red-200' : 'bg-slate-200 text-slate-600'} px-2 py-0.5 rounded-full text-[10px] font-bold`}>{vehicleLogs.length}</div>
                </div>
                <div className="divide-y divide-gray-100">
                    {vehicleLogs.map((log: LogEntry) => {
                        const isDone = log.status === 'DONE';
                        const isInProgress = log.status === 'IN_PROGRESS';
                        return (
                            <div key={log.id} className={`p-2 group transition-colors ${isInProgress ? 'bg-amber-50' : isDone ? 'bg-gray-50 opacity-75' : 'hover:bg-blue-50'}`}>
                                <div className="flex justify-between items-start gap-1.5">
                                    <div className="flex-1 min-w-0">
                                        <div className="flex items-center gap-2 mb-0.5">
                                                <span className={`px-1.5 py-0.5 rounded-[3px] text-[10px] font-bold uppercase tracking-wider border ${log.priority === Priority.HIGH ? 'bg-red-100 text-red-800 border-red-200' : log.priority === Priority.LOW ? 'bg-gray-100 text-gray-600 border-gray-200' : 'bg-blue-50 text-blue-800 border-blue-100'}`}>{log.priority}</span>
                                                {isInProgress && <span className="text-[10px] font-bold text-amber-600 flex items-center gap-1 bg-amber-100 px-1.5 py-0.5 rounded border border-amber-200"><Icons.Clock /> In Bearbeitung</span>}
                                                {log.isVirtual && <span className="text-[10px] font-bold text-purple-600 bg-purple-100 px-1.5 py-0.5 rounded border border-purple-200 ml-1">PRÜFUNG</span>}
                                        </div>
                                        <div className={`text-sm text-gray-800 whitespace-pre-wrap ${isDone ? 'line-through text-gray-500' : ''}`}>{log.description}</div>
                                        <div className="text-[10px] text-gray-400 mt-0.5 flex gap-2"><span>Erstellt: {log.dateAdded}</span>{log.mileage && <span>• KM: {log.mileage}</span>}</div>
                                    </div>
                                    <div className="flex flex-col gap-1 items-end">
                                        {!isDone && (
                                            <div className="flex gap-1">
                                                {!isInProgress && !log.isVirtual && (
                                                    <button onClick={() => onStatusUpdate(log, 'IN_PROGRESS')} className="p-1 bg-white border border-gray-200 text-amber-500 hover:bg-amber-50 hover:border-amber-300 rounded shadow-sm transition-all" title="In Bearbeitung setzen"><Icons.Clock /></button>
                                                )}
                                                <button onClick={() => log.isVirtual ? onInspect(log) : onStatusUpdate(log, 'DONE')} className="p-1 bg-white border border-gray-200 text-green-600 hover:bg-green-50 hover:border-green-300 rounded shadow-sm transition-all" title={log.isVirtual ? "Prüfung durchführen" : "Erledigen"}><Icons.Check /></button>
                                            </div>
                                        )}
                                        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                            {!log.isVirtual && (
                                                <>
                                                <button onClick={() => onEdit(log)} className="p-1 text-blue-400 hover:text-blue-600"><Icons.Edit /></button>
                                                <button onClick={() => onDelete(log.id)} className="p-1 text-red-300 hover:text-red-600"><Icons.Trash /></button>
                                                </>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
                </div>
            </React.Fragment>
          );
        })}
      </div>
    </div>
  );
};

