export const AppointmentsView = ({ vehicles = [], onComplete }: any) => {
  const [selectedMonth, setSelectedMonth] = useState(getTodayDate().substring(0, 7));
  const safeVehicles = Array.isArray(vehicles) ? vehicles : [];

  const appointments = useMemo(() => {
    const list: any[] = [];
    safeVehicles.forEach((v: Vehicle) => {
      if (v.nextHU) list.push({ id: v.id + 'HU', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'HU', date: v.nextHU });
      if (v.nextSP) list.push({ id: v.id + 'SP', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'SP', date: v.nextSP });
      if (v.nextUVV) list.push({ id: v.id + 'UVV', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'UVV', date: v.nextUVV });
      if (v.nextTacho) list.push({ id: v.id + 'Tacho', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'Tacho', date: v.nextTacho });
    });
    return list.sort((a, b) => {
       const [ma, ya] = a.date.split('/'); const [mb, yb] = b.date.split('/');
       return new Date(parseInt(ya), parseInt(ma)-1).getTime() - new Date(parseInt(yb), parseInt(mb)-1).getTime();
    });
  }, [safeVehicles]);

  const { overdue, dueThisMonth, upcomingGrouped } = useMemo(() => {
    const ov: any[] = [], curr: any[] = [], up: any[] = [];
    appointments.forEach(apt => {
        const [m, y] = apt.date.split('/');
        const aptIso = `${y}-${m.padStart(2, '0')}`;
        if (aptIso < selectedMonth) ov.push({...apt, isOverdue: true});
        else if (aptIso === selectedMonth) curr.push({...apt, isOverdue: false});
        else up.push(apt);
    });
    const groups: Record<string, any[]> = {};
    up.forEach(apt => { if(!groups[apt.date]) groups[apt.date] = []; groups[apt.date].push(apt); });
    return { overdue: ov, dueThisMonth: curr, upcomingGrouped: groups };
  }, [appointments, selectedMonth]);

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-end justify-between border-b pb-2 gap-2">
          <div><h2 className="text-xl font-bold text-gray-800">Prüfungs-Monitor</h2><div className="text-xs text-gray-500 mt-0.5">Anzeige für: <span className="font-mono font-bold text-gray-700">{selectedMonth}</span></div></div>
          <div className="flex items-center gap-2 bg-white p-1 rounded border shadow-sm">
             <span className="text-xs font-bold text-gray-600">Monat:</span>
             <input type="month" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} className="border border-gray-300 rounded px-1 py-0.5 text-xs font-sans focus:outline-none" />
             {selectedMonth !== getTodayDate().substring(0, 7) && <button onClick={() => setSelectedMonth(getTodayDate().substring(0, 7))} className="ml-1 text-[10px] bg-blue-100 text-blue-700 px-2 py-1 rounded font-bold">Heute</button>}
          </div>
      </div>
      {overdue.length > 0 && (
          <div className="space-y-2 animate-pulse-once">
              <h3 className="font-bold text-red-700 text-sm flex items-center gap-2 bg-red-50 p-2 rounded border border-red-200"><Icons.Alert /> ÜBERFÄLLIG ({overdue.length})</h3>
              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-3">{overdue.map(apt => <AppointmentCard key={apt.id} apt={apt} isOverdue={true} onComplete={onComplete} />)}</div>
          </div>
      )}
      <div className="space-y-2">
          <h3 className="font-bold text-blue-800 text-sm flex items-center gap-2 border-b border-blue-200 pb-1"><Icons.Calendar /> FÄLLIG IM {selectedMonth} ({dueThisMonth.length})</h3>
          {dueThisMonth.length === 0 && <div className="bg-blue-50 border border-blue-100 text-blue-800 p-4 rounded text-center">📅 Nichts geplant</div>}
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-3">{dueThisMonth.map(apt => <AppointmentCard key={apt.id} apt={apt} isOverdue={false} onComplete={onComplete} />)}</div>
      </div>
      <div className="pt-6 border-t mt-4">
          <h3 className="text-sm font-bold text-gray-500 mb-4 uppercase tracking-wider">Vorschau (Quartalsansicht)</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
              {Object.keys(upcomingGrouped).length === 0 && <div className="col-span-full text-xs text-gray-400 italic">Keine späteren Termine.</div>}
              {Object.keys(upcomingGrouped).map(dateKey => (
                  <div key={dateKey} className="bg-white border border-gray-200 rounded shadow-sm flex flex-col h-full">
                      <div className="bg-gray-50 px-3 py-2 border-b border-gray-100 flex justify-between items-center"><span className="font-bold text-gray-700 text-sm">{dateKey}</span><span className="text-[10px] bg-white border border-gray-200 px-1.5 rounded text-gray-500 font-bold shadow-sm">{upcomingGrouped[dateKey].length}</span></div>
                      <div className="divide-y divide-gray-100 p-1">
                          {upcomingGrouped[dateKey].map(apt => (
                              <div key={apt.id} className="p-2 flex justify-between items-center hover:bg-gray-50 transition-colors rounded">
                                  <div className="flex items-center gap-2 overflow-hidden"><div className={`shrink-0 w-9 text-center text-[9px] font-bold px-0.5 py-0.5 rounded border ${getBadgeColor(apt.inspectionType)}`}>{apt.inspectionType}</div><div className="min-w-0"><div className="font-bold text-gray-800 text-xs truncate">{apt.license}</div><div className="text-[9px] text-gray-500 truncate">{apt.vehicleType}</div></div></div>
                                  <button onClick={() => onComplete(apt)} className="text-gray-300 hover:text-green-600 p-1.5 hover:bg-green-50 rounded transition-colors" title="Jetzt schon erledigen"><Icons.Check /></button>
                              </div>
                          ))}
                      </div>
                  </div>
              ))}
          </div>
      </div>
    </div>
  );
};

export const OrdersView = ({ orders, vehicles = [], onAdd, onEdit, onStatusChange, onDelete }: any) => {
  const safeVehicles = Array.isArray(vehicles) ? vehicles : [];
  const [showCompleted, setShowCompleted] = useState(false);

  const filteredOrders = useMemo(() => {
    return orders.filter((o: Order) => {
        if (!showCompleted && o.status === OrderStatus.ERLEDIGT) return false;
        return true;
    }).sort((a: Order, b: Order) => {
       const vA = safeVehicles.find((v:Vehicle) => v.id === a.vehicleId);
       const vB = safeVehicles.find((v:Vehicle) => v.id === b.vehicleId);
       const plateCompare = (vA?.licensePlate || 'ZZZ').localeCompare(vB?.licensePlate || 'ZZZ');
       if (plateCompare !== 0) return plateCompare;
       return getPrioritySortValue(a.description) - getPrioritySortValue(b.description);
    });
  }, [orders, safeVehicles, showCompleted]);

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center bg-white p-3 rounded shadow-sm border border-gray-200">
        <h2 className="text-xl font-bold text-gray-800">Bestellungen</h2>
        <div className="flex gap-2">
            <button onClick={() => setShowCompleted(!showCompleted)} className={`p-2 rounded border transition-colors ${showCompleted ? 'bg-blue-50 text-blue-600 border-blue-200' : 'bg-white text-gray-400 border-gray-200 hover:border-gray-300'}`}>{showCompleted ? <Icons.Eye /> : <Icons.EyeOff />}</button>
            <button onClick={onAdd} className="bg-blue-600 hover:bg-blue-700 text-white px-3 py-1.5 rounded flex items-center gap-2 shadow-sm font-bold text-sm"><Icons.Plus /> Neu</button>
        </div>
      </div>
      <div className="bg-white rounded shadow border border-gray-200 overflow-hidden">
        {filteredOrders.length === 0 && <div className="p-12 text-center text-gray-400 italic">Keine Bestellungen vorhanden.</div>}
        {filteredOrders.map((o: Order) => {
            const vehicle = safeVehicles.find((v:Vehicle) => v.id === o.vehicleId);
            const isUrgent = o.description.includes('[Dringend]');
            const isLow = o.description.includes('[Niedrig]');
            return (
              <div key={o.id} className="p-4 border-b last:border-b-0 flex flex-col md:flex-row md:items-center justify-between hover:bg-gray-50 gap-4 transition-colors">
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-2"><span className="font-bold text-lg text-gray-800 bg-gray-100 px-2 py-0.5 rounded border border-gray-200">{vehicle?.licensePlate || 'Lager/Allgemein'}</span>{(isUrgent || isLow) && <span className={`px-2 py-0.5 rounded text-xs font-bold uppercase tracking-wider ${isUrgent ? 'bg-red-100 text-red-800 border border-red-200' : 'bg-gray-100 text-gray-600 border border-gray-200'}`}>{isUrgent ? 'Dringend' : 'Niedrig'}</span>}</div>
                  <div className={`font-normal text-gray-700 whitespace-pre-wrap ${o.status === OrderStatus.ERLEDIGT ? 'line-through text-gray-400' : ''}`}>
                      {o.description.replace(/\[Dringend\]|\[Niedrig\]/g, '').trim()}
                      {o.supplier && <div className="text-sm text-blue-600 font-bold mt-1">@ {o.supplier}</div>}
                  </div>
                  <div className="text-[10px] text-gray-400 mt-1 flex gap-2"><span>Erstellt: {o.dateAdded}</span></div>
                </div>
                <div className="flex items-center gap-4 self-end md:self-center">
                    <div className="flex bg-gray-100 p-1 rounded-md gap-1">
                        <StatusButton currentStatus={o.status} targetStatus={OrderStatus.OFFEN} label="Offen" icon={<Icons.Box />} colorClass="bg-white text-gray-700 shadow-sm border-gray-300" onClick={() => onStatusChange(o.id, OrderStatus.OFFEN)} />
                        <StatusButton currentStatus={o.status} targetStatus={OrderStatus.BESTELLT} label="Bestellt" icon={<Icons.FileText />} colorClass="bg-blue-100 text-blue-700 border-blue-200" onClick={() => onStatusChange(o.id, OrderStatus.BESTELLT)} />
                        <StatusButton currentStatus={o.status} targetStatus={OrderStatus.ERLEDIGT} label="Erledigt" icon={<Icons.CheckCircle />} colorClass="bg-green-100 text-green-700 border-green-200" onClick={() => onStatusChange(o.id, OrderStatus.ERLEDIGT)} />
                    </div>
                    <div className="flex gap-1 border-l pl-4 border-gray-200"><button onClick={() => onEdit(o)} className="text-blue-400 hover:text-blue-600 p-1.5 hover:bg-blue-50 rounded" title="Bearbeiten"><Icons.Edit /></button><button onClick={() => onDelete(o.id)} className="text-red-300 hover:text-red-600 p-1.5 hover:bg-red-50 rounded" title="Löschen"><Icons.Trash /></button></div>
                </div>
              </div>
            );
        })}
      </div>
    </div>
  );
};

const express = require('express');
const sqlite3 = require('sqlite3').verbose();
const path = require('path');
const fs = require('fs');

const app = express();
const PORT = process.env.PORT || 3000;

// Ensure data directory exists
const dataDir = path.join(__dirname, 'data');
if (!fs.existsSync(dataDir)) {
  fs.mkdirSync(dataDir);
}

// Initialize SQLite
const dbPath = path.join(dataDir, 'fuhrpark.db');
const db = new sqlite3.Database(dbPath, (err) => {
  if (err) console.error('Error opening database', err);
  else console.log('Connected to SQLite database at', dbPath);
});

// Middleware - INCREASED LIMIT FOR FILE UPLOADS
app.use(express.json({ limit: '50mb' }));
app.use(express.urlencoded({ limit: '50mb', extended: true }));

// Serve Favicon from data directory (Handle both .png and .ico)
app.get(['/favicon.png', '/favicon.ico'], (req, res) => {
  const faviconPath = path.join(dataDir, 'favicon.png');
  if (fs.existsSync(faviconPath)) {
    res.sendFile(faviconPath);
  } else {
    // Send 404 if file doesn't exist
    res.status(404).end();
  }
});

// Helper for Promisified DB
const run = (sql, params = []) => new Promise((resolve, reject) => {
  db.run(sql, params, function (err) {
    if (err) reject(err);
    else resolve(this);
  });
});

const all = (sql, params = []) => new Promise((resolve, reject) => {
  db.all(sql, params, (err, rows) => {
    if (err) reject(err);
    else resolve(rows);
  });
});

// Init Tables
db.serialize(() => {
  db.run(`CREATE TABLE IF NOT EXISTS vehicles (
    id TEXT PRIMARY KEY, licensePlate TEXT, type TEXT, manufacturer TEXT, model TEXT, vin TEXT, year INTEGER, notes TEXT, coupledVehicleId TEXT, nextHU TEXT, nextSP TEXT, nextUVV TEXT, nextTacho TEXT, currentMileage INTEGER
  )`, (err) => {
    if (err) console.error("Error creating vehicles table:", err);
  });

  // Added attachments column
  db.run(`CREATE TABLE IF NOT EXISTS logs (
    id TEXT PRIMARY KEY, vehicleId TEXT, type TEXT, description TEXT, priority TEXT, dateAdded TEXT, dateCompleted TEXT, status TEXT, mileage INTEGER, inspectionType TEXT, attachments TEXT
  )`, (err) => {
    if (err) console.error("Error creating logs table:", err);
  });

  // Migration for existing tables: Add attachments column if missing
  db.run("ALTER TABLE logs ADD COLUMN attachments TEXT", (err) => {
    // Ignore error if column already exists
  });

  // Added supplier column
  db.run(`CREATE TABLE IF NOT EXISTS orders (
    id TEXT PRIMARY KEY, description TEXT, vehicleId TEXT, dateAdded TEXT, status TEXT, supplier TEXT
  )`, (err) => {
    if (err) console.error("Error creating orders table:", err);
  });

  // Migration for existing orders table: Add supplier column
  db.run("ALTER TABLE orders ADD COLUMN supplier TEXT", (err) => {
     // Ignore error if column already exists
  });

  // NEW: Repairs / Maintenance Table
  db.run(`CREATE TABLE IF NOT EXISTS repairs (
    id TEXT PRIMARY KEY, vehicleId TEXT, date TEXT, type TEXT, description TEXT, performer TEXT, cost REAL, mileage INTEGER, invoiceData TEXT
  )`, (err) => {
    if (err) console.error("Error creating repairs table:", err);
  });
});

