import React, { useState, useMemo, useEffect } from 'react';
import { LogEntry, Vehicle, VehicleType } from '../types';
import { Icons } from '../icons';
import { api, getIsOfflineMode } from '../api';

export const HistoryView = ({ logs, vehicles = [], isAdmin, onEdit, onDelete }: any) => {
  const [filters, setFilters] = useState({ text: '', licensePlate: '', type: '', category: '' });
  const safeVehicles = Array.isArray(vehicles) ? vehicles : [];

  const completedLogs = useMemo(() => {
      return logs.filter((l: LogEntry) => {
        if (l.status !== 'DONE') return false;
        const vehicle = safeVehicles.find((v:Vehicle) => v.id === l.vehicleId);
        const plate = vehicle?.licensePlate || '';
        const vType = vehicle?.type || '';
        if (filters.text && !l.description.toLowerCase().includes(filters.text.toLowerCase())) return false;
        if (filters.licensePlate && !plate.toLowerCase().includes(filters.licensePlate.toLowerCase())) return false;
        if (filters.type && vType !== filters.type) return false;
        if (filters.category === 'inspection' && (!l.inspectionType && l.type !== 'Wartung')) return false;
        if (filters.category === 'task' && (l.inspectionType || l.type === 'Wartung')) return false;
        return true;
      }).sort((a: LogEntry, b: LogEntry) => (b.dateCompleted || '').localeCompare(a.dateCompleted || ''));
  }, [logs, safeVehicles, filters]);

  return (
    <div className="space-y-4">
      <div className="bg-white p-3 rounded shadow-sm border border-gray-200 flex flex-col md:flex-row md:items-center justify-between gap-3">
        <h2 className="text-xl font-bold text-gray-800">Historie</h2>
        <div className="flex flex-wrap items-center gap-2">
           <div className="relative group"><span className="absolute left-2.5 top-2 text-gray-400 pointer-events-none"><Icons.Search /></span><input type="text" placeholder="Stichwort..." className="w-32 md:w-48 pl-8 pr-2 py-1.5 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none" value={filters.text} onChange={e => setFilters({...filters, text: e.target.value})} /></div>
           <div className="relative group"><span className="absolute left-2.5 top-2 text-gray-400 pointer-events-none"><Icons.Truck /></span><input type="text" placeholder="Kennzeichen..." className="w-32 md:w-40 pl-8 pr-2 py-1.5 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none" value={filters.licensePlate} onChange={e => setFilters({...filters, licensePlate: e.target.value})} /></div>
           <div className="relative"><select className="w-32 py-1.5 pl-2 pr-6 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none bg-white text-gray-600 cursor-pointer" value={filters.type} onChange={e => setFilters({...filters, type: e.target.value})}><option value="">Alle Arten</option>{Object.values(VehicleType).map(t => <option key={t} value={t}>{t}</option>)}</select></div>
           <div className="relative"><select className="w-36 py-1.5 pl-2 pr-6 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none bg-white text-gray-600 cursor-pointer" value={filters.category} onChange={e => setFilters({...filters, category: e.target.value})}><option value="">Alle Einträge</option><option value="inspection">Nur Prüfungen</option><option value="task">Nur Aufgaben</option></select></div>
           {(filters.text || filters.licensePlate || filters.type || filters.category) && <button onClick={() => setFilters({text: '', licensePlate: '', type: '', category: ''})} className="text-gray-400 hover:text-red-500 p-1.5 rounded hover:bg-red-50" title="Filter löschen"><Icons.Trash /></button>}
        </div>
      </div>
      <div className="bg-white rounded shadow border border-gray-200 overflow-hidden">
        {completedLogs.length === 0 ? <div className="p-8 text-center text-gray-500 italic">Keine Einträge gefunden.</div> : (
            <div className="divide-y divide-gray-100">
                {completedLogs.map((l: LogEntry) => {
                    const vehicle = safeVehicles.find((v:Vehicle) => v.id === l.vehicleId);
                    return (
                        <div key={l.id} className="p-2 border-b last:border-b-0 border-gray-100 hover:bg-gray-50 transition-colors">
                            <div className="flex justify-between items-start">
                                <div className="flex-1 min-w-0 pr-4">
                                    <div className="flex items-center gap-6 mb-1 flex-wrap">
                                        <span className="text-sm text-gray-900 font-medium">{vehicle ? vehicle.licensePlate : 'Allgemein / Gelöscht'}</span>
                                        <span className="text-xs text-gray-900 font-medium">{l.dateCompleted}</span>
                                        {l.mileage && <span className="text-[10px] text-gray-900 bg-gray-100 border border-gray-200 px-2 py-0.5 rounded font-mono font-bold">KM: {l.mileage}</span>}
                                        {vehicle && <span className="text-[10px] text-gray-400 px-1 border border-gray-200 rounded">{vehicle.type}</span>}
                                    </div>
                                    <div className="text-sm text-gray-600 whitespace-pre-wrap leading-tight">{l.description}</div>
                                    {l.inspectionType && <div className="mt-1"><span className="text-[10px] px-1.5 py-0.5 rounded border bg-purple-50 text-purple-700 border-purple-200">{l.inspectionType}</span></div>}
                                </div>
                                {isAdmin && <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity self-center"><button onClick={() => onEdit(l)} className="text-gray-400 hover:text-blue-600"><Icons.Edit /></button><button onClick={() => onDelete(l.id)} className="text-gray-400 hover:text-red-600"><Icons.Trash /></button></div>}
                            </div>
                         </div>
                    );
                })}
            </div>
        )}
      </div>
    </div>
  );
};

export const AdminView = () => {
    const [dbStats, setDbStats] = useState<any>(null);
    const [checkResult, setCheckResult] = useState<any[]>([]);
    const [loading, setLoading] = useState(false);
    const [message, setMessage] = useState('');
    const offline = getIsOfflineMode();
    const [isAuthenticated, setIsAuthenticated] = useState(false);
    const [passwordInput, setPasswordInput] = useState('');
    const [loginError, setLoginError] = useState('');

    const fetchStats = async () => { try { const data = await api.get('/admin/db-stats'); setDbStats(data); } catch(e) { console.error(e); } };
    useEffect(() => { if(!offline && isAuthenticated) fetchStats(); }, [offline, isAuthenticated]);

    const handleIntegrityCheck = async () => {
        setLoading(true); setMessage('');
        try { const res = await api.get('/admin/db-check'); setCheckResult(Array.isArray(res) ? res : []); } catch(e) { setMessage('Fehler bei der Prüfung.'); } finally { setLoading(false); }
    };

    const handleVacuum = async () => {
         if(!confirm("Diese Aktion reorganisiert die Datenbank...")) return;
         setLoading(true); setMessage('');
         try { const res = await api.post('/admin/db-vacuum', {}); if(res.success) { setMessage('Optimierung erfolgreich.'); fetchStats(); } } catch(e) { setMessage('Fehler.'); } finally { setLoading(false); }
    };

    const handleDownloadBackup = () => {
         window.open('/api/admin/backup', '_blank');
    };

    if (offline) return <div className="p-8 text-center bg-white rounded border border-gray-200"><Icons.WifiOff /><h2 className="text-lg font-bold mt-2">Admin-Modus nicht verfügbar</h2></div>;

    if (!isAuthenticated) {
        return (
            <div className="max-w-md mx-auto mt-20 bg-white p-8 rounded shadow-md border border-gray-200">
                <h2 className="text-2xl font-bold text-gray-800 mb-6 flex items-center gap-2"><Icons.Lock /> Admin-Bereich</h2>
                <form onSubmit={(e) => { e.preventDefault(); if(passwordInput === 'administrator') { setIsAuthenticated(true); setLoginError(''); } else { setLoginError('Falsches Passwort.'); } }}>
                    <input type="password" className="w-full border border-gray-300 p-2 rounded mb-4" placeholder="Passwort" value={passwordInput} onChange={e => setPasswordInput(e.target.value)} autoFocus />
                    {loginError && <div className="text-red-600 text-sm mb-4 font-bold">{loginError}</div>}
                    <button type="submit" className="w-full bg-blue-600 text-white font-bold py-2 rounded hover:bg-blue-700">Anmelden</button>
                </form>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2"><Icons.Database /> Datenbank Wartung</h2>
            <div className="bg-white p-6 rounded shadow-sm border border-gray-200">
                 <h3 className="font-bold text-gray-700 mb-4 border-b pb-2">Status</h3>
                 <div className="grid grid-cols-2 gap-4"><div><div className="text-sm text-gray-500 uppercase font-bold">Größe</div><div className="text-2xl font-mono text-blue-600">{dbStats?.size || '-'}</div></div><div><div className="text-sm text-gray-500 uppercase font-bold">Backend</div><div className="text-lg font-bold text-green-600">Online</div></div></div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                <div className="bg-white p-6 rounded shadow-sm border border-gray-200 flex flex-col">
                    <h3 className="font-bold text-gray-700 mb-2">Datensicherung</h3>
                    <button onClick={handleDownloadBackup} className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded text-sm font-bold w-full flex justify-center items-center gap-2 mt-auto">
                        <Icons.Download /> Backup herunterladen (.db)
                    </button>
                    <p className="mt-2 text-xs text-gray-400">Lädt die aktuelle SQLite Datenbank herunter.</p>
                </div>
                <div className="bg-white p-6 rounded shadow-sm border border-gray-200">
                    <h3 className="font-bold text-gray-700 mb-2">Integrität prüfen</h3>
                    <button onClick={handleIntegrityCheck} disabled={loading} className="bg-slate-700 hover:bg-slate-800 text-white px-4 py-2 rounded text-sm font-bold w-full disabled:opacity-50">{loading ? 'Prüfe...' : 'Jetzt prüfen'}</button>
                    {checkResult.length > 0 && <div className="mt-4 bg-gray-50 p-2 rounded text-xs font-mono max-h-40 overflow-auto border border-gray-200">{JSON.stringify(checkResult, null, 2)}</div>}
                </div>
                <div className="bg-white p-6 rounded shadow-sm border border-gray-200">
                    <h3 className="font-bold text-gray-700 mb-2">Optimierung (VACUUM)</h3>
                     <button onClick={handleVacuum} disabled={loading} className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded text-sm font-bold w-full disabled:opacity-50">{loading ? 'Arbeite...' : 'Optimierung starten'}</button>
                    {message && <div className="mt-4 text-sm text-green-700 font-bold text-center bg-green-50 p-2 rounded border border-green-200">{message}</div>}
                </div>
            </div>
        </div>
    );
};

import React, { useMemo, useState } from 'react';
import { LogEntry, Vehicle, VehicleType } from '../types';
import { Icons } from '../icons';

// Simple SVG Bar Chart Component for Monthly Data
const SimpleBarChart = ({ data, height = 200 }: { data: { label: string, value: number }[], height?: number }) => {
    const maxValue = Math.max(...data.map(d => d.value), 1);

    return (
        <div className="flex items-end justify-between gap-2 h-full w-full" style={{ height }}>
            {data.map((d, i) => {
                const percentage = (d.value / maxValue) * 100;
                return (
                    <div key={i} className="flex-1 flex flex-col items-center group relative h-full justify-end">
                        {/* Tooltip */}
                        <div className="absolute bottom-full mb-2 opacity-0 group-hover:opacity-100 transition-opacity bg-gray-800 text-white text-xs rounded px-2 py-1 pointer-events-none whitespace-nowrap z-10 shadow-lg">
                            {d.label}: {d.value} Einträge
                        </div>
                        <div 
                            className={`w-full max-w-[30px] rounded-t transition-all relative ${d.value === 0 ? 'bg-gray-100' : 'bg-blue-500 hover:bg-blue-600'}`}
                            style={{ height: d.value === 0 ? '4px' : `${percentage}%` }}
                        >
                             {d.value > 0 && <span className="absolute -top-5 left-1/2 -translate-x-1/2 text-[10px] font-bold text-gray-600">{d.value}</span>}
                        </div>
                        <div className="text-[10px] text-gray-500 mt-2 truncate w-full text-center border-t border-gray-200 pt-1">{d.label}</div>
                    </div>
                )
            })}
        </div>
    );
};

export const AnalysisView = ({ logs, vehicles = [] }: any) => {
    const safeVehicles = Array.isArray(vehicles) ? vehicles : [];

    // State filters
    const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
    const [selectedType, setSelectedType] = useState<string>('');

    // Prepare Data
    const analysisData = useMemo(() => {
        // 1. Filter Logs (Completed only + Filters)
        const filtered = logs.filter((l: LogEntry) => {
            if (l.status !== 'DONE' || !l.dateCompleted) return false;

            const completionDate = new Date(l.dateCompleted);
            if (completionDate.getFullYear() !== selectedYear) return false;

            const vehicle = safeVehicles.find((v: Vehicle) => v.id === l.vehicleId);
            if (selectedType && vehicle?.type !== selectedType) return false;

            return true;
        });

        // 2. Monthly Stats
        const months = ['Jan', 'Feb', 'Mär', 'Apr', 'Mai', 'Jun', 'Jul', 'Aug', 'Sep', 'Okt', 'Nov', 'Dez'];
        const monthlyData = months.map((m, idx) => ({ label: m, value: 0 }));

        filtered.forEach((l: LogEntry) => {
            if(!l.dateCompleted) return;
            const mIdx = new Date(l.dateCompleted).getMonth(); // 0-11
            if(monthlyData[mIdx]) monthlyData[mIdx].value++;
        });

        // 3. Top Vehicles
        const vehicleCounts: Record<string, number> = {};
        filtered.forEach((l: LogEntry) => {
            if (l.vehicleId) vehicleCounts[l.vehicleId] = (vehicleCounts[l.vehicleId] || 0) + 1;
        });

        const topVehicles = Object.entries(vehicleCounts)
            .map(([vid, count]) => {
                const v = safeVehicles.find((vh: Vehicle) => vh.id === vid);
                return { 
                    id: vid, 
                    count, 
                    license: v?.licensePlate || 'Unbekannt', 
                    model: v ? `${v.manufacturer} ${v.model}` : '',
                    type: v?.type 
                };
            })
            .sort((a, b) => b.count - a.count)
            .slice(0, 10); // Top 10

        // 4. Categories
        const categoryCounts: Record<string, number> = { 'Wartung': 0, 'Reparatur': 0, 'Prüfung': 0 };
        filtered.forEach((l: LogEntry) => {
            if (l.inspectionType) categoryCounts['Prüfung']++;
            else if (l.type === 'Wartung') categoryCounts['Wartung']++;
            else categoryCounts['Reparatur']++;
        });
        const categoryData = Object.entries(categoryCounts).map(([k, v]) => ({ label: k, value: v }));

        return { total: filtered.length, monthlyData, topVehicles, categoryData };

    }, [logs, safeVehicles, selectedYear, selectedType]);

    const availableYears = useMemo(() => {
        const years = new Set<number>();
        years.add(new Date().getFullYear());
        logs.forEach((l: LogEntry) => {
            if(l.dateCompleted) years.add(new Date(l.dateCompleted).getFullYear());
        });
        return Array.from(years).sort((a, b) => b - a);
    }, [logs]);

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row justify-between items-center bg-white p-4 rounded shadow-sm border border-gray-200 gap-4">
                <div className="flex items-center gap-3">
                    <div className="bg-blue-100 p-2 rounded text-blue-600"><Icons.Chart /></div>
                    <div>
                        <h2 className="text-xl font-bold text-gray-800">Auswertung</h2>
                        <div className="text-sm text-gray-500">Erledigte Aufgaben & Prüfungen</div>
                    </div>
                </div>

                <div className="flex gap-2">
                     <select 
                        className="border border-gray-300 rounded px-3 py-2 text-sm font-bold text-gray-700 outline-none focus:border-blue-500 cursor-pointer"
                        value={selectedYear}
                        onChange={(e) => setSelectedYear(parseInt(e.target.value))}
                    >
                        {availableYears.map(y => <option key={y} value={y}>{y}</option>)}
                    </select>

                    <select 
                        className="border border-gray-300 rounded px-3 py-2 text-sm text-gray-700 outline-none focus:border-blue-500 cursor-pointer bg-white"
                        value={selectedType}
                        onChange={(e) => setSelectedType(e.target.value)}
                    >
                        <option value="">Alle Typen</option>
                        {Object.values(VehicleType).map(t => <option key={t} value={t}>{t}</option>)}
                    </select>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Main Chart */}
                <div className="lg:col-span-2 bg-white p-6 rounded shadow-sm border border-gray-200">
                    <h3 className="font-bold text-gray-700 mb-6 flex justify-between items-center">
                        <span>Aktivität im Jahresverlauf</span>
                        <span className="text-xs bg-gray-100 px-2 py-1 rounded text-gray-600">Gesamt: <strong>{analysisData.total}</strong></span>
                    </h3>
                    <div className="h-64">
                         <SimpleBarChart data={analysisData.monthlyData} height={250} />
                    </div>
                </div>

                {/* Category Distribution */}
                <div className="bg-white p-6 rounded shadow-sm border border-gray-200 flex flex-col">
                    <h3 className="font-bold text-gray-700 mb-4">Verteilung nach Art</h3>
                    <div className="flex-1 flex flex-col justify-center gap-4">
                        {analysisData.categoryData.map(cat => {
                            const percent = analysisData.total > 0 ? Math.round((cat.value / analysisData.total) * 100) : 0;
                            return (
                                <div key={cat.label}>
                                    <div className="flex justify-between text-sm mb-1">
                                        <span className="font-medium text-gray-600">{cat.label}</span>
                                        <span className="font-bold text-gray-800">{cat.value} ({percent}%)</span>
                                    </div>
                                    <div className="w-full bg-gray-100 rounded-full h-2.5 overflow-hidden">
                                        <div 
                                            className={`h-2.5 rounded-full ${cat.label === 'Wartung' ? 'bg-amber-400' : cat.label === 'Prüfung' ? 'bg-purple-500' : 'bg-blue-500'}`} 
                                            style={{ width: `${percent}%` }}
                                        ></div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </div>

            {/* Top Vehicles Table */}
            <div className="bg-white rounded shadow-sm border border-gray-200 overflow-hidden">
                <div className="p-4 border-b border-gray-200 bg-gray-50 flex justify-between items-center">
                    <h3 className="font-bold text-gray-700">Fahrzeuge mit höchstem Wartungsaufwand (Top 10)</h3>
                </div>
                <table className="w-full text-left">
                    <thead className="text-xs text-gray-500 uppercase bg-white border-b border-gray-100">
                        <tr>
                            <th className="p-3">Rang</th>
                            <th className="p-3">Kennzeichen</th>
                            <th className="p-3">Fahrzeug</th>
                            <th className="p-3 text-right">Anzahl Einträge</th>
                            <th className="p-3"></th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100 text-sm">
                        {analysisData.topVehicles.length === 0 ? (
                            <tr><td colSpan={5} className="p-6 text-center text-gray-400 italic">Keine Daten für diesen Zeitraum.</td></tr>
                        ) : (
                            analysisData.topVehicles.map((v, idx) => (
                                <tr key={v.id} className="hover:bg-gray-50">
                                    <td className="p-3 font-mono text-gray-400 font-bold w-12">#{idx + 1}</td>
                                    <td className="p-3 font-bold text-gray-800">{v.license}</td>
                                    <td className="p-3 text-gray-600">{v.model} <span className="text-xs px-1.5 py-0.5 bg-gray-100 rounded ml-2">{v.type}</span></td>
                                    <td className="p-3 text-right font-bold text-blue-600">{v.count}</td>
                                    <td className="p-3 w-full relative"><div className="bg-blue-100 h-1.5 rounded-full" style={{ width: `${Math.min((v.count / (analysisData.topVehicles[0]?.count || 1)) * 100, 100)}%` }}></div></td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import { createRoot } from 'react-dom/client';
import { Vehicle, LogEntry, Order, Priority } from './types';
import { Icons } from './icons';
import { getIsOfflineMode } from './api';
import { getTodayDate } from './utils';

// Hooks
import { useFleetData } from './hooks/useFleetData';

// Components
import { ErrorBoundary, NavButton } from './components/Common';
import { VehicleModal, EntryModal, OrderModal, InspectionModal, CompletionModal } from './components/Modals';

// Views
import { DashboardView } from './views/DashboardView';
import { VehicleListView, CombinationsView } from './views/VehicleView';
import { AppointmentsView, OrdersView } from './views/PlanningView';
import { HistoryView, AdminView } from './views/ReportView';
import { AnalysisView } from './views/AnalysisView';

const App = () => {
    const [view, setView] = useState('dashboard');

    // Use Custom Hook for Data & Business Logic
    const { 
        vehicles, logs, orders, loading, loadData,
        saveVehicle, deleteVehicle, coupleVehicles, uncoupleVehicles,
        saveLogEntry, updateLogStatus, deleteLog, completeTask, completeInspection,
        saveOrder, updateOrderStatus, deleteOrder
    } = useFleetData();

    // Modal UI States (Only UI concern left here)
    const [vehicleModal, setVehicleModal] = useState({ open: false, data: null as Vehicle | null });
    const [entryModal, setEntryModal] = useState({ open: false, data: null as LogEntry | null });
    const [orderModal, setOrderModal] = useState({ open: false, data: null as Order | null });
    const [inspectionModal, setInspectionModal] = useState({ open: false, data: null as LogEntry | null });
    const [completionModal, setCompletionModal] = useState({ open: false, data: null as LogEntry | null });

    // UI Handlers (Wiring Modals to Data Hook)
    const handleStatusUpdate = (log: LogEntry, newStatus: 'IN_PROGRESS' | 'DONE') => {
        if (newStatus === 'DONE') {
            setCompletionModal({ open: true, data: log });
        } else {
            updateLogStatus(log, newStatus);
        }
    };

    const handleInspectionCompletion = async (log: LogEntry, nextDate: string) => {
        const success = await completeInspection(log, nextDate);
        if (success) setInspectionModal({ open: false, data: null });
    };

    const handleTaskCompletion = async (log: LogEntry, mileage: number) => {
        const success = await completeTask(log, mileage);
        if (success) setCompletionModal({ open: false, data: null });
    };

    const handleSaveVehicle = async (v: Vehicle) => {
        const success = await saveVehicle(v);
        if (success) setVehicleModal({ open: false, data: null });
    };

    const handleSaveEntry = async (entries: any[]) => {
        const success = await saveLogEntry(entries);
        if (success) setEntryModal({ open: false, data: null });
    };

    const handleSaveOrder = async (ordersList: any[]) => {
        const success = await saveOrder(ordersList);
        if (success) setOrderModal({ open: false, data: null });
    };

    return (
        <div className="flex h-full bg-gray-100 font-sans text-gray-900">
            {/* Sidebar */}
            <div className="w-64 bg-slate-800 text-white flex flex-col shadow-xl z-10 no-print">
                <div className="p-6 border-b border-slate-700">
                    <h1 className="text-xl font-bold tracking-tight">Fuhrpark<span className="text-blue-400">Manager</span></h1>
                </div>
                <nav className="flex-1 p-4 space-y-2">
                    <NavButton icon={<Icons.Dashboard />} label="ToDo" active={view === 'dashboard'} onClick={() => setView('dashboard')} />
                    <NavButton icon={<Icons.Calendar />} label="Termine" active={view === 'appointments'} onClick={() => setView('appointments')} />
                    <NavButton icon={<Icons.ShoppingCart />} label="Bestellungen" active={view === 'orders'} onClick={() => setView('orders')} />
                    <NavButton icon={<Icons.History />} label="Historie" active={view === 'history'} onClick={() => setView('history')} />
                    <NavButton icon={<Icons.Chart />} label="Auswertung" active={view === 'analysis'} onClick={() => setView('analysis')} />
                    <NavButton icon={<Icons.Link />} label="Gespanne" active={view === 'combinations'} onClick={() => setView('combinations')} />
                    <NavButton icon={<Icons.Truck />} label="Fahrzeuge" active={view === 'vehicles'} onClick={() => setView('vehicles')} />
                    <div className="pt-4 mt-4 border-t border-slate-700">
                        <NavButton icon={<Icons.Database />} label="Admin" active={view === 'admin'} onClick={() => setView('admin')} />
                    </div>
                </nav>
                <div className="p-4 border-t border-slate-700 text-xs text-slate-400">v2.5.0 • {getIsOfflineMode() ? 'Offline Mode' : 'Online'}</div>
            </div>

            {/* Main Content */}
            <div className="flex-1 flex flex-col h-full overflow-hidden">
                <header className="bg-white shadow-sm border-b px-8 py-4 flex justify-between items-center no-print">
                     <h2 className="text-xl font-bold text-gray-800 capitalize">{view === 'dashboard' ? 'ToDo' : view === 'analysis' ? 'Auswertung' : view}</h2>
                     <button onClick={loadData} className="p-2 text-gray-500 hover:bg-gray-100 rounded" title="Refresh"><Icons.History /></button>
                </header>

                <main className="flex-1 overflow-auto p-8">
                    <ErrorBoundary>
                        {loading ? <div className="flex justify-center items-center h-full text-gray-400">Laden...</div> : (
                            <>
                                {view === 'dashboard' && (
                                    <DashboardView 
                                        logs={logs} 
                                        vehicles={vehicles} 
                                        onAdd={() => setEntryModal({open:true, data:null})} 
                                        onInspect={(l:any) => setInspectionModal({open: true, data: l})} 
                                        onStatusUpdate={handleStatusUpdate} 
                                        onEdit={(l:any) => setEntryModal({open:true, data:l})} 
                                        onDelete={deleteLog} 
                                    />
                                )}
                                {view === 'vehicles' && (
                                    <VehicleListView 
                                        vehicles={vehicles} 
                                        onAdd={() => setVehicleModal({open:true, data:null})} 
                                        onEdit={(v:any) => setVehicleModal({open:true, data:v})} 
                                        onDelete={deleteVehicle} 
                                    />
                                )}
                                {view === 'combinations' && (
                                    <CombinationsView 
                                        vehicles={vehicles} 
                                        onCouple={coupleVehicles} 
                                        onUncouple={uncoupleVehicles} 
                                    />
                                )}
                                {view === 'appointments' && (
                                    <AppointmentsView 
                                        vehicles={vehicles} 
                                        onComplete={(apt: any) => {
                                            setInspectionModal({ open: true, data: { id: `virt_${apt.vid}_${apt.inspectionType}`, vehicleId: apt.vid, type: 'Prüfung', description: `${apt.inspectionType} Fällig (${apt.date})`, priority: Priority.NORMAL, dateAdded: getTodayDate(), status: 'OPEN', inspectionType: apt.inspectionType, isVirtual: true } as LogEntry });
                                        }} 
                                    />
                                )}
                                {view === 'orders' && (
                                    <OrdersView 
                                        orders={orders} 
                                        vehicles={vehicles} 
                                        onAdd={() => setOrderModal({open:true, data:null})} 
                                        onEdit={(o:any) => setOrderModal({open:true, data:o})} 
                                        onStatusChange={updateOrderStatus} 
                                        onDelete={deleteOrder} 
                                    />
                                )}
                                {view === 'history' && (
                                    <HistoryView 
                                        logs={logs} 
                                        vehicles={vehicles} 
                                        isAdmin={true} 
                                        onEdit={(l:any) => setEntryModal({open:true, data:l})} 
                                        onDelete={deleteLog} 
                                    />
                                )}
                                {view === 'analysis' && (
                                    <AnalysisView logs={logs} vehicles={vehicles} />
                                )}
                                {view === 'admin' && <AdminView />}
                            </>
                        )}
                    </ErrorBoundary>
                </main>
            </div>

            {/* Modals */}
            <VehicleModal 
                isOpen={vehicleModal.open} 
                onClose={() => setVehicleModal({open:false, data:null})} 
                vehicle={vehicleModal.data} 
                onSave={handleSaveVehicle} 
            />
            <EntryModal 
                isOpen={entryModal.open} 
                onClose={() => setEntryModal({open:false, data:null})} 
                entry={entryModal.data} 
                vehicles={vehicles} 
                onSave={handleSaveEntry} 
            />
            <OrderModal 
                isOpen={orderModal.open} 
                onClose={() => setOrderModal({open:false, data:null})} 
                order={orderModal.data} 
                vehicles={vehicles} 
                onSave={handleSaveOrder} 
            />
            <InspectionModal 
                isOpen={inspectionModal.open} 
                onClose={() => setInspectionModal({open:false, data:null})} 
                log={inspectionModal.data} 
                onSave={handleInspectionCompletion} 
            />
            <CompletionModal 
                isOpen={completionModal.open} 
                onClose={() => setCompletionModal({open:false, data:null})} 
                log={completionModal.data} 
                onConfirm={handleTaskCompletion} 
            />
        </div>
    );
};

