/**
 * @file server.js
 * @description Main Backend Entry Point.
 * 
 * Provides a RESTful API using Express and SQLite.
 * Handles database initialization, migration, and static file serving for the React frontend.
 * 
 * @requires express
 * @requires sqlite3
 * @requires fs
 * @requires path
 */

const express = require('express');
const sqlite3 = require('sqlite3').verbose();
const path = require('path');
const fs = require('fs');

const app = express();
const PORT = process.env.PORT || 3000;

// --- CONFIGURATION ---

// Ensure persistent data directory exists
const dataDir = path.join(__dirname, 'data');
if (!fs.existsSync(dataDir)) {
  fs.mkdirSync(dataDir);
}

// Initialize SQLite Database
const dbPath = path.join(dataDir, 'fuhrpark.db');
const db = new sqlite3.Database(dbPath, (err) => {
  if (err) console.error('Error opening database', err);
  else console.log('Connected to SQLite database at', dbPath);
});

// Middleware configuration
// Increased payload limit to 50mb to support image attachments in logs/repairs
app.use(express.json({ limit: '50mb' }));
app.use(express.urlencoded({ limit: '50mb', extended: true }));

