import { useState, useEffect, useCallback } from 'react';
import { Vehicle, LogEntry, Order, OrderStatus, Priority } from '../types';
import { api } from '../api';
import { getTodayDate } from '../utils';

/**
 * Custom Hook: useFleetData
 * 
 * Central State Management for the application.
 * Handles fetching, polling, and CRUD operations for Vehicles, Logs, and Orders.
 * Implements business logic for task completion and inspection scheduling.
 */
export const useFleetData = () => {
    // --- STATE ---
    const [vehicles, setVehicles] = useState<Vehicle[]>([]);
    const [logs, setLogs] = useState<LogEntry[]>([]);
    const [orders, setOrders] = useState<Order[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    /**
     * Fetches all data from the API.
     * @param silentArg - If true, suppresses the loading spinner (used for background polling).
     */
    const loadData = useCallback(async (silentArg: boolean | any = false) => {
        // If called from an Event (onClick), silentArg is an Object. Treat as false (show loading).
        // If called from Interval, silentArg is true. Treat as true (silent).
        const isSilent = typeof silentArg === 'boolean' ? silentArg : false;

        if (!isSilent) {
            setLoading(true);
            setError(null);
        }

        try {
            const [v, l, o] = await Promise.all([
                api.get('/vehicles'),
                api.get('/logs'),
                api.get('/orders')
            ]);
            setVehicles(Array.isArray(v) ? v : []);
            setLogs(Array.isArray(l) ? l : []);
            setOrders(Array.isArray(o) ? o : []);
        } catch (e: any) {
            console.error(e);
            if (!isSilent) setError(e.message || "Fehler beim Laden der Daten");
        } finally {
            if (!isSilent) setLoading(false);
        }
    }, []);

    // Initial Load & Polling Mechanism (every 30s)
    useEffect(() => { 
        loadData(); 

        const interval = setInterval(() => {
            loadData(true); // Silent update
        }, 30000);

        return () => clearInterval(interval);
    }, [loadData]);

    // --- VEHICLE OPERATIONS ---

    const saveVehicle = async (v: Vehicle) => {
        try {
            if(v.id && vehicles.find(x => x.id === v.id)) {
                await api.put(`/vehicles/${v.id}`, v);
            } else {
                await api.post('/vehicles', v);
            }
            await loadData(true); // Refresh silently to keep UI stable
            return true;
        } catch (e) { console.error(e); return false; }
    };

    const deleteVehicle = async (id: string) => {
        if(!confirm('Fahrzeug wirklich löschen?')) return false;
        try {
            await api.delete(`/vehicles/${id}`);
            await loadData(true);
            return true;
        } catch (e) { console.error(e); return false; }
    };

    /**
     * Couples two vehicles (e.g. Truck + Trailer).
     * Updates both vehicle records to reference each other.
     */
    const coupleVehicles = async (motorId: string, trailerId: string) => {
        const motor = vehicles.find(v => v.id === motorId);
        const trailer = vehicles.find(v => v.id === trailerId);
        if(motor && trailer) {
            await api.put(`/vehicles/${motor.id}`, { ...motor, coupledVehicleId: trailer.id });
            await api.put(`/vehicles/${trailer.id}`, { ...trailer, coupledVehicleId: motor.id });
            await loadData(true);
        }
    };

    /**
     * Decouples a vehicle combination.
     */
    const uncoupleVehicles = async (motorId: string, trailerId?: string) => {
        const motor = vehicles.find(v => v.id === motorId);
        if(motor) await api.put(`/vehicles/${motor.id}`, { ...motor, coupledVehicleId: null });

        if(trailerId) {
            const trailer = vehicles.find(v => v.id === trailerId);
            if(trailer) await api.put(`/vehicles/${trailer.id}`, { ...trailer, coupledVehicleId: null });
        }
        await loadData(true);
    };

    // --- LOG / TASK OPERATIONS ---

    const saveLogEntry = async (entries: any[]) => {
        try {
            for (const entry of entries) {
                if(entry.id && logs.find(x => x.id === entry.id)) {
                    await api.put(`/logs/${entry.id}`, entry);
                } else {
                    await api.post('/logs', entry);
                }
            }
            await loadData(true);
            return true;
        } catch (e) { console.error(e); return false; }
    };

    const updateLogStatus = async (log: LogEntry, newStatus: 'IN_PROGRESS' | 'DONE') => {
        try {
            await api.put(`/logs/${log.id}`, { ...log, status: newStatus });
            await loadData(true);
        } catch (e) { console.error(e); }
    };

    const deleteLog = async (id: string) => {
        if(!confirm('Eintrag löschen?')) return false;
        try {
            await api.delete(`/logs/${id}`);
            await loadData(true);
            return true;
        } catch (e) { console.error(e); return false; }
    };

    // --- BUSINESS LOGIC: COMPLETIONS ---

    /**
     * Completes a generic task and optionally updates the vehicle's mileage.
     * Only updates mileage if the new value is higher than the current one.
     */
    const completeTask = async (log: LogEntry, mileage: number) => {
        try {
            // 1. Update Log
            await api.put(`/logs/${log.id}`, { 
                ...log, 
                status: 'DONE', 
                dateCompleted: getTodayDate(), 
                mileage: mileage 
            });

            // 2. Update Vehicle Mileage (Business Logic: Only update if higher)
            const vehicle = vehicles.find(v => v.id === log.vehicleId);
            if(vehicle && mileage > (vehicle.currentMileage || 0)) {
                await api.put(`/vehicles/${vehicle.id}`, { ...vehicle, currentMileage: mileage });
            }

            await loadData(true);
            return true;
        } catch(e) { console.error(e); return false; }
    };

    /**
     * Completes a recurring inspection (HU, SP, etc.).
     * 1. Creates a historical log entry ("Wartung").
     * 2. Updates the vehicle's next due date for this inspection type.
     */
    const completeInspection = async (log: LogEntry, nextDate: string) => {
        try {
            const [y, m] = nextDate.split('-'); // YYYY-MM from input

            // 1. Create archival log
            await api.post('/logs', {
                vehicleId: log.vehicleId,
                type: 'Wartung',
                description: `${log.inspectionType} Prüfung durchgeführt`,
                priority: Priority.NORMAL,
                dateAdded: getTodayDate(),
                status: 'DONE',
                dateCompleted: getTodayDate(),
                inspectionType: log.inspectionType
            });

            // 2. Update Vehicle Next Date
            const vehicle = vehicles.find(v => v.id === log.vehicleId);
            if (vehicle && log.inspectionType) {
                // Determine which field to update based on inspection type
                const updateField = `next${log.inspectionType}`; 
                // Store as MM/YYYY
                await api.put(`/vehicles/${vehicle.id}`, { ...vehicle, [updateField]: `${m}/${y}` });
            }

            await loadData(true);
            return true;
        } catch(e) { console.error(e); return false; }
    };

    // --- ORDER OPERATIONS ---

    const saveOrder = async (ordersList: any[]) => {
        try {
            for (const o of ordersList) {
                if(o.id && orders.find(x => x.id === o.id)) {
                    await api.put(`/orders/${o.id}`, o);
                } else {
                    await api.post('/orders', o);
                }
            }
            await loadData(true);
            return true;
        } catch (e) { console.error(e); return false; }
    };

    const updateOrderStatus = async (id: string, status: OrderStatus) => {
        const order = orders.find(o => o.id === id);
        if(order) {
            await api.put(`/orders/${id}`, { ...order, status });
            await loadData(true);
        }
    };

    const deleteOrder = async (id: string) => {
        if(!confirm('Bestellung löschen?')) return false;
        try {
            await api.delete(`/orders/${id}`);
            await loadData(true);
            return true;
        } catch (e) { console.error(e); return false; }
    };

    return {
        // State
        vehicles,
        logs,
        orders,
        loading,
        error,

        // Actions
        loadData,
        saveVehicle,
        deleteVehicle,
        coupleVehicles,
        uncoupleVehicles,

        saveLogEntry,
        updateLogStatus,
        deleteLog,
        completeTask,
        completeInspection,

        saveOrder,
        updateOrderStatus,
        deleteOrder
    };
};

/**
 * @file types.ts
 * @description Type definitions for the application's data models.
 */

export enum VehicleType {
  PKW = 'PKW',
  LKW = 'LKW',
  TRANSPORTER = 'Transporter',
  ANHAENGER = 'Anhänger',
  AUFLIEGER = 'Auflieger',
  SONSTIGE = 'Sonstige',
  MASCHINE = 'Maschine'
}

export enum Priority {
  LOW = 'Niedrig',
  NORMAL = 'Normal',
  HIGH = 'Dringend',
}

export enum OrderStatus {
  OFFEN = 'Offen',
  BESTELLT = 'Bestellt',
  ERLEDIGT = 'Erledigt',
}

export interface Attachment {
  name: string;
  data: string; // Base64 encoded string
  type: string; // MIME Type
}

/**
 * Represents a Vehicle in the fleet.
 */
export interface Vehicle {
  id: string;
  licensePlate: string;
  type: VehicleType | string;
  manufacturer: string;
  model: string; // Typ / Series
  vin: string; // Vehicle Identification Number
  year: number;
  notes: string;

  /** 
   * ID of the trailer or truck this vehicle is coupled with.
   * Enables logic for "Gespanne" (Combinations).
   */
  coupledVehicleId?: string | null; 

  // Inspection Due Dates (Stored as MM/YYYY string)
  nextHU?: string;
  nextSP?: string;
  nextUVV?: string;
  nextTacho?: string;

  currentMileage?: number; // KM or Hours
}

/**
 * Represents a Task or Inspection Log.
 * Can be an active todo ('OPEN') or historical record ('DONE').
 */
export interface LogEntry {
  id: string;
  vehicleId: string;
  type: string; // Generic type like 'Aufgabe' or 'Wartung'
  description: string;
  priority: Priority;
  dateAdded: string; // ISO Date String (YYYY-MM-DD)
  dateCompleted?: string;
  status: 'OPEN' | 'IN_PROGRESS' | 'DONE';
  mileage?: number;

  // Specific for recurring inspections
  inspectionType?: 'HU' | 'SP' | 'UVV' | 'Tacho';

  // Attachments (Images, PDFs)
  attachments?: Attachment[];

  // Frontend specific flag
  // If true, this is a calculated entry based on vehicle due dates, not a database record.
  isVirtual?: boolean; 
}

/**
 * Represents a spare part order.
 */
export interface Order {
  id: string;
  description: string;
  vehicleId?: string;
  dateAdded: string;
  status: OrderStatus;
  supplier?: string;
}

/**
 * @file server.js
