      <div className="bg-white rounded shadow border border-gray-200 overflow-hidden">
        {filteredOrders.length === 0 && <div className="p-12 text-center text-gray-400 italic">Keine Bestellungen vorhanden.</div>}
        {filteredOrders.map((o: Order) => {
            const vehicle = safeVehicles.find((v:Vehicle) => v.id === o.vehicleId);
            const isUrgent = o.description.includes('[Dringend]');
            const isLow = o.description.includes('[Niedrig]');
            return (
              <div key={o.id} className="p-4 border-b last:border-b-0 flex flex-col md:flex-row md:items-center justify-between hover:bg-gray-50 gap-4 transition-colors">
