import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Vehicle, LogEntry, Order, OrderStatus, Priority } from '../types';
import { api } from '../api';
import { getTodayDate } from '../utils';

/**
 * Custom Hook: useFleetData (React Query Version)
 * 
 * Acts as a facade for React Query hooks to maintain compatibility 
 * with the existing view components while providing caching and auto-refetching.
 */
export const useFleetData = () => {
    const queryClient = useQueryClient();

    // --- QUERIES ---

    const vehiclesQuery = useQuery({
        queryKey: ['vehicles'],
        queryFn: () => api.get('/vehicles'),
        refetchInterval: 30000, // Poll every 30s
        staleTime: 10000,
    });

    const logsQuery = useQuery({
        queryKey: ['logs'],
        queryFn: () => api.get('/logs'),
        refetchInterval: 30000,
        staleTime: 10000,
    });

    const ordersQuery = useQuery({
        queryKey: ['orders'],
        queryFn: () => api.get('/orders'),
        refetchInterval: 30000,
        staleTime: 10000,
    });

    const loading = vehiclesQuery.isLoading || logsQuery.isLoading || ordersQuery.isLoading;

    // Explicit reload function (just invalidates queries to trigger refetch)
    const loadData = async () => {
        await Promise.all([
            queryClient.invalidateQueries({ queryKey: ['vehicles'] }),
            queryClient.invalidateQueries({ queryKey: ['logs'] }),
            queryClient.invalidateQueries({ queryKey: ['orders'] })
        ]);
    };

    // --- MUTATIONS (Vehicles) ---

    const saveVehicleMutation = useMutation({
        mutationFn: (v: Vehicle) => {
            return v.id && vehiclesQuery.data?.find((x: Vehicle) => x.id === v.id)
                ? api.put(`/vehicles/${v.id}`, v)
                : api.post('/vehicles', v);
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['vehicles'] })
    });

    const deleteVehicleMutation = useMutation({
        mutationFn: (id: string) => api.delete(`/vehicles/${id}`),
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['vehicles'] })
    });

    const coupleMutation = useMutation({
        mutationFn: async ({ motorId, trailerId }: { motorId: string, trailerId: string }) => {
            const motor = vehiclesQuery.data.find((v:Vehicle) => v.id === motorId);
            const trailer = vehiclesQuery.data.find((v:Vehicle) => v.id === trailerId);
            if(motor && trailer) {
                await api.put(`/vehicles/${motor.id}`, { ...motor, coupledVehicleId: trailer.id });
                await api.put(`/vehicles/${trailer.id}`, { ...trailer, coupledVehicleId: motor.id });
            }
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['vehicles'] })
    });

    const uncoupleMutation = useMutation({
        mutationFn: async ({ motorId, trailerId }: { motorId: string, trailerId?: string }) => {
            const motor = vehiclesQuery.data.find((v:Vehicle) => v.id === motorId);
            if(motor) await api.put(`/vehicles/${motor.id}`, { ...motor, coupledVehicleId: null });
            if(trailerId) {
                const trailer = vehiclesQuery.data.find((v:Vehicle) => v.id === trailerId);
                if(trailer) await api.put(`/vehicles/${trailer.id}`, { ...trailer, coupledVehicleId: null });
            }
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['vehicles'] })
    });

    // --- MUTATIONS (Logs) ---

    const saveLogMutation = useMutation({
        mutationFn: async (entries: any[]) => {
            for (const entry of entries) {
                if(entry.id && logsQuery.data?.find((x: LogEntry) => x.id === entry.id)) {
                    await api.put(`/logs/${entry.id}`, entry);
                } else {
                    await api.post('/logs', entry);
                }
            }
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['logs'] })
    });

    const updateLogStatusMutation = useMutation({
        mutationFn: ({ log, newStatus }: { log: LogEntry, newStatus: string }) => 
            api.put(`/logs/${log.id}`, { ...log, status: newStatus }),
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['logs'] })
    });

    const deleteLogMutation = useMutation({
        mutationFn: (id: string) => api.delete(`/logs/${id}`),
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['logs'] })
    });

    const completeTaskMutation = useMutation({
        mutationFn: async ({ log, mileage }: { log: LogEntry, mileage: number }) => {
             // 1. Update Log
             await api.put(`/logs/${log.id}`, { 
                ...log, 
                status: 'DONE', 
                dateCompleted: getTodayDate(), 
                mileage: mileage 
            });
            // 2. Update Vehicle Mileage (Business Logic: Only update if higher)
            const vehicle = vehiclesQuery.data?.find((v:Vehicle) => v.id === log.vehicleId);
            if(vehicle && mileage > (vehicle.currentMileage || 0)) {
                await api.put(`/vehicles/${vehicle.id}`, { ...vehicle, currentMileage: mileage });
            }
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['logs'] });
            queryClient.invalidateQueries({ queryKey: ['vehicles'] });
        }
    });

    const completeInspectionMutation = useMutation({
        mutationFn: async ({ log, nextDate }: { log: LogEntry, nextDate: string }) => {
            const [y, m] = nextDate.split('-');
            // 1. Create archival log
            await api.post('/logs', {
                vehicleId: log.vehicleId,
                type: 'Wartung',
                description: `${log.inspectionType} Prüfung durchgeführt`,
                priority: Priority.NORMAL,
                dateAdded: getTodayDate(),
                status: 'DONE',
                dateCompleted: getTodayDate(),
                inspectionType: log.inspectionType
            });
            // 2. Update Vehicle Next Date
            const vehicle = vehiclesQuery.data?.find((v:Vehicle) => v.id === log.vehicleId);
            if (vehicle && log.inspectionType) {
                const updateField = `next${log.inspectionType}`; 
                await api.put(`/vehicles/${vehicle.id}`, { ...vehicle, [updateField]: `${m}/${y}` });
            }
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['logs'] });
            queryClient.invalidateQueries({ queryKey: ['vehicles'] });
        }
    });

    // --- MUTATIONS (Orders) ---

    const saveOrderMutation = useMutation({
        mutationFn: async (ordersList: any[]) => {
            for (const o of ordersList) {
                if(o.id && ordersQuery.data?.find((x: Order) => x.id === o.id)) {
                    await api.put(`/orders/${o.id}`, o);
                } else {
                    await api.post('/orders', o);
                }
            }
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['orders'] })
    });

    const updateOrderStatusMutation = useMutation({
        mutationFn: async ({ id, status }: { id: string, status: OrderStatus }) => {
            const order = ordersQuery.data?.find((o: Order) => o.id === id);
            if(order) await api.put(`/orders/${id}`, { ...order, status });
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['orders'] })
    });

    const deleteOrderMutation = useMutation({
        mutationFn: (id: string) => api.delete(`/orders/${id}`),
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['orders'] })
    });


    // --- RETURN API (Matches old interface mostly) ---
    return {
        vehicles: vehiclesQuery.data || [],
        logs: logsQuery.data || [],
        orders: ordersQuery.data || [],
        loading,
        error: vehiclesQuery.error || logsQuery.error || ordersQuery.error,

        loadData,

        saveVehicle: async (v: Vehicle) => { await saveVehicleMutation.mutateAsync(v); return true; },
        deleteVehicle: async (id: string) => { if(!confirm('Fahrzeug löschen?')) return false; await deleteVehicleMutation.mutateAsync(id); return true; },
        coupleVehicles: async (m: string, t: string) => coupleMutation.mutateAsync({ motorId: m, trailerId: t }),
        uncoupleVehicles: async (m: string, t?: string) => uncoupleMutation.mutateAsync({ motorId: m, trailerId: t }),

        saveLogEntry: async (entries: any[]) => { await saveLogMutation.mutateAsync(entries); return true; },
        updateLogStatus: async (log: LogEntry, newStatus: 'IN_PROGRESS' | 'DONE') => updateLogStatusMutation.mutateAsync({ log, newStatus }),
        deleteLog: async (id: string) => { if(!confirm('Eintrag löschen?')) return false; await deleteLogMutation.mutateAsync(id); return true; },
        completeTask: async (log: LogEntry, mileage: number) => { await completeTaskMutation.mutateAsync({ log, mileage }); return true; },
        completeInspection: async (log: LogEntry, nextDate: string) => { await completeInspectionMutation.mutateAsync({ log, nextDate }); return true; },

        saveOrder: async (orders: any[]) => { await saveOrderMutation.mutateAsync(orders); return true; },
        updateOrderStatus: async (id: string, status: OrderStatus) => updateOrderStatusMutation.mutateAsync({ id, status }),
        deleteOrder: async (id: string) => { if(!confirm('Bestellung löschen?')) return false; await deleteOrderMutation.mutateAsync(id); return true; },
    };
};

