import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Vehicle } from '../types';
import { api } from '../api';

export const useVehicles = () => {
    const queryClient = useQueryClient();

    const query = useQuery({
        queryKey: ['vehicles'],
        queryFn: () => api.get('/vehicles'),
        refetchInterval: 30000,
        staleTime: 10000,
    });

    const saveMutation = useMutation({
        mutationFn: (v: Vehicle) => {
            return v.id && query.data?.find((x: Vehicle) => x.id === v.id)
                ? api.put(`/vehicles/${v.id}`, v)
                : api.post('/vehicles', v);
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['vehicles'] })
    });

    const deleteMutation = useMutation({
        mutationFn: (id: string) => api.delete(`/vehicles/${id}`),
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['vehicles'] })
    });

    const coupleMutation = useMutation({
        mutationFn: async ({ motorId, trailerId }: { motorId: string, trailerId: string }) => {
            const motor = query.data.find((v:Vehicle) => v.id === motorId);
            const trailer = query.data.find((v:Vehicle) => v.id === trailerId);
            if(motor && trailer) {
                await api.put(`/vehicles/${motor.id}`, { ...motor, coupledVehicleId: trailer.id });
                await api.put(`/vehicles/${trailer.id}`, { ...trailer, coupledVehicleId: motor.id });
            }
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['vehicles'] })
    });

    const uncoupleMutation = useMutation({
        mutationFn: async ({ motorId, trailerId }: { motorId: string, trailerId?: string }) => {
            const motor = query.data.find((v:Vehicle) => v.id === motorId);
            if(motor) await api.put(`/vehicles/${motor.id}`, { ...motor, coupledVehicleId: null });
            if(trailerId) {
                const trailer = query.data.find((v:Vehicle) => v.id === trailerId);
                if(trailer) await api.put(`/vehicles/${trailer.id}`, { ...trailer, coupledVehicleId: null });
            }
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['vehicles'] })
    });

    return {
        vehicles: query.data || [],
        loading: query.isLoading,
        error: query.error,
        refetch: query.refetch,
        saveVehicle: async (v: Vehicle) => { await saveMutation.mutateAsync(v); return true; },
        deleteVehicle: async (id: string) => { if(!confirm('Fahrzeug löschen?')) return false; await deleteMutation.mutateAsync(id); return true; },
        coupleVehicles: async (m: string, t: string) => coupleMutation.mutateAsync({ motorId: m, trailerId: t }),
        uncoupleVehicles: async (m: string, t?: string) => uncoupleMutation.mutateAsync({ motorId: m, trailerId: t }),
    };
};

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { LogEntry, Priority, Vehicle } from '../types';
import { api } from '../api';
import { getTodayDate } from '../utils';

export const useLogs = () => {
    const queryClient = useQueryClient();

    const query = useQuery({
        queryKey: ['logs'],
        queryFn: () => api.get('/logs'),
        refetchInterval: 30000,
        staleTime: 10000,
    });

    const saveMutation = useMutation({
        mutationFn: async (entries: any[]) => {
            for (const entry of entries) {
                // Check if ID exists to determine update vs create. 
                // Note: ideally API handles this, but keeping logic consistent with existing backend.
                if(entry.id && query.data?.find((x: LogEntry) => x.id === entry.id)) {
                    await api.put(`/logs/${entry.id}`, entry);
                } else {
                    await api.post('/logs', entry);
                }
            }
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['logs'] })
    });

    const updateStatusMutation = useMutation({
        mutationFn: ({ log, newStatus }: { log: LogEntry, newStatus: string }) => 
            api.put(`/logs/${log.id}`, { ...log, status: newStatus }),
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['logs'] })
    });

    const deleteMutation = useMutation({
        mutationFn: (id: string) => api.delete(`/logs/${id}`),
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['logs'] })
    });

    const completeTaskMutation = useMutation({
        mutationFn: async ({ log, mileage }: { log: LogEntry, mileage: number }) => {
             await api.put(`/logs/${log.id}`, { 
                ...log, 
                status: 'DONE', 
                dateCompleted: getTodayDate(), 
                mileage: mileage 
            });
            // Side Effect: Update Vehicle Mileage via API directly or invalidate vehicle query
            // Ideally backend handles this trigger, but for now we do it here or let the vehicle hook handle it.
            // We'll assume the user uses invalidateQueries(['vehicles']) in the facade or here.

            // To keep separation clean: We fetch the vehicle just to update it here? 
            // Better: Just update the specific vehicle endpoint blindly if we had one.
            // For now, we'll implement the logic:
            const vehicles = queryClient.getQueryData(['vehicles']) as Vehicle[];
            const vehicle = vehicles?.find((v:Vehicle) => v.id === log.vehicleId);
            if(vehicle && mileage > (vehicle.currentMileage || 0)) {
                await api.put(`/vehicles/${vehicle.id}`, { ...vehicle, currentMileage: mileage });
            }
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['logs'] });
            queryClient.invalidateQueries({ queryKey: ['vehicles'] });
        }
    });

    const completeInspectionMutation = useMutation({
        mutationFn: async ({ log, nextDate }: { log: LogEntry, nextDate: string }) => {
            const [y, m] = nextDate.split('-');
            await api.post('/logs', {
                vehicleId: log.vehicleId,
                type: 'Wartung',
                description: `${log.inspectionType} Prüfung durchgeführt`,
                priority: Priority.NORMAL,
                dateAdded: getTodayDate(),
                status: 'DONE',
                dateCompleted: getTodayDate(),
                inspectionType: log.inspectionType
            });

            const vehicles = queryClient.getQueryData(['vehicles']) as Vehicle[];
            const vehicle = vehicles?.find((v:Vehicle) => v.id === log.vehicleId);
            if (vehicle && log.inspectionType) {
                const updateField = `next${log.inspectionType}`; 
                // @ts-ignore
                await api.put(`/vehicles/${vehicle.id}`, { ...vehicle, [updateField]: `${m}/${y}` });
            }
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['logs'] });
            queryClient.invalidateQueries({ queryKey: ['vehicles'] });
        }
    });

    return {
        logs: query.data || [],
        loading: query.isLoading,
        error: query.error,
        refetch: query.refetch,
        saveLogEntry: async (entries: any[]) => { await saveMutation.mutateAsync(entries); return true; },
        updateLogStatus: async (log: LogEntry, newStatus: 'IN_PROGRESS' | 'DONE') => updateStatusMutation.mutateAsync({ log, newStatus }),
        deleteLog: async (id: string) => { if(!confirm('Eintrag löschen?')) return false; await deleteMutation.mutateAsync(id); return true; },
        completeTask: async (log: LogEntry, mileage: number) => { await completeTaskMutation.mutateAsync({ log, mileage }); return true; },
        completeInspection: async (log: LogEntry, nextDate: string) => { await completeInspectionMutation.mutateAsync({ log, nextDate }); return true; },
    };
};

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Order, OrderStatus } from '../types';
import { api } from '../api';

export const useOrders = () => {
    const queryClient = useQueryClient();

    const query = useQuery({
        queryKey: ['orders'],
        queryFn: () => api.get('/orders'),
        refetchInterval: 30000,
        staleTime: 10000,
    });

    const saveMutation = useMutation({
        mutationFn: async (ordersList: any[]) => {
            for (const o of ordersList) {
                if(o.id && query.data?.find((x: Order) => x.id === o.id)) {
                    await api.put(`/orders/${o.id}`, o);
                } else {
                    await api.post('/orders', o);
                }
            }
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['orders'] })
    });

    const updateStatusMutation = useMutation({
        mutationFn: async ({ id, status }: { id: string, status: OrderStatus }) => {
            const order = query.data?.find((o: Order) => o.id === id);
            if(order) await api.put(`/orders/${id}`, { ...order, status });
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['orders'] })
    });

    const deleteMutation = useMutation({
        mutationFn: (id: string) => api.delete(`/orders/${id}`),
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['orders'] })
    });

    return {
        orders: query.data || [],
        loading: query.isLoading,
        error: query.error,
        refetch: query.refetch,
        saveOrder: async (orders: any[]) => { await saveMutation.mutateAsync(orders); return true; },
        updateOrderStatus: async (id: string, status: OrderStatus) => updateStatusMutation.mutateAsync({ id, status }),
        deleteOrder: async (id: string) => { if(!confirm('Bestellung löschen?')) return false; await deleteMutation.mutateAsync(id); return true; },
    };
};

import { useVehicles } from './useVehicles';
import { useLogs } from './useLogs';
import { useOrders } from './useOrders';

/**
 * Custom Hook: useFleetData (Facade Version)
 * 
 * This hook now acts as an aggregator (Facade) for the individual domain hooks.
 * It maintains the original API signature so we don't break existing views,
 * but allows the underlying logic to be separated.
 */
export const useFleetData = () => {
    const vehicleHook = useVehicles();
    const logHook = useLogs();
    const orderHook = useOrders();

    const loadData = async () => {
        await Promise.all([
            vehicleHook.refetch(),
            logHook.refetch(),
            orderHook.refetch()
        ]);
    };

    return {
        // Data
        vehicles: vehicleHook.vehicles,
        logs: logHook.logs,
        orders: orderHook.orders,

        // Meta
        loading: vehicleHook.loading || logHook.loading || orderHook.loading,
        error: vehicleHook.error || logHook.error || orderHook.error,
        loadData,

        // Vehicle Actions
        saveVehicle: vehicleHook.saveVehicle,
        deleteVehicle: vehicleHook.deleteVehicle,
        coupleVehicles: vehicleHook.coupleVehicles,
        uncoupleVehicles: vehicleHook.uncoupleVehicles,

        // Log Actions
        saveLogEntry: logHook.saveLogEntry,
        updateLogStatus: logHook.updateLogStatus,
        deleteLog: logHook.deleteLog,
        completeTask: logHook.completeTask,
        completeInspection: logHook.completeInspection,

        // Order Actions
        saveOrder: orderHook.saveOrder,
        updateOrderStatus: orderHook.updateOrderStatus,
        deleteOrder: orderHook.deleteOrder,
    };
};

import React, { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Vehicle, LogEntry, Order, Priority } from '../types';
import { Icons } from '../icons';
import { getIsOfflineMode } from '../api';
import { getTodayDate } from '../utils';

// Hooks
import { useFleetData } from '../hooks/useFleetData';

// Components
import { ErrorBoundary, NavButton } from './Common';
// Modals
import { VehicleModal } from './modals/VehicleModal';
import { EntryModal } from './modals/EntryModal';
import { OrderModal } from './modals/OrderModal';
import { InspectionModal } from './modals/InspectionModal';
import { CompletionModal } from './modals/CompletionModal';

interface LayoutProps {
    children: React.ReactNode;
}

export const Layout = ({ children }: LayoutProps) => {
    const navigate = useNavigate();
    const location = useLocation();

    // Data & Logic Hook (Global scope for Modals)
    const { 
        vehicles, logs, orders, loading, loadData,
        saveVehicle, deleteVehicle, coupleVehicles, uncoupleVehicles,
        saveLogEntry, updateLogStatus, deleteLog, completeTask, completeInspection,
        saveOrder, updateOrderStatus, deleteOrder
    } = useFleetData();

    // Modal UI States
    const [vehicleModal, setVehicleModal] = useState({ open: false, data: null as Vehicle | null });
    const [entryModal, setEntryModal] = useState({ open: false, data: null as LogEntry | null });
    const [orderModal, setOrderModal] = useState({ open: false, data: null as Order | null });
    const [inspectionModal, setInspectionModal] = useState({ open: false, data: null as LogEntry | null });
    const [completionModal, setCompletionModal] = useState({ open: false, data: null as LogEntry | null });

    // Handlers
    const handleStatusUpdate = (log: LogEntry, newStatus: 'IN_PROGRESS' | 'DONE') => {
        if (newStatus === 'DONE') setCompletionModal({ open: true, data: log });
        else updateLogStatus(log, newStatus);
    };

    const handleInspectionCompletion = async (log: LogEntry, nextDate: string) => {
        const success = await completeInspection(log, nextDate);
        if (success) setInspectionModal({ open: false, data: null });
    };

    const handleTaskCompletion = async (log: LogEntry, mileage: number) => {
        const success = await completeTask(log, mileage);
        if (success) setCompletionModal({ open: false, data: null });
    };

    const handleSaveVehicle = async (v: Vehicle) => {
        const success = await saveVehicle(v);
        if (success) setVehicleModal({ open: false, data: null });
    };

    const handleSaveEntry = async (entries: any[]) => {
        const success = await saveLogEntry(entries);
        if (success) setEntryModal({ open: false, data: null });
    };

    const handleSaveOrder = async (ordersList: any[]) => {
        const success = await saveOrder(ordersList);
        if (success) setOrderModal({ open: false, data: null });
    };

    // Propagate props to children (cloneElement would be messy, so we use Context or simple passing if children were components, 
    // but here children is the <Routes> block. 
    // Ideally, Views should use the hooks directly! 
    // BUT: To keep "Phase 2" simple without breaking 10 files, we are passing props via React.cloneElement in index.tsx OR
    // we actually move the Routes definition INSIDE here or keep it as is.

    // For this refactor, we will actually RENDER the children passed to us, 
    // but we need to pass the modal triggers DOWN to the views.
    // This reveals the architecture flaw: The Layout owns the modals, but the Views trigger them.

    // SOLUTION: We render the children, but we assume the children are the Routes.
    // The Routes in index.tsx need the data to pass to the views.
    // This suggests Layout should probably just Wrap the visual part, and Data fetching stays in App 
    // OR we provide a Context.

    // To solve this cleanly for you now:
    // We will clone the children to inject props. This is legacy React style but effective here.
    const childrenWithProps = React.Children.map(children, child => {
        if (React.isValidElement(child)) {
            // @ts-ignore
            return React.cloneElement(child, {
                // Pass Data
                logs, vehicles, orders, loading,
                // Pass Actions
                onAdd: () => {}, // Default overridden below based on context
                onInspect: (l:any) => setInspectionModal({open: true, data: l}),
                onStatusUpdate: handleStatusUpdate,
                onEdit: (l:any) => setEntryModal({open:true, data:l}),
                onDelete: deleteLog,
                // Specifics for specific views
                onCouple: coupleVehicles,
                onUncouple: uncoupleVehicles,
                onComplete: (apt: any) => {
                     setInspectionModal({ open: true, data: { id: `virt_${apt.vid}_${apt.inspectionType}`, vehicleId: apt.vid, type: 'Prüfung', description: `${apt.inspectionType} Fällig (${apt.date})`, priority: Priority.NORMAL, dateAdded: getTodayDate(), status: 'OPEN', inspectionType: apt.inspectionType, isVirtual: true } as LogEntry });
                },
                onStatusChange: updateOrderStatus,
                // Modal Openers (injected based on view type usually, but we expose them all)
                openEntryModal: (data?: any) => setEntryModal({open:true, data: data || null}),
                openVehicleModal: (data?: any) => setVehicleModal({open:true, data: data || null}),
                openOrderModal: (data?: any) => setOrderModal({open:true, data: data || null}),

                // Compatibility mapping for existing Views
                onAddEntry: () => setEntryModal({open:true, data:null}),
                onAddVehicle: () => setVehicleModal({open:true, data:null}),
                onAddOrder: () => setOrderModal({open:true, data:null}),
            });
        }
        return child;
    });

    // Determine current path for header
    const currentPath = location.pathname;
    const getPageTitle = () => {
        if(currentPath.includes('appointments')) return 'Termine';
        if(currentPath.includes('orders')) return 'Bestellungen';
        if(currentPath.includes('history')) return 'Historie';
        if(currentPath.includes('analysis')) return 'Auswertung';
        if(currentPath.includes('combinations')) return 'Gespanne';
        if(currentPath.includes('vehicles')) return 'Fahrzeuge';
        if(currentPath.includes('admin')) return 'Admin';
        return 'ToDo';
    };

    // Helper to get the right "Add" function for the header button if we wanted one there
    // For now, views have their own buttons.

    return (
        <div className="flex h-full bg-gray-100 font-sans text-gray-900">
            {/* Sidebar */}
            <div className="w-64 bg-slate-800 text-white flex flex-col shadow-xl z-10 no-print">
                <div className="p-6 border-b border-slate-700">
                    <h1 className="text-xl font-bold tracking-tight">Fuhrpark<span className="text-blue-400">Manager</span></h1>
                </div>
                <nav className="flex-1 p-4 space-y-2">
                    <NavButton icon={<Icons.Dashboard />} label="ToDo" active={currentPath === '/'} onClick={() => navigate('/')} />
                    <NavButton icon={<Icons.Calendar />} label="Termine" active={currentPath === '/appointments'} onClick={() => navigate('/appointments')} />
                    <NavButton icon={<Icons.ShoppingCart />} label="Bestellungen" active={currentPath === '/orders'} onClick={() => navigate('/orders')} />
