// Components
import { Layout } from './components/Layout';

// Views
import { DashboardView } from './views/DashboardView';
import { VehicleListView, CombinationsView } from './views/VehicleView';
import { AppointmentsView, OrdersView } from './views/PlanningView';
import { HistoryView, AdminView } from './views/ReportView';
import { AnalysisView } from './views/AnalysisView';

// --- SETUP QUERY CLIENT ---
const queryClient = new QueryClient({
    defaultOptions: {
        queries: {
            retry: 1,
            refetchOnWindowFocus: false,
        }
    }
});

/**
 * RouteWrapper
 * Helper component to bridge the Layout's props to the View.
 * The Layout clones its children and injects props (logs, vehicles, actions).
 * This component simply spreads those injected props to the specific View.
 */
const RouteWrapper = (props: any) => {
    const { Component, ...rest } = props;

    // Map generic props to specific view handlers if necessary
    // DashboardView needs: onAdd, onInspect, onStatusUpdate, onEdit, onDelete
    // These are already passed in 'rest' by the Layout.

    // Specifically mapping 'openXModal' to 'onAdd' where appropriate
    let viewProps = { ...rest };

    if (Component === DashboardView) {
        viewProps.onAdd = rest.openEntryModal;
    } else if (Component === VehicleListView) {
        viewProps.onAdd = rest.openVehicleModal;
        viewProps.onEdit = rest.openVehicleModal; // VehicleView expects onEdit(vehicle)
    } else if (Component === OrdersView) {
        viewProps.onAdd = rest.openOrderModal;
        viewProps.onEdit = rest.openOrderModal;
    }

    return <Component {...viewProps} />;
};

const App = () => (
    <QueryClientProvider client={queryClient}>
        <BrowserRouter>
            <Layout>
                <Routes>
                    <Route path="/" element={<RouteWrapper Component={DashboardView} />} />
                    <Route path="/vehicles" element={<RouteWrapper Component={VehicleListView} />} />
