import React, { useContext } from 'react';
import { createRoot } from 'react-dom/client';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';

// Components
import { Layout, FleetContext } from './components/Layout';

// Views
import { DashboardView } from './views/DashboardView';
import { VehicleListView, CombinationsView } from './views/VehicleView';
import { AppointmentsView, OrdersView } from './views/PlanningView';
import { HistoryView, AdminView } from './views/ReportView';
import { AnalysisView } from './views/AnalysisView';

// --- SETUP QUERY CLIENT ---
const queryClient = new QueryClient({
    defaultOptions: {
        queries: {
            retry: 1,
            refetchOnWindowFocus: false,
        }
    }
});

/**
 * RouteWrapper
 * Helper component to bridge the Layout's props to the View via Context.
 */
const RouteWrapper = (props: any) => {
    const { Component } = props;
    const context = useContext(FleetContext);

    // Safety check: If context is null (e.g. during initial render before provider is ready, or if misplaced),
    // return a fallback or render with empty props to prevent crash, but usually Provider ensures this doesn't happen unless error.
    if (!context) return null; 

    // Map generic props to specific view handlers if necessary
    // We start with context as base props
    let viewProps = { ...context };

    if (Component === DashboardView) {
        viewProps.onAdd = context.openEntryModal;
    } else if (Component === VehicleListView) {
        viewProps.onAdd = context.openVehicleModal;
        viewProps.onEdit = context.openVehicleModal; // VehicleView expects onEdit(vehicle)
    } else if (Component === OrdersView) {
        viewProps.onAdd = context.openOrderModal;
        viewProps.onEdit = context.openOrderModal;
    }

    return <Component {...viewProps} />;
};

const App = () => (
    <QueryClientProvider client={queryClient}>
        <BrowserRouter>
            <Layout>
                <Routes>
                    <Route path="/" element={<RouteWrapper Component={DashboardView} />} />
                    <Route path="/vehicles" element={<RouteWrapper Component={VehicleListView} />} />
                    <Route path="/combinations" element={<RouteWrapper Component={CombinationsView} />} />
                    <Route path="/appointments" element={<RouteWrapper Component={AppointmentsView} />} />
                    <Route path="/orders" element={<RouteWrapper Component={OrdersView} />} />
                    <Route path="/history" element={<RouteWrapper Component={HistoryView} isAdmin={true} />} />
                    <Route path="/analysis" element={<RouteWrapper Component={AnalysisView} />} />
                    <Route path="/admin" element={<AdminView />} />
                    <Route path="*" element={<Navigate to="/" replace />} />
                </Routes>
            </Layout>
        </BrowserRouter>
    </QueryClientProvider>
);

const container = document.getElementById('root');
const root = createRoot(container!);
root.render(<App />);

import { useState, useMemo } from 'react';
import { LogEntry, Vehicle, VehicleType, Priority } from '../types';
import { generateVirtualInspections, getPrioritySortValue, getVehicleTypePriority } from '../utils';

export const useDashboardPresenter = (logs: LogEntry[], vehicles: Vehicle[]) => {
    const safeVehicles = Array.isArray(vehicles) ? vehicles : [];
    const safeLogs = Array.isArray(logs) ? logs : [];

    const [showCompleted, setShowCompleted] = useState(false);
    const [sortMode, setSortMode] = useState<'priority' | 'type' | 'license'>('priority');
    const [filters, setFilters] = useState({ licensePlate: '', type: '', priority: '', category: '' });

    // 1. Generate Virtual Inspections
    const generatedInspections: LogEntry[] = useMemo(() => generateVirtualInspections(safeVehicles), [safeVehicles]);

    // 2. Filter Logs
    const filteredLogs = useMemo(() => {
        const allItems = [...safeLogs, ...generatedInspections];
        return allItems.filter((l: LogEntry) => {
            if (!showCompleted && l.status === 'DONE') return false;
            const vehicle = safeVehicles.find((v:Vehicle) => v.id === l.vehicleId);
            const licensePlate = vehicle?.licensePlate || 'Allgemein';
            const type = vehicle?.type || 'Sonstige';

            if (filters.licensePlate && !licensePlate.toLowerCase().includes(filters.licensePlate.toLowerCase())) return false;
            if (filters.type && type !== filters.type) return false;
            if (filters.priority && l.priority !== filters.priority) return false;
            if (filters.category === 'inspection' && (!l.inspectionType && l.type !== 'Wartung' && l.type !== 'Prüfung')) return false;
            if (filters.category === 'task' && (l.inspectionType || l.type === 'Wartung' || l.type === 'Prüfung')) return false;
            return true;
        });
    }, [safeLogs, generatedInspections, safeVehicles, showCompleted, filters]);

    // 3. Group Logs by Vehicle
    const groupedLogs = useMemo(() => {
        const groups: { [key: string]: LogEntry[] } = {};
        filteredLogs.forEach((log: LogEntry) => {
            const key = log.vehicleId || 'unknown';
            if (!groups[key]) groups[key] = [];
            groups[key].push(log);
        });
        Object.keys(groups).forEach(key => {
            groups[key].sort((a, b) => {
                const statusOrder = { 'IN_PROGRESS': 0, 'OPEN': 1, 'DONE': 2 };
                // @ts-ignore
                if (statusOrder[a.status] !== undefined && statusOrder[b.status] !== undefined && a.status !== b.status) {
                     // @ts-ignore
                     return statusOrder[a.status] - statusOrder[b.status];
                }
                const pA = getPrioritySortValue(a.priority);
                const pB = getPrioritySortValue(b.priority);
                if (pA !== pB) return pA - pB;
                return (a.dateAdded || '').localeCompare(b.dateAdded || '');
            });
        });
        return groups;
    }, [filteredLogs]);

    // 4. Sort Groups
    const sortedGroupKeys = useMemo(() => {
        const keys = Object.keys(groupedLogs);
        return keys.sort((a, b) => {
            const vA = safeVehicles.find((v:Vehicle) => v.id === a);
            const vB = safeVehicles.find((v:Vehicle) => v.id === b);

            if (sortMode === 'priority') {
                const minPrio = (tasks: LogEntry[]) => tasks.length === 0 ? 99 : Math.min(...tasks.map(t => getPrioritySortValue(t.priority)));
                const pA = minPrio(groupedLogs[a]), pB = minPrio(groupedLogs[b]);
                if (pA !== pB) return pA - pB;
                return (vA?.licensePlate || 'ZZ').localeCompare(vB?.licensePlate || 'ZZ');
            } else if (sortMode === 'type') {
                const pA = getVehicleTypePriority(vA?.type || 'Sonstige'), pB = getVehicleTypePriority(vB?.type || 'Sonstige');
                if (pA !== pB) return pA - pB;
                return (vA?.licensePlate || 'ZZ').localeCompare(vB?.licensePlate || 'ZZ');
            } else {
                return (vA?.licensePlate || 'ZZ').localeCompare(vB?.licensePlate || 'ZZ');
            }
        });
    }, [groupedLogs, safeVehicles, sortMode]);

    return {
        // State
        showCompleted, setShowCompleted,
        sortMode, setSortMode,
        filters, setFilters,

        // Data
        safeVehicles,
        groupedLogs,
        sortedGroupKeys,

        // Helpers
        isEmpty: sortedGroupKeys.length === 0
    };
};

