import React, { useContext } from 'react';
import { createRoot } from 'react-dom/client';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';

// Components
import { Layout } from './components/Layout';
import { FleetContext } from './components/Context';

// Views
import { DashboardView } from './views/DashboardView';
import { VehicleListView, CombinationsView } from './views/VehicleView';
import { AppointmentsView, OrdersView } from './views/PlanningView';
import { HistoryView, AdminView } from './views/ReportView';
import { AnalysisView } from './views/AnalysisView';

// --- SETUP QUERY CLIENT ---
const queryClient = new QueryClient({
    defaultOptions: {
        queries: {
            retry: 1,
            refetchOnWindowFocus: false,
        }
    }
});

/**
 * RouteWrapper
 * Helper component to bridge the Layout's props to the View via Context.
 */
const RouteWrapper = (props: any) => {
    const { Component, ...rest } = props;
    const context = useContext(FleetContext);

    // Safety check: If context is null (e.g. during initial render before provider is ready)
    if (!context) return null; 

    // We pass everything from context to props, but override specific handlers based on the View
    let viewProps = { ...context, ...rest };

    if (Component === DashboardView) {
        viewProps.onAdd = context.openEntryModal;
        viewProps.onDelete = context.actions?.deleteLog;
        viewProps.onEdit = context.openEntryModal;
    } else if (Component === VehicleListView) {
        viewProps.onAdd = context.openVehicleModal;
        viewProps.onEdit = context.openVehicleModal;
        viewProps.onDelete = context.actions?.deleteVehicle;
    } else if (Component === OrdersView) {
        viewProps.onAdd = context.openOrderModal;
        viewProps.onEdit = context.openOrderModal;
        viewProps.onDelete = context.actions?.deleteOrder;
    } else if (Component === HistoryView) {
        viewProps.onDelete = context.actions?.deleteLog;
    }

    return <Component {...viewProps} />;
};

const App = () => (
    <QueryClientProvider client={queryClient}>
        <BrowserRouter>
            <Layout>
                <Routes>
                    <Route path="/" element={<RouteWrapper Component={DashboardView} />} />
                    <Route path="/vehicles" element={<RouteWrapper Component={VehicleListView} />} />
                    <Route path="/combinations" element={<RouteWrapper Component={CombinationsView} />} />
                    <Route path="/appointments" element={<RouteWrapper Component={AppointmentsView} />} />
                    <Route path="/orders" element={<RouteWrapper Component={OrdersView} />} />
                    <Route path="/history" element={<RouteWrapper Component={HistoryView} isAdmin={true} />} />
                    <Route path="/analysis" element={<RouteWrapper Component={AnalysisView} />} />
                    <Route path="/admin" element={<AdminView />} />
                    <Route path="*" element={<Navigate to="/" replace />} />
                </Routes>
            </Layout>
        </BrowserRouter>
    </QueryClientProvider>
);

const container = document.getElementById('root');
const root = createRoot(container!);
root.render(<App />);

import { Vehicle, Priority, VehicleType, LogEntry } from './types';

export const getTodayDate = () => new Date().toISOString().split('T')[0];
export const isValidDateMMYYYY = (val: string) => /^\d{2}\/\d{4}$/.test(val);

// Convert "MM/YYYY" (Storage) to "YYYY-MM" (Input type="month")
export const toInputFormat = (dateStr?: string) => {
    if (!dateStr) return '';
    const [m, y] = dateStr.split('/');
    if (!m || !y) return '';
    return `${y}-${m}`;
};

// Convert "YYYY-MM" (Input type="month") to "MM/YYYY" (Storage)
export const fromInputFormat = (dateStr: string) => {
    if (!dateStr) return '';
    const [y, m] = dateStr.split('-');
    return `${m}/${y}`;
};

export const parseDateMMYYYY = (dateStr?: string) => {
    if (!dateStr) return 0;
    const parts = dateStr.split('/');
    if (parts.length < 2) return 0;
    const [m, y] = parts;
    if (!m || !y) return 0;
    return new Date(parseInt(y), parseInt(m)-1).getTime();
};

export const getVehicleTypePriority = (type: string | any) => {
    switch(type) {
        case VehicleType.LKW: return 1;
        case VehicleType.TRANSPORTER: return 2;
        case VehicleType.PKW: return 3;
        case VehicleType.ANHAENGER: return 4;
        case VehicleType.AUFLIEGER: return 5;
        case VehicleType.MASCHINE: return 6;
        case VehicleType.SONSTIGE: return 7;
        default: return 99;
    }
}

export const getPrioritySortValue = (p: string | Priority) => {
    if (p === Priority.HIGH || (typeof p === 'string' && p.includes('Dringend'))) return 0;
    if (p === Priority.LOW || (typeof p === 'string' && p.includes('Niedrig'))) return 2;
    return 1; // Normal
};

export const getBadgeColor = (type: string) => {
    switch(type) {
        case 'HU': return 'bg-rose-100 text-rose-800 border-rose-200';
        case 'SP': return 'bg-orange-100 text-orange-800 border-orange-200';
        case 'UVV': return 'bg-blue-100 text-blue-800 border-blue-200';
        case 'Tacho': return 'bg-purple-100 text-purple-800 border-purple-200';
        default: return 'bg-gray-100 text-gray-800';
    }
};

export const sortVehicles = (vehicles: Vehicle[]) => {
  return [...vehicles].sort((a, b) => {
    if (a.type !== b.type) {
        return getVehicleTypePriority(a.type) - getVehicleTypePriority(b.type);
    }
    return a.licensePlate.localeCompare(b.licensePlate);
  });
};

export const groupVehiclesByType = (vehicles: Vehicle[]) => {
    const sorted = sortVehicles(vehicles);
    const groups: { [key: string]: Vehicle[] } = {};
    sorted.forEach(v => {
        const typeKey = String(v.type);
        if(!groups[typeKey]) groups[typeKey] = [];
        groups[typeKey].push(v);
    });
    return groups;
}

// Generates virtual log entries for overdue inspections
export const generateVirtualInspections = (vehicles: Vehicle[]): LogEntry[] => {
    const today = new Date();
    const currentMonthStr = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}`; // YYYY-MM

    const virtual: LogEntry[] = [];

    vehicles.forEach((v: Vehicle) => {
        const check = (type: 'HU'|'SP'|'UVV'|'Tacho', dateStr?: string) => {
            if (!dateStr || typeof dateStr !== 'string') return;
            // dateStr is MM/YYYY
            const parts = dateStr.split('/');
            if (parts.length < 2) return;
            const [m, y] = parts;
            if (!m || !y) return;

            const iso = `${y}-${m.padStart(2, '0')}`; // YYYY-MM

            let priority = Priority.NORMAL;
            // If strictly less than current month -> Overdue -> High Priority
            if (iso < currentMonthStr) priority = Priority.HIGH;
            // If equal to current month -> Normal Priority
            else if (iso === currentMonthStr) priority = Priority.NORMAL;
            else return; // Future

            virtual.push({
                id: `virt_${v.id}_${type}_${dateStr}`, // Unique ID
                vehicleId: v.id,
                type: 'Prüfung',
                description: `${type} Fällig (${dateStr})`,
                priority: priority,
                dateAdded: getTodayDate(), 
                status: 'OPEN',
                inspectionType: type,
                isVirtual: true // Flag to handle click differently
            });
        };

        check('HU', v.nextHU);
        check('SP', v.nextSP);
        check('UVV', v.nextUVV);
        check('Tacho', v.nextTacho);
    });

    return virtual;
}

import { useState, useMemo } from 'react';
import { Vehicle, Order, OrderStatus } from '../types';
import { getTodayDate, getPrioritySortValue, parseDateMMYYYY } from '../utils';

export const useAppointmentsPresenter = (vehicles: Vehicle[]) => {
    const [selectedMonth, setSelectedMonth] = useState(getTodayDate().substring(0, 7));
    const safeVehicles = Array.isArray(vehicles) ? vehicles : [];

    const appointments = useMemo(() => {
        const list: any[] = [];
        safeVehicles.forEach((v: Vehicle) => {
            if (v.nextHU) list.push({ id: v.id + 'HU', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'HU', date: v.nextHU });
            if (v.nextSP) list.push({ id: v.id + 'SP', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'SP', date: v.nextSP });
            if (v.nextUVV) list.push({ id: v.id + 'UVV', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'UVV', date: v.nextUVV });
            if (v.nextTacho) list.push({ id: v.id + 'Tacho', vid: v.id, license: v.licensePlate, vehicleType: v.type, inspectionType: 'Tacho', date: v.nextTacho });
        });
        return list.sort((a, b) => {
            // Use safe parse utility to avoid NaNs or errors during sort
            const timeA = parseDateMMYYYY(a.date);
            const timeB = parseDateMMYYYY(b.date);
            return timeA - timeB;
        });
    }, [safeVehicles]);

    const { overdue, dueThisMonth, upcomingGrouped } = useMemo(() => {
        const ov: any[] = [], curr: any[] = [], up: any[] = [];
        appointments.forEach(apt => {
            if (!apt.date || typeof apt.date !== 'string') return;
            const parts = apt.date.split('/');
            if (parts.length < 2) return;
            const [m, y] = parts;

            const aptIso = `${y}-${m.padStart(2, '0')}`;
            if (aptIso < selectedMonth) ov.push({...apt, isOverdue: true});
            else if (aptIso === selectedMonth) curr.push({...apt, isOverdue: false});
            else up.push(apt);
        });
        const groups: Record<string, any[]> = {};
        up.forEach(apt => { if(!groups[apt.date]) groups[apt.date] = []; groups[apt.date].push(apt); });
        return { overdue: ov, dueThisMonth: curr, upcomingGrouped: groups };
    }, [appointments, selectedMonth]);

    return {
        selectedMonth, setSelectedMonth,
        overdue, dueThisMonth, upcomingGrouped
    };
};

export const useOrdersPresenter = (orders: Order[], vehicles: Vehicle[]) => {
    const safeVehicles = Array.isArray(vehicles) ? vehicles : [];
    const [showCompleted, setShowCompleted] = useState(false);

    const filteredOrders = useMemo(() => {
        return orders.filter((o: Order) => {
            if (!showCompleted && o.status === OrderStatus.ERLEDIGT) return false;
            return true;
        }).sort((a: Order, b: Order) => {
            const vA = safeVehicles.find((v:Vehicle) => v.id === a.vehicleId);
            const vB = safeVehicles.find((v:Vehicle) => v.id === b.vehicleId);
            const plateCompare = (vA?.licensePlate || 'ZZZ').localeCompare(vB?.licensePlate || 'ZZZ');
            if (plateCompare !== 0) return plateCompare;
            return getPrioritySortValue(a.description) - getPrioritySortValue(b.description);
        });
    }, [orders, safeVehicles, showCompleted]);

    return {
        showCompleted, setShowCompleted,
        filteredOrders,
        safeVehicles // Expose for rendering usage if needed
    };
};

