const mockDB = {
    init: () => {
        // Seed demo data if completely empty (for better preview experience)
        if (!localStorage.getItem('fuhrpark_vehicles')) {
            console.log("Seeding Demo Data for Preview...");
            localStorage.setItem('fuhrpark_vehicles', JSON.stringify(DEMO_VEHICLES));
            localStorage.setItem('fuhrpark_logs', JSON.stringify(DEMO_LOGS));
            localStorage.setItem('fuhrpark_orders', '[]');
        }
    },
    load: (key: string) => {
        try {
            const data = localStorage.getItem(`fuhrpark_${key}`);
            return data ? JSON.parse(data) : [];
        } catch (e) {
            console.error("MockDB Load Error", e);
            return [];
        }
    },
    save: (key: string, data: any) => localStorage.setItem(`fuhrpark_${key}`, JSON.stringify(data)),

    async get(collection: string) {
      // Initialize on first access
      this.init();
      return this.load(collection);
    },
    async post(collection: string, item: any) {
      this.init();
      const items = this.load(collection);
      const newItem = { ...item, id: Math.random().toString(36).substr(2, 9) };
      items.push(newItem);
      this.save(collection, items);
      return { success: true, id: newItem.id };
    },
    async put(collection: string, id: string, item: any) {
      this.init();
      const items = this.load(collection);
      const idx = items.findIndex((i:any) => i.id === id);
      if (idx !== -1) {
        items[idx] = item;
        this.save(collection, items);
      } else {
        // Create if not exists (upsert behavior)
        items.push(item);
        this.save(collection, items);
      }
      return { success: true };
    },
    async delete(collection: string, id: string) {
      this.init();
      const items = this.load(collection);
      const filtered = items.filter((i:any) => i.id !== id);
      this.save(collection, filtered);
      return { success: true };
    }
};

let isOfflineMode = false;

export const getIsOfflineMode = () => isOfflineMode;

export const api = {
    request: async (method: string, endpoint: string, data: any = null) => {
        // Extract collection (e.g., "vehicles") and optional ID
        const parts = endpoint.split('/').filter(Boolean);
        // Handle routes like /admin/logs or /vehicles
        const collection = parts[0] === 'admin' ? 'logs' : parts[0]; 
        const id = parts[1];

        // 1. FAST PATH: If already offline, use MockDB immediately
        if (isOfflineMode) {
            // @ts-ignore
            if (method === 'GET') return mockDB.get(collection);
            // @ts-ignore
            if (method === 'POST') return mockDB.post(collection, data);
            // @ts-ignore
            if (method === 'PUT') return mockDB.put(collection, id, data);
            // @ts-ignore
            if (method === 'DELETE') return mockDB.delete(collection, id);
            return [];
        }

        // 2. NETWORK ATTEMPT with Timeout
        // In preview/WebContainer, backend might not run. We fail fast (2s).
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 2000);

        try {
            const opts: any = { 
                method, 
                headers: { 'Content-Type': 'application/json' },
                signal: controller.signal
            };
            if (data) opts.body = JSON.stringify(data);

            const res = await fetch(`/api${endpoint}`, opts);
            clearTimeout(timeoutId);

            if (!res.ok) throw new Error(`API Error: ${res.status}`);
            return await res.json();

        } catch (e) {
            clearTimeout(timeoutId);

            // Only warn once to keep console clean
            if (!isOfflineMode) {
                console.warn('Backend unavailable or timed out (Preview Mode active). Switching to LocalStorage.');
                isOfflineMode = true;
            }

            // 3. FALLBACK: Recursively call self, which will now hit the "FAST PATH" above
            return api.request(method, endpoint, data);
        }
    },

    get: (url: string) => api.request('GET', url),
    post: (url: string, data: any) => api.request('POST', url, data),
    put: (url: string, data: any) => api.request('PUT', url, data),
    delete: (url: string) => api.request('DELETE', url)
};

/**
 * @file server.js
 * @description Main Application Entry Point
 * ROBUST VERSION: Handles missing sqlite3 for preview environments.
 */

const express = require('express');
const path = require('path');
const fs = require('fs');

const app = express();
const PORT = process.env.PORT || 3000;

// --- DATABASE SETUP WITH FALLBACK ---
let db = null;
let dbError = null;

// Ensure persistent data directory exists
const dataDir = path.join(__dirname, 'data');
if (!fs.existsSync(dataDir)) {
  try { fs.mkdirSync(dataDir); } catch(e) {}
}

try {
  const sqlite3 = require('sqlite3').verbose();
  const dbPath = path.join(dataDir, 'fuhrpark.db');
  db = new sqlite3.Database(dbPath, (err) => {
    if (err) {
      console.error('Error opening database', err);
      dbError = err;
    } else {
      console.log('Connected to SQLite database at', dbPath);
      initDB();
    }
  });
} catch (e) {
  console.warn("WARNING: sqlite3 module not found or failed to load. Server will run in STATIC ONLY mode.");
  console.warn("This is expected in web-based preview environments.");
  dbError = e;
}

// Database Helper Wrappers
const run = (sql, params = []) => new Promise((resolve, reject) => {
  if (!db) return reject(new Error("Database not available"));
  db.run(sql, params, function (err) {
    if (err) reject(err);
    else resolve(this);
  });
});

const all = (sql, params = []) => new Promise((resolve, reject) => {
  if (!db) return reject(new Error("Database not available"));
  db.all(sql, params, (err, rows) => {
    if (err) reject(err);
    else resolve(rows);
  });
});

function initDB() {
  db.serialize(() => {
    db.run(`CREATE TABLE IF NOT EXISTS vehicles (
      id TEXT PRIMARY KEY, licensePlate TEXT, type TEXT, manufacturer TEXT, model TEXT, vin TEXT, year INTEGER, notes TEXT, coupledVehicleId TEXT, nextHU TEXT, nextSP TEXT, nextUVV TEXT, nextTacho TEXT, currentMileage INTEGER
    )`);
    db.run(`CREATE TABLE IF NOT EXISTS logs (
      id TEXT PRIMARY KEY, vehicleId TEXT, type TEXT, description TEXT, priority TEXT, dateAdded TEXT, dateCompleted TEXT, status TEXT, mileage INTEGER, inspectionType TEXT, attachments TEXT
    )`);
    try { db.run("ALTER TABLE logs ADD COLUMN attachments TEXT", () => {}); } catch(e){}

    db.run(`CREATE TABLE IF NOT EXISTS orders (
      id TEXT PRIMARY KEY, description TEXT, vehicleId TEXT, dateAdded TEXT, status TEXT, supplier TEXT
    )`);
    try { db.run("ALTER TABLE orders ADD COLUMN supplier TEXT", () => {}); } catch(e){}

    db.run(`CREATE TABLE IF NOT EXISTS repairs (
      id TEXT PRIMARY KEY, vehicleId TEXT, date TEXT, type TEXT, description TEXT, performer TEXT, cost REAL, mileage INTEGER, invoiceData TEXT
    )`);
    db.run(`CREATE TABLE IF NOT EXISTS system_logs (
      id INTEGER PRIMARY KEY AUTOINCREMENT, timestamp TEXT, level TEXT, source TEXT, message TEXT, details TEXT
    )`);
  });
}

const logEvent = async (level, source, message, details = '') => {
  if (!db) return;
  const timestamp = new Date().toISOString();
  try {
    await run(`INSERT INTO system_logs (timestamp, level, source, message, details) VALUES (?, ?, ?, ?, ?)`,
      [timestamp, level, source, message, typeof details === 'object' ? JSON.stringify(details) : details]);
