let isOfflineMode = true;

// Attempt to detect backend in background
setTimeout(async () => {
    try {
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), 1000);
        const res = await fetch('/api/vehicles', { method: 'HEAD', signal: controller.signal });
        clearTimeout(timeout);
        if (res.ok || res.status === 503) {
            // Even if 503 (DB missing), the server is there, so we could switch to online logic
            // But if 503, our API wrapper handles it by staying offline.
            // If 200, we switch to online.
            if (res.status === 200) {
                console.log("Backend detected. Switching to Online Mode.");
                isOfflineMode = false;
            }
        }
    } catch(e) {
        // console.log("Backend check failed, staying offline");
    }
}, 500);

