        } catch (e) {
            // 3. FAILOVER
            if (!isOfflineMode) {
                console.warn('Backend unavailable (Network/Proxy Error). Switching to Offline Mode.');
                isOfflineMode = true;
            }
            // Retry immediately against mockDB
            return api.request(method, endpoint, data);
