// --- LOCAL STORAGE MOCK DB ---
const mockDB = {
    init: () => {
        try {
            if (!localStorage.getItem('fuhrpark_vehicles')) {
                console.log("Seeding Demo Data for Preview...");
                localStorage.setItem('fuhrpark_vehicles', JSON.stringify(DEMO_VEHICLES));
                localStorage.setItem('fuhrpark_logs', JSON.stringify(DEMO_LOGS));
                localStorage.setItem('fuhrpark_orders', '[]');
            }
        } catch(e) { console.error("LocalStorage access failed", e); }
    },
    load: (key: string) => {
        try {
            const data = localStorage.getItem(`fuhrpark_${key}`);
            return data ? JSON.parse(data) : [];
        } catch (e) {
            console.error("MockDB Load Error", e);
            return [];
        }
    },
    save: (key: string, data: any) => {
        try { localStorage.setItem(`fuhrpark_${key}`, JSON.stringify(data)); } catch(e){}
    },
    async get(collection: string) { this.init(); return this.load(collection); },
    async post(collection: string, item: any) {
      this.init();
      const items = this.load(collection);
      const newItem = { ...item, id: Math.random().toString(36).substr(2, 9) };
      items.push(newItem);
      this.save(collection, items);
      return { success: true, id: newItem.id };
    },
    async put(collection: string, id: string, item: any) {
      this.init();
      const items = this.load(collection);
      const idx = items.findIndex((i:any) => i.id === id);
      if (idx !== -1) items[idx] = item; else items.push(item);
      this.save(collection, items);
      return { success: true };
    },
    async delete(collection: string, id: string) {
      this.init();
      const items = this.load(collection);
      this.save(collection, items.filter((i:any) => i.id !== id));
      return { success: true };
    }
};

// Default to Offline to prevent waiting
let isOfflineMode = true;

// Check connectivity in background
setTimeout(async () => {
    try {
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), 2000);
        // We now have a specific health endpoint
        const res = await fetch('/api/health', { signal: controller.signal });
        clearTimeout(timeout);
        if (res.ok) {
            const data = await res.json();
            // Only switch to online if DB is actually ready
            if (data.db === true) {
                console.log("Backend & DB Online. Switching mode.");
                isOfflineMode = false;
            }
        }
    } catch(e) { /* Stay offline */ }
}, 1000);

export const getIsOfflineMode = () => isOfflineMode;

export const api = {
    request: async (method: string, endpoint: string, data: any = null) => {
        const parts = endpoint.split('/').filter(Boolean);
        const collection = parts[0] === 'admin' ? 'logs' : parts[0]; 
        const id = parts[1];

        if (isOfflineMode) {
            // @ts-ignore
            if (method === 'GET') return mockDB.get(collection);
            // @ts-ignore
            if (method === 'POST') return mockDB.post(collection, data);
            // @ts-ignore
            if (method === 'PUT') return mockDB.put(collection, id, data);
            // @ts-ignore
            if (method === 'DELETE') return mockDB.delete(collection, id);
            return [];
        }

        try {
            const controller = new AbortController();
            const timeoutId = setTimeout(() => controller.abort(), 3000); 

            const opts: any = { 
                method, 
                headers: { 'Content-Type': 'application/json' },
                signal: controller.signal
            };
            if (data) opts.body = JSON.stringify(data);

            const res = await fetch(`/api${endpoint}`, opts);
            clearTimeout(timeoutId);

            // 503 means Server is up but DB is down -> Force Offline for this request (and maybe globally?)
            if (res.status === 503) {
                 // isOfflineMode = true; // Optionally switch globally
                 throw new Error("DB_OFFLINE");
            }

            const contentType = res.headers.get("content-type");
            if (!contentType || !contentType.includes("application/json")) {
                 throw new Error("INVALID_RESPONSE");
            }
            if (!res.ok) throw new Error(`API Error: ${res.status}`);
            return await res.json();

        } catch (e) {
            // Failover to MockDB
            return api.request(method, endpoint, data); // Recursive call will hit isOfflineMode check? No, we need to force it.
        }
    },

    get: (url: string) => api.request('GET', url),
    post: (url: string, data: any) => api.request('POST', url, data),
    put: (url: string, data: any) => api.request('PUT', url, data),
    delete: (url: string) => api.request('DELETE', url)
};

