// Complete Task: Atomic update of Log AND Vehicle Mileage
app.post('/api/actions/complete-task', (req, res) => handle(async () => {
    const { logId, mileage, dateCompleted } = req.body;

    // We use db.serialize to ensure sequential execution (basic transaction behavior in node-sqlite3)
    // For strict ACID, we use BEGIN/COMMIT manually.
    const runTransaction = async () => {
        return new Promise((resolve, reject) => {
            db.serialize(async () => {
                try {
                    await run("BEGIN TRANSACTION");

                    // 1. Get the log to find the vehicleId
                    const log = await get("SELECT vehicleId FROM logs WHERE id = ?", [logId]);
                    if (!log) throw new Error("Log not found");

                    // 2. Update the Log Entry
                    await run("UPDATE logs SET status = 'DONE', dateCompleted = ?, mileage = ? WHERE id = ?", [dateCompleted, mileage, logId]);

                    // 3. Update Vehicle Mileage (only if new is higher)
                    if (log.vehicleId) {
                         // Read current mileage first
                         const vehicle = await get("SELECT currentMileage FROM vehicles WHERE id = ?", [log.vehicleId]);
                         const current = vehicle ? (vehicle.currentMileage || 0) : 0;

                         if (mileage > current) {
                             await run("UPDATE vehicles SET currentMileage = ? WHERE id = ?", [mileage, log.vehicleId]);
                         }
                    }

                    await run("COMMIT");
                    resolve();
                } catch (e) {
                    await run("ROLLBACK");
                    reject(e);
                }
            });
        });
    };

    await runTransaction();
    res.json({ success: true });
}, res));

// Complete Inspection: Atomic update of Log AND Vehicle Due Date
app.post('/api/actions/complete-inspection', (req, res) => handle(async () => {
    const { logId, nextDate, dateCompleted, vehicleId, inspectionType, description } = req.body;
    // nextDate format expected: YYYY-MM
    // DB format expected: MM/YYYY

    const runTransaction = async () => {
        return new Promise((resolve, reject) => {
            db.serialize(async () => {
                try {
                    await run("BEGIN TRANSACTION");

                    // 1. If it was a real log entry, mark it done. If virtual, we skip this or create a new done entry.
                    // The frontend sends logId. If it starts with 'virt_', we create a new entry.
                    if (!logId.startsWith('virt_')) {
                        await run("UPDATE logs SET status = 'DONE', dateCompleted = ? WHERE id = ?", [dateCompleted, logId]);
                    } else {
                        // Create a history entry for the virtual inspection
                        const newId = Math.random().toString(36).substr(2, 9);
                        await run(`INSERT INTO logs VALUES (?,?,?,?,?,?,?,?,?,?,?)`, 
                            [newId, vehicleId, 'Wartung', description, 'Normal', dateCompleted, dateCompleted, 'DONE', 0, inspectionType, '[]']);
                    }

                    // 2. Update Vehicle Next Date
                    if (vehicleId && inspectionType && nextDate) {
                        const [year, month] = nextDate.split('-');
                        const dbDate = `${month}/${year}`;

                        // Dynamically build query based on type
                        const validTypes = ['HU', 'SP', 'UVV', 'Tacho'];
                        if (validTypes.includes(inspectionType)) {
                            await run(`UPDATE vehicles SET next${inspectionType} = ? WHERE id = ?`, [dbDate, vehicleId]);
                        }
                    }

                    await run("COMMIT");
                    resolve();
                } catch (e) {
                    await run("ROLLBACK");
                    reject(e);
                }
            });
        });
    };

    await runTransaction();
    res.json({ success: true });
}, res));


