import React from 'react';
import { NavLink, useLocation } from 'react-router-dom';
import { Icons } from '../icons';
import { getIsOfflineMode } from '../api';
import { useQueryClient } from '@tanstack/react-query';

const NavItem = ({ to, icon, label }: { to: string; icon: React.ReactNode; label: string }) => {
  return (
    <NavLink
      to={to}
      className={({ isActive }) =>
        `w-full flex items-center gap-3 px-4 py-3 rounded transition-colors font-medium ${
          isActive ? 'bg-blue-600 text-white shadow-md' : 'text-slate-300 hover:bg-slate-700 hover:text-white'
        }`
      }
    >
      {icon}
      <span>{label}</span>
    </NavLink>
  );
};

export const Layout = ({ children, title }: { children?: React.ReactNode; title: string }) => {
  const queryClient = useQueryClient();

  const handleRefresh = () => {
    queryClient.invalidateQueries();
  };

  return (
    <div className="flex h-full bg-gray-100 font-sans text-gray-900">
      {/* Sidebar */}
      <div className="w-64 bg-slate-800 text-white flex flex-col shadow-xl z-10 no-print">
        <div className="p-6 border-b border-slate-700">
          <h1 className="text-xl font-bold tracking-tight">
            Fuhrpark<span className="text-blue-400">Manager</span>
          </h1>
        </div>
        <nav className="flex-1 p-4 space-y-2">
          <NavItem to="/" icon={<Icons.Dashboard />} label="ToDo" />
          <NavItem to="/appointments" icon={<Icons.Calendar />} label="Termine" />
          <NavItem to="/orders" icon={<Icons.ShoppingCart />} label="Bestellungen" />
          <NavItem to="/history" icon={<Icons.History />} label="Historie" />
          <NavItem to="/analysis" icon={<Icons.Chart />} label="Auswertung" />
          <NavItem to="/combinations" icon={<Icons.Link />} label="Gespanne" />
          <NavItem to="/vehicles" icon={<Icons.Truck />} label="Fahrzeuge" />
          <div className="pt-4 mt-4 border-t border-slate-700">
            <NavItem to="/admin" icon={<Icons.Database />} label="Admin" />
          </div>
        </nav>
        <div className="p-4 border-t border-slate-700 text-xs text-slate-400">
          v2.5.0 • {getIsOfflineMode() ? 'Offline Mode' : 'Online'}
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col h-full overflow-hidden">
        <header className="bg-white shadow-sm border-b px-8 py-4 flex justify-between items-center no-print">
          <h2 className="text-xl font-bold text-gray-800 capitalize">{title}</h2>
          <button
            onClick={handleRefresh}
            className="p-2 text-gray-500 hover:bg-gray-100 rounded"
            title="Daten aktualisieren"
          >
            <Icons.History />
          </button>
        </header>

        <main className="flex-1 overflow-auto p-8">
            {children}
        </main>
      </div>
    </div>
  );
};
